window.__D("text/torat-shmuel/c044",{"p":[[2000470462,"<h3>אז ישיר משה</h3>\n<b></b><b>יום שביעי ש\"פ תר\"ם לפ\"ק</b>\nיום שביעי ש\"פ\n<b>אז</b> ישיר משה<sup data-n=\"4280\">1</sup> ובנ\"י את השירה הזאת ויאמרו לאמר<sup data-n=\"4281\">2</sup>, הנה השירה הזאת היא שירה של בחי' מל'<sup data-n=\"4282\">3</sup> וכמ\"ש למען יזמרך כבוד<sup data-n=\"4283\">4</sup> ולא ידום נהו\"ת קארי תדיר<sup data-n=\"4284\">5</sup> לנהו\"ע ולא שכיך וכמ\"ש אלקים אל דמי לך ואל תחרוש<sup data-n=\"4285\">6</sup> ואל תשקוט אל, ומשה ובנ\"י שרו השירה הזאת. וצ\"ל אם תחילה הי' שירה דמשה ובנ\"י ואח\"כ השירה הזאת, או שתחלה הי' השירה הזאת ואח\"כ השירה דמשה ובנ\"י. וה\"ז ב' פי' בפסוק, וצ\"ל תחילה הפי' הא' שתחילה הי' השירה דמשה ובנ\"י ואח\"כ השירה הזאת, והענין דהנה נת\"ל<sup data-n=\"4286\">7</sup> דשרש האותיות הם מח\"ע וס\"ר נש\"י<sup data-n=\"4287\">8</sup> הם נגד ס\"ר אותיות התורה<sup data-n=\"4288\">9</sup> אשר כל נשמה כללות<sup data-n=\"4289\">11</sup> יש לה אות בתורה<sup data-n=\"4290\">10</sup> ולכן כאו\"א מנש\"י יש לו כליון ותשוקה לאלקות מפני שכל דבר נמשך לשרשו<sup data-n=\"4291\">12</sup> (הראשון).",[["4280","1","<b>אז ישיר משה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פ\"ה-פ\"י. וש\"נ.\nהנחה זו כנראה נזכרה לקמן בהנחה ד\"ה יפה שעה א' על יד הערה 63<sup data-n=\"e251\">א</sup>. ד\"ה אני לדודי הב' על יד הערה 42<sup data-n=\"e252\">ב</sup>."],["4281","2","<b>אז ישיר משה. . לאמר</b>: בשלח טו, א [בדילוג השם]."],["4282","3","<b>השירה הזאת. . מל'</b>: ראה גם בענין השירה הזאת מאמרי אדה\"ז תקס\"ז ע' שנב ואילך."],["4283","4","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["4284","5","<b>נהו\"ת קארי תדיר</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["4285","6","<b>אלקים אל דמי לך ואל תחרוש</b>: תהלים פג, ב [ושם: אל תחרש — ראה גם לעיל הנחה ד\"ה בן פורת יוסף הא' הערה 37]."],["4286","7","<b>נת\"ל</b>: ראה הנחה ד\"ה מצה זו."],["4287","8","<b>וס\"ר נש\"י</b>: נסמן לעיל הנחה ד\"ה מצה זו הערה 26."],["4288","9","<b>ס\"ר אותיות התורה</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע אופן קפו. לקו\"ש טו\"ב כסלו תשמ\"א כרך כ ע' 419 בהערה. שו\"ת הצ\"צ חאבהע\"ז סרמ\"ט (צה, א)."],["4289","11","<b>כללות</b>: אוצ\"ל: כללית."],["4290","10","<b>כל נשמה. . אות בתורה</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רנב. וש\"נ. שה\"א צז, סע\"א ובהערה 13."],["4291","12","<b>שכל דבר נמשך לשרשו</b>: ראה גם לעיל הנחה ד\"ה מצה זו ובהערה 68.\n\n<b>א</b>  <b>ושם</b>: ”ד\"ה גן נעול, מצה זו מ\"ם\" ע\"ש בהערה.\n\n<b>ב</b>  <b>ושם</b>: ”בד\"ה גן נעול מצה זו\" ע\"ש בהערה."]]],[2000470463,"<b>וביאור</b> הענין דהנה האותיות הם נראים ונגלים כשהשכל בא לידי השגה והבנה הגם שבמשכיל יש ג\"כ אותיות, אך אינם בגילוי עדיין דכל הברק המבריק<sup data-n=\"4292\">13</sup> הוא אינו גילוי ממילא גם האותיות אינם נגלים, רק כשהשכל בא לידי השגה והבנה אז נראים ונגלים האותיות, נמצא יש ג' מדרי' איך שהוא עדיין בהעלם לגמרי, והברק המבריק הגם שיש שם אותיות אך אינם בגילוי עדיין, והשגה והבנה ששם נראים ונגלים האותיות, וע\"י לימוד התורה לשמה ממשיכים תוס' אורות בהאותיות, והעלאה והמשכה זו הוא מריש כ\"ד עד סכ\"ד, וצ\"ל האותיות מה ענינם, דהנה האותיות הם מלבישים את השכל, וא\"כ מוכרח לומר ששרש האותיות למעלה מהשכל, ויובן זה כמו משל שמלביש לשכל הרי המשל הוא דבר זר מהשכל וכמו להשמרך מאשה זרה<sup data-n=\"4293\">14</sup> הוא משל על חכ' חיצוניות ולימודיות בכלל, ראה חיים אם אשה<sup data-n=\"4294\">15</sup> אשר אהבת הוא משל לחכ' התורה, הרי דבר זר לגמרי, מ\"מ כדי שיוכל לומר משל צ\"ל בעל שכל גדול<sup data-n=\"4295\">16</sup> דיש מי שמשיג השכל בטוב ומ\"מ א\"י להמשיל משל, כי ע\"ז צריכים בעל שכל גדול וכמו משלי שלמה<sup data-n=\"4296\">17</sup> שנא' עליו ויחכם מכל אדם<sup data-n=\"4297\">18</sup> לכן הי' ביכולתו לומר משל, דהמשל הוא כמו לבוש להשכל, והלבוש צ\"ל בערך הלובש לא קטן ולא גדול, לכן צ\"ל בעל שכל גדול, וכמו ר\"מ שהי' אומר תלתא מתלי<sup data-n=\"4298\">19</sup> דאמרז\"ל לא ר\"מ שמו אלא ר' נהוראי שמו<sup data-n=\"4299\">20</sup> ולמה נק' ר\"מ מפני שהוא מנהיר עיני חכמים בהלכה שהי' בחי' מאור מקור האור<sup data-n=\"4300\">21</sup> לכן הי' אומר משל, וכמו\"כ האותיות שהם מלבישים השכלות התורה צ\"ל שרשם למעלה מהתורה, וכ\"ה האמת דהנה אורייתא מחכ' נפקת<sup data-n=\"4301\">22</sup> ושרש האותיות הם מכתר<sup data-n=\"4302\">23</sup> ולכן נק' בזהר כתרין עילאין<sup data-n=\"4303\">24</sup> ואי' בזהר נחתא כף מעל כורסייא יקרי'<sup data-n=\"4304\">25</sup>, הגם שהאותיות הם בחכ', היינו",[["4292","13","<b>דכל הברק המבריק</b>: כ\"ה בגוכתי\"ק. ראה גם בענין ברק המבריק לעיל הנחה ד\"ה כי הנה יוצר הרים ובהערה 21."],["4293","14","<b>להשמרך מאשה זרה</b>: משלי ז, ה [ושם: לשמרך]. ראה גם סה\"מ תרל\"ח ע' תפט וע' רצא."],["4294","15","<b>ראה חיים אם אשה</b>: קהלת ט, ט [ושם: עם]."],["4295","16","<b>לומר משל צ\"ל בעל שכל גדול</b>: ראה תו\"א לך יא, ג. לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 172."],["4296","17","<b>משלי שלמה</b>: משלי א, א."],["4297","18","<b>ויחכם מכל אדם</b>: מלכים-א ה, יא [ושם: האדם — ראה גם מאמרי אדה\"א בראשית ע' קלא. וש\"נ. סה\"מ תרל\"ח ע' תפט]."],["4298","19","<b>ר\"מ. . תלתא מתלי</b>: סנהדרין לח, סע\"ב. ראה תו\"א מג\"א צא, ג. מאמרי אדה\"ז תקס\"ח ח\"א שצד רע\"א. לקו\"ש וילך כרך ט ע' 202 ואילך."],["4299","20","<b>לא ר\"מ. . ר' נהוראי שמו</b>: ראה ערובין יג, ב. לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 178."],["4300","21","<b>ר\"מ. . מאור מקור האור</b>: ראה מאמרי אדה\"ז תקס\"ג ח\"א ע' יט. ע' כא. מאמרי אדה\"א במדבר ח\"ב ע' תרסה. אוה\"ת וישב כרך ו' תתרצג רע\"א. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ה. תרט\"ו ע' נב. סה\"מ תרכ\"ט ע' קעו. תרל\"ח ע' ריג."],["4301","22","<b>אורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4302","23","<b>ושרש האותיות הם מכתר</b>: ראה תו\"א מקץ מב, ב. סידור שער החנוכה ערב, סע\"ב ואילך. ד\"ח שער התפלה ס, ד. לקו\"ת חוקת נח, סע\"א ואילך. אוה\"ת יתרו ע' תשצג."],["4303","24","<b>האותיות. . נק' בזהר כתרין עילאין</b>: כ\"ה גם בתו\"א מקץ מג, א הובא לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 184."],["4304","25","<b>נחתא כף מעל כורסייא יקרי'</b>: זהר בהקדמה ג, א<sup data-n=\"e253\">ג</sup>. סה\"מ תרל\"ג ח\"א ע' ו. לעיל שם על יד הערה 185.\n\n<b>ג</b>  <b>ושם</b>: וכד נחתת כ' מעל כורסי יקרי' — ראה אוה\"ת תשא ע' א'תתקו. ושם לפנ\"ז: נחתא."]]],[2000470464,"שהם נראים ונגלים בחכ' אבל שרש האותיות הם מבחי' עדן מקדם<sup data-n=\"4305\">26</sup> שהוא בחי' כתר, ולכן כל דבר שבא לידי השגה בע' לשון הוא בא באותיות דשרש האותיות הם מבחי' קדמות השכל<sup data-n=\"4306\">27</sup>, ונק' קדמות השכ\"ל<sup data-n=\"4307\">28</sup> מפני שאח\"כ מתגלה השכל ע\"י, ותי' קדמות השכל פי' קדם לשכל, אבל לא שהאותיות מהותן שכל, אלא שהם מלבישים את השכל ולכן כמה פוסקים שאומרים שכל א' ובאותיות שונים, והיינו מפני שהם לבוש, זה מלביש בלבוש זה כו', אך שרשם למעלה מהשכל.\n<b>והנה</b> אי' בזהר<sup data-n=\"4308\">29</sup> ע\"פ לכן ישכב עמי<sup data-n=\"4309\">30</sup> בלילה ההוא<sup data-n=\"4310\">31</sup>, ישכב הוא יש כב, יש הוא השגה והבנה וכמ\"ש להנחיל אוהבי יש<sup data-n=\"4311\">32</sup>, כד<sup data-n=\"4312\">33</sup> ההוא נקודה עילאה והוא בחי' חכ' יסו\"א שמשם נמשך צורת האותיות, וזהו ישכב שהכ\"ב אותיות מגלים התענוג העליון, והנה נת\"ל<sup data-n=\"4313\">34</sup> דבג\"ע יש ב' מדרי' אור ההשכלה דיו\"ד, וכמו עשה פי' פעל בל\"א גיטאן, יעשה פי' יפעול בל\"א ער וועט טאן, ושינוי הפי' מפני שנתוסף בו אות יו\"ד, והתענוג העליון שהוא עצם אות יו\"ד, וצ\"ל איך שייך שהכ\"ב<sup data-n=\"4314\">35</sup> יגלו עצם העונג העליון שהוא עצם האות יו\"ד. ונת\"ל שהמגלה צ\"ל גבוה במדריגה מהדבר המתגלה, ואיך שייך שאותיות יגלו אותו. אך באמת יש ע\"ז כמה תירוצים (בפ\"א<sup data-n=\"4315\">36</sup> : וית\"ל אי\"ה), ובקצרה י\"ל דהנה התענוג הוא גילוי האותיות, דמה שייך לומר שהאותיות הם תענוג, אלא שהם מגלים תענוג, וידוע דכל גילוי א\"א להיות כמו שהוא בעצם וכמו כשא' משפיע שכל לזולתו א\"ז רק בחי' אחרונה<sup data-n=\"4316\">37</sup> והוא הארה לבד ועצם האותיות הם למעלה מההארה זו לכן ביכולתם לגלות, ועפ\"ז יובן ענין קרי\"ס דכתי' אז ישיר כו' דהנה כתי' למען יזמרך כבוד ולא ידום נהו\"ת קארי תדיר לנהו\"ע ולא שכיך והוא מפני שה' אלקי לעולם אודך ע\"י שיר ושבחה דנשמות.\n<b>והענין</b> דהנה כל שנת\"ל דשרש האותיות הם בקדמות השכל ה\"ז באצי' דהנה ראשית אצי' הוא מחכ' עד מל' וכתר [שהוא קוש\"י<sup data-n=\"4317\">38</sup> ] ג\"כ בכלל אצי' יחשב, אך שרש האותיות הוא מהרשימה<sup data-n=\"4318\">*39</sup>, וע\"י העלאות האותיות ממשיכים הקו",[["4305","26","<b>עדן מקדם</b>: בראשית ב, ח."],["4306","27","<b>דשרש האותיות. . קדמות השכל</b>: ראה אגה\"ק ס\"ה (קז, ב). לעיל הנחה ד\"ה כי הנה יוצר הרים הערה 23."],["4307","28","<b>ונק' קדמות השכ\"ל</b>: ראה גם לעיל הנחה ד\"ה מצה זו על יד הערה 42."],["4308","29","<b>בזהר</b>: ראה ויצא סתרי תורה קנו, סע\"ב."],["4309","30","<b>לכן ישכב עמי</b>: ויצא ל, טו [ושם: עמך]."],["4310","31","<b>בלילה ההוא</b>: ויצא ל, טז ושם: בלילה הוא ו”לסבירין\" ההוא. פסוק זה לא הובא בזהר שם. וראה לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 196."],["4311","32","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["4312","33","<b>כד</b>: אוצ\"ל: כב."],["4313","34","<b>נת\"ל</b>: בהנחה מצה זו פיסקא וזהו ביו\"ד."],["4314","35","<b>שהכ\"ב</b>: אוצ\"ל: שהכ\"ב אותיות."],["4315","36","<b>בפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4316","37","<b>דכל גילוי. . בחי' אחרונה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 198."],["4317","38","<b>וכתר [שהוא קוש\"י</b>: ראה זהר ויקרא י, ב. פרדס שער שם בן ד' שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["4318","*39","<b>שרש האותיות הוא מהרשימה</b>: ראה גם לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה ושאבתם מים הערה 124."]]],[2000470465,"ותוס' אורות בקו, ועפ\"ז יובן מ\"ש בע\"ח שיש יחוד מ\"ה וב\"ן דעתיק מני' ובי'<sup data-n=\"4319\">39</sup>, דב\"ן הוא אותיות וכמו בחי' מל' שהוא שם ב\"ן<sup data-n=\"4320\">40</sup> ה\"ה עולם הדיבור<sup data-n=\"4321\">41</sup>, וע\"י העלאות האותיות ממשיכים תוס' אורות, וביאור הענין דהנה אי' בכהאריז\"ל (בפ\"א : בזהר הרקיע<sup data-n=\"4322\">42</sup> ) פי' מאה\"ז בריש הורמנותא דמלכא<sup data-n=\"4323\">43</sup> גליף גליפו בטהירא עילאה כו' הוא הבוצינא, וזאת הבוצינא נמשך תוך הטהירא א\"ק<sup data-n=\"4324\">*44</sup> כי א\"ק מלביש הרשימה, וע\"י העלאות האותיות ממשיכים הקו אשר שורשו מת\"ת הנעלם ולמקום שנמשך הוא יסוד דנוק' וממשיכים תוס' אורות בקו מא\"ס שלפני הצמצום, ובוצינא הוא נר חזק שבו נמשך השמן (ובפ\"א : הטוב) והוא הקו, ובד\"כ הוא יחוד ת\"ת ומל' דא\"ס הנעלמים, וזהו\"ע יחוד דחו\"כ שנת' בכ\"מ ובאצי' הו\"ע יש כב. וזהו\"ע מ\"ש בע\"ח יחוד דמ\"ה וב\"ן דעתיק מני' ובי', ועפ\"ז יובן מה שיש בכח האותיות להמשיך הקו, דהרשימה הוא מה שנשאר מאוא\"ס שלפני הצמצום דאין דבר שבקדושה נעקר ממקומו לגמרי<sup data-n=\"4325\">45</sup>, וא\"כ לא נגע בו הצמצום כלל<sup data-n=\"4326\">44</sup> שאם נגע בו הצמצום לא הי' נשאר האור כמו שהוא לפני הצמצום, והקו הוא קו מצומצם<sup data-n=\"4327\">46</sup>, לכן ביכולתם<sup data-n=\"4328\">47</sup> להמשיך הקו.\n<b>אך</b> הנה נת\"ל שממשיכים תוס' אורות בקו והוא מעגול הגדול שלפני הקו, שלפני הצמצום והמגלה צ\"ל גבוה במעלה מהדבר המתגלה, והרשימה הוא לפני הצמצום, והעגול הגדול הוא ג\"כ לפני הצמצום ה\"ה שוים במעלה דלפני הצמצום אינו שייך לומר מעלה במדרי' או מטה במדרי' ואיך באפשרם לגלות אור דעגול הגדול שלפני הצמצום, אך הנה מ\"ש דהרשימו הם אותיות אינו נזכר בע\"ח, רק בעמה\"מ<sup data-n=\"4329\">48</sup> קורא הרשימה בשם אותיות, אך זה אי' בע\"ח ובכהאריז\"ל בכ\"מ כשעלה",[["4319","39","<b>יחוד מ\"ה וב\"ן דעתיק מני' ובי'</b>: ראה ע\"ח שער עתיק שי\"ב, פ\"ב. שער אנ\"ך שי\"ט, פ\"ה. שער העבורים שכ\"ח, פ\"ב. שער מ\"ן ומ\"ד דרוש ב."],["4320","40","<b>מל' שהוא שם ב\"ן</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א. הערה 14."],["4321","41","<b>מל'. . עולם הדיבור</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפב. וש\"נ."],["4322","42","<b>בזהר הרקיע</b>: ראה שם פ' בראשית ע' כ."],["4323","43","<b>בריש הורמנותא דמלכא</b>: זהר בראשית טו, א. ראה גם פלח הרמון בחוקותי ע' תמד הערה 61."],["4324","*44","<b>הטהירא א\"ק</b>: ממעל לתיבת הטהירא כתב א\"ק."],["4325","45","<b>דאין דבר שבקדושה נעקר ממקומו לגמרי</b>: ראה פרדס שער המציאות שי\"ד, פ\"א<sup data-n=\"e254\">ד</sup>. אלשיך ר\"פ לך<sup data-n=\"e255\">ה</sup>. שער הכוונות ענין ר\"ה דרוש א. ע\"ח שער תיקון הנוקבא של\"ד, פ\"ג (ושם: כנודע). שער הירח של\"ה, פ\"א. שער סדר אבי\"ע שמ\"ז, פ\"ו. מבו\"ש ש\"ו, ח\"א ד\"א. פע\"ח שער התפלה ש\"א, פ\"ז. לקו\"ת להאריז\"ל פ' וירא (ענין לוט ושתי בנותיו סח, א). לקו\"א להה\"מ סו\"ס קלט (לג, ד) או\"ת על אגדות חז\"ל קז, ג<sup data-n=\"e256\">ו</sup>. אגה\"ק ביאור לסז\"ך קמז, א. שיחת ש\"פ ויקרא תשמ\"ז."],["4326","44","<b>דהרשימה. . לא נגע בו הצמצום כלל</b>: ראה גם [ובהבא לקמן] לעיל (בחלק המאמרים) המשך מצה זו כאן פ\"ו ופ\"ז. וש\"נ."],["4327","46","<b>והקו הוא קו מצומצם</b>: ראה כהאריז\"ל שבהערה 49."],["4328","47","<b>ביכולתם</b>: אולי כתוב: בכוחם."],["4329","48","<b>דהרשימו הם אותיות אינו נזכר בע\"ח רק בעמה\"מ</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו שם הערה 217.\n\n<b>ד</b>  הובא בשל\"ה בית ה' ד, ב.\n\n<b>ה</b>  הובא באוה\"ת לך כרך ד ע' תרעה וע' תרפא ושם צויין לפרדס הנ\"ל.\n\n<b>ו</b>  ושם מציין לע\"ח שער אח\"פ."]]],[2000470466,"ברצונו הפשוט לברוא העולמות כו' סילק אורו הגדול אל הצד<sup data-n=\"4330\">49</sup> ונעשה חלל ומקו\"פ<sup data-n=\"4331\">50</sup>, ומאחר שסילק האור לצדדין כביכול ה\"ז צמצום, דבתחילה הי' אוא\"ס ממלא את כל החלל<sup data-n=\"4332\">51</sup> ואח\"כ סילק כו' א\"כ ה\"ז צמצום, הגם דהאור הוא לפני הצמצום, היינו שאינו שייך לומר תי'<sup data-n=\"4333\">52</sup> צמצום אבל עכ\"פ נגע בו הצמצום, אבל הרשימה לא נגע בו הצמצום כלל, דאם הי' נוגע בו הצמצום לא הי' נשאר האור כמו שהוא לפני הצמצום, לכן בכוחם לגלות האור דעגול הגדול שלפני הקו, הגם שנת' בחסידות דענין הצמצום ר\"ל העלם<sup data-n=\"4334\">53</sup> וזה הי' גם בהאותיות, אך מה שהי' העלם בהאותיות אין זה רק בפעולת האותיות שפעולתם הי' לגלות ועכשיו אינם מגלים אבל עצם האותיות הם על עמדם ואין זה ח\"ו כמו ענין שבה\"כ שנפרדו האותיות<sup data-n=\"4335\">54</sup> וכמו תי' ברוך שפי' ברכה או שבח בל\"א גיבענצט או גילובט<sup data-n=\"4336\">55</sup> ואח\"כ כשהי' בשבירה נפרדו האותיות הב' בפ\"ע והר' בפ\"ע כו' ה\"ז שבירה בהאותיות, וג\"ז אינו רק בצירוף האותיות אבל לא בעצם האותיות, וכאן לא הי' העלם אפי' בהצירוף רק בפעולתם, וכד דייקת בי' שפיר תבין שאפי' בפעולת<sup data-n=\"4337\">56</sup> לא הי' ג\"כ שום צמצום, דבכוחן לגלות עכשיו ג\"כ רק המניעה הוא מצד האור שנתעלם, אבל מצ\"ע היו מגלים וראי' דכשממשיכים תוס' אור בהאותיות מגלים האור הרי שיש בכוחם לגלות הרי שבפעולת האותיות לא הי' ג\"כ שום צמצום, ואף אם נא' שבפעולת האותיות הי' צמצום אבל בעצם האותיות לא נגע בהם הצמצום כלל, ובהעגול הגדול שלפני הקו עכ\"פ נגע בו הצמצום<sup data-n=\"4338\">57</sup>, ובאמת א\"צ לכ\"ז דהקושי' היא האיך האותיות מגלים האוא\"ס שלפני הצמצום, איך קודם הצמצום שהי' גילוי אוא\"ס שלפני הצמצום ע\"י ואיך הגילוי אז<sup data-n=\"4339\">58</sup> האוא\"ס שלפני הצמצום הרי יש בכוחם לגלות האור שלפני הצמצום כמו\"כ עתה לאחר הצמצום יכולים לגלות אוא\"ס שלפני הצמצום.\n<b>אך</b> צ\"ל איך שייך אותיות שלפני הצמצום, דהנה אותיות הם גבול דהאותיות מגבילים את השכל ואיך שייך זה באוא\"ס שלפני הצמצום. אך הנה כמו\"כ קשה איך הי' הצמצום, ומוכרח לומר כמ\"ש בעה\"ק דא\"ס כשם שיש לו כח בבע\"ג כמו\"כ יש לו כח בגבול<sup data-n=\"4340\">59</sup> דא\"ת שיש לו כח בבע\"ג ואין לו כח בגבול הרי אתה מחסר",[["4330","49","<b>סילק אורו הגדול אל הצד</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב. לקו\"ת בהוספות (לויקרא) נא, ג שמציין לאוצ\"ח ומבו\"ש."],["4331","50","<b>חלל ומקו\"פ</b>: ראה הגהת הרמ\"ז הובא לעיל (בחלק המאמרים) המשך מצה זו שם הערה 217."],["4332","51","<b>ממלא את כל החלל</b>: ראה כתהאריז\"ל שבהערה 49."],["4333","52","<b>תי'</b>: תיבת? או אוצ\"ל: בו."],["4334","53","<b>שנת' בחסידות דענין הצמצום ר\"ל העלם</b>: ראה לקו\"ת בהוספות (לויקרא) נב, ג ואילך."],["4335","54","<b>שבה\"כ שנפרדו האותיות</b>: לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 221 מציין לד\"ה ויקח מן הבא בידו מנחה. וש\"נ."],["4336","55","<b>ברוך. . גיבענצט או גילובט</b>: ראה גם לעיל הנחה ד\"ה מצה זו על יד הערה 36. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ובהערה 54."],["4337","56","<b>בפעולת</b>: אוצ\"ל: בפעולת'."],["4338","57","<b>ובהעגול. . נגע בו הצמצום</b>: ראה (בנוסף להמשך מצה זו כאן) סה\"מ תרמ\"ג ע' עט ואילך. תרנ\"ה ע' רח. תרס\"ו ע' קצד ואילך. מאמר ד\"ה ויקח קרח תשי\"ד."],["4339","58","<b>איך קודם. . אז</b>: כ\"ה בגוכתי\"ק."],["4340","59","<b>כמ\"ש בעה\"ק דא\"ס. . בבע\"ג. . כח בגבול</b>: ראה עבודת הקודש ח\"א רפ\"ח. דרך אמונה להנ\"ל רפ\"ב (קה\"ת תשמ\"ח ע' יג). ראה לקו\"ת עקב טז, א ובהנסמן במ\"מ לשם (מהדורת תשנ\"ט)."]]],[2000470467,"שלימותו וא\"ס הוא שלימותא דכולא, וצ\"ל שהצמצום הוא כח הגבול שבא\"ס, וכמו\"כ האותיות הם כח הגבול שבא\"ס, לפ\"ז האותיות הם כמו הצמצום. אך באמת יש הפרש גדול ביניהם, דהצמצום הוא מעלים האור והאותיות מגלים, רק שבזה הם דומים מאחר שהם גבול הם כח הגבול שבא\"ס, הגם שנת' במ\"א דכוונת הצמצום הוא לא בשביל ההעלם כ\"א לצורך הגילוי<sup data-n=\"4341\">60</sup>, א\"כ הצמצום ג\"כ מגלה, מ\"מ מה שמגלה ה\"ז אח\"כ אבל בתחילה העלים האור, ואף כשמגלה אח\"כ מה הוא מגלה אור מצומצם, אבל האותיות פעולתם בתחילה לגלות ומה הם מגלים אור שלפני הצמצום, א\"כ ההפרש גדול עד מאד ומהפעולה יובן הפועל שהוא גבוה במעלה יותר.\n<b>ועפ\"ז</b> יובן ענין קרי\"ס דכתי' אז ישיר משה כו' דהנה אמרז\"ל כל בעלי השיר<sup data-n=\"4342\">61</sup> יוצאים בשיר ונמשכים בשיר פי' כדי שיוצא לחוץ מהגבלות הכלי הוא ע\"י שיר וכמו מי שהוא בהתפעלות והתלהבות הוא משורר, והנה ענין קרי\"ס הוא דיש ב' מדרי' ים וארץ ושניהם במל'<sup data-n=\"4343\">62</sup>, ארץ הוא מקור לבי\"ע וים הוא מה שכונס אורות אצי' בתוכו, וכמו\"כ יובן למעלה בשרש ומקור הראשון ים הוא העגול הגדול שלפני הקו שמעלים האור בתוכו, וענין קרי\"ס הוא שבחי' עלמדאת\"כ יאיר ויומשך בבחי' עלמדאת\"ג<sup data-n=\"4344\">63</sup>, וכמו\"כ יובן בשרש ומקור הראשון הי' קרי\"ס שהאור דעגול הגדול שלפני הקו יאיר ויומשך בבחי' עלמדאת\"ג וזהו יבקע ל' בקיעה שנמשך מבחי' עגול הגדול שלפני הקו. וזהו אז ישיר משה ובנ\"י דע\"י שירת משה ובנ\"י שהו\"ע העלאות האותיות לשרש ומקור הראשון עי\"ז הי' השירה הזאת שהו\"ע נהו\"ת קארי תדיר לנהו\"ע ולא שכיך עד שבשרש ומקור יהי' ג\"כ נהו\"ת קארי לנהו\"ע, וכאן נק' הרשימה נהו\"ת והעגול הגדול נהו\"ע, דנהורא הוא אור ובזה נק' העגול הגדול נהו\"ע שהרי ממנו נמשך הקו אבל הרשימה נק' נהו\"ת, וע\"י שגם בשרש ומקור הראשון הי' נהו\"ת קארי לנהו\"ע עי\"ז שהם עצמם מגלים, הי' קרי\"ס שאור דעגול הגדול יומשך בבחי' עלדאת\"ג, וזהו אז ישיר משה ובנ\"י ואח\"כ השירה הזאת.\n<b>בסוף</b> הע' בצד השמאלי מלמטלמ\"ע נרשם (ולא צויין מקומו בפנים): ובתחילה הי' בהם הגילוי אור לכן הם תאוב להאור.",[["4341","60","<b>דכוונת הצמצום. . הגילוי</b>: ראה גם לעיל המשך מצה זו כאן ובהערה 226."],["4342","61","<b>כל בעלי השיר</b>: ראה שבת נא, ב (במשנה). ראה גם סה\"מ תרכ\"ח ס\"ע ו אילך."],["4343","62","<b>ים וארץ ושניהם במל'</b>: ראה גם לקו\"ת צו יד, ב. סה\"מ תרל\"ח ע' יב. וש\"נ."],["4344","63","<b>עלמדאת\"כ. . עלמדאת\"ג</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, ריש ע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך."]]],[2000470468,"<h3>גן נעול</h3>\n<b>ש\"פ שמיני תר\"ם לפ\"ק</b>\n<b>גן</b> נעול<sup data-n=\"4345\">1</sup> אחותי כלה<sup data-n=\"4346\">2</sup>, ואי' בת\"ז<sup data-n=\"4347\">3</sup> הה\"ד שער החצר הפנימית<sup data-n=\"4348\">4</sup> הפונה קדים סגור יהי'<sup data-n=\"4349\">5</sup> ששת ימי המעשה וביום השבת יפתח וביום החודש יפתח, ומפרש שהוא מם סתומה שציורו ב' ו', ומה שייך גן נעול למ\"ש שער החצר כו' הוא דבגן כתי' גן בעדן<sup data-n=\"4350\">6</sup> מקדם וכאן כתי' שער החצר הפנימית הפונה קדים, וצ\"ל מהו\"ע הסגירה, ואפ\"ל שהוא הפרסא המפסקת בין אצי' לבריאה<sup data-n=\"4351\">7</sup>, דבין אצי' לבריאה יש פרסא המפסקת ושרש הפרסא מכתר<sup data-n=\"4352\">8</sup>, וענין הפרסא הוא כדי שיהי' מאיר מתגלה אור אצי' בבריאה<sup data-n=\"4353\">9</sup>, דאצי' לגבי בריאה אינו בערך<sup data-n=\"4354\">10</sup>, דאצי' הוא אלקות ובריאה הם נבראים נפרדים ואיך שייך שיומשך מאצי' לבריאה, הוא ע\"י הפרסא, ובתהו לא הי' פרסא בין אצי' לבריאה הי' בו השבירה, ושרש הפרסא הוא מ\"ש מת\"ת דאימא נעשה כתר לז\"א<sup data-n=\"4355\">11</sup> והוא בחי' יחידה<sup data-n=\"4356\">12</sup> מקיף דיחידה שמקיף הד' מוחין וגם תחת רגליו בשוה ומזה נעשה הפרסא המפסקת בין אצי' לבריאה, והוא לבוש החשמל ששרשו מת\"ת דאימא או ת\"ת דז\"א<sup data-n=\"4357\">13</sup>, דחשמל שרשו מת\"ת, והפרסא הוא מחיצוניות בינה<sup data-n=\"4358\">14</sup> דמפנימיות נמשך המקיף דיחידה, וזהו שנת\"ל דהפרסא הוא מהמקיף ר\"ל מחיצוניות.\n<b>ועוי\"ל</b> ענין הסגירה עד\"מ תענוג שמלובש בשכל דכשמשכיל איזהו שכל הוא מתענג הנה התענוג הוא בהעלם בשכל דאימתי הוא מתענג כשמבין את השכל בהשגה והבנה ומי שהוא בעל שכל יותר ומבין הדבר יותר ה\"ה מתענג יותר, וכמו ששת ימי המעשה דכתי' ששת ימים עשה<sup data-n=\"4359\">15</sup>, ה\"ה מלובשים בהעלם בהששת ימים, וא\"כ הסגירה הוא הפרסא המפסקת בין קדושה לסט\"א שלא ינקו מפנימיות האור אשר ישראל ממשיכים ע\"י תומ\"צ, וזהו ההבדלה בין קדש לחול,",[["4345","1","<b>גן נעול</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו [ושם הפתיחה: והנה בת\"ז וכו' גן נעול] פי\"א-פי\"ג (ולא נגמר בכתיבתו). וש\"נ."],["4346","2","<b>גן נעול אחותי כלה</b>: שה\"ש ד, יב."],["4347","3","<b>ואי' בת\"ז</b>: ראה שם תי\"ט לח, א."],["4348","4","<b>שער החצר הפנימית</b>: יחזקאל מו, א."],["4349","5","<b>סגור יהי'</b>: ביחזקאל ות\"ז: יהי' סגור. ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 320."],["4350","6","<b>גן בעדן מקדם</b>: בראשית ב, ח."],["4351","7","<b>הפרסא. . אצי' לבריאה</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא."],["4352","8","<b>ושרש הפרסא מהכתר</b>: ראה בסמוך בפנים. (לעיל כאן."],["4353","9","<b>הפרסא. . אור אצי' בבריאה</b>: ראה גם (לעיל חלק המאמרים) בההמשך כאן."],["4354","10","<b>דאצי' לגבי בריאה אינו בערך</b>: ראה גם לעיל הנחה ד\"ה משה קבל ובהערה 22."],["4355","11","<b>מת\"ת דאימא נעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["4356","12","<b>כתר. . יחידה</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 329."],["4357","13","<b>לבוש החשמל. . מת\"ת. . דז\"א</b>: רמ\"ז ס\"פ יתרו דף עח."],["4358","14","<b>והפרסא. . בינה</b>: ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. ראה גם תו\"א לך יב, ג. הגהות לד\"ה פתח אלי' תרנ\"ח פ\"ה ס\"ע סח ואילך."],["4359","15","<b>ששת ימים עשה</b>: יתרו כ, יא. תשא לא, יז."]]],[2000470469,"ושרש פרסא זו הוא מהפרסא המפסקת בין אצי' לבריאה, אך היא במדרי' תחתונה ממנה<sup data-n=\"4360\">16</sup>.",[["4360","16","<b>ממנה</b>: ע\"כ נרשם בגוכתי\"ק. והמשך העמוד נשאר חלק. ראה ההמשך לעיל בהמשך מצה זו כאן."]]],[2000470470,"<h3>גן נעול</h3>\n<b>ש\"פ תו\"מ תר\"ם לפ\"ק</b>\n<b>גן</b> נעול<sup data-n=\"4361\">1</sup> פי' בתרגום<sup data-n=\"4362\">2</sup> כמו שג\"ע נעול לצדיקים ומי שראוי לבד כמו\"כ יצ\"מ הי' בזכות שהי' מרוחקים מזנות, דבנות ישראל אוגדות פתחיהם לבעליהם, ובעבודה הוא מ\"ש בנוסח התפלה דשבת ויו\"ט קדשנו במצותיך<sup data-n=\"4363\">3</sup> ותן חלקינו בתורתיך, משמע דכדי שיהי' ותן חלקנו בתורתך צ\"ל תחילה קדשינו במצותיך, דענין ותן חלקינו בתורתך הוא כמ\"ש במד' על מה דז' ימי החג<sup data-n=\"4364\">4</sup> הי' ע' פרים וע' אילים<sup data-n=\"4365\">5</sup> ובשמ\"ע פר אחד איל אחד<sup data-n=\"4366\">6</sup> משל למלך שעשה משתה ז' ימים וזימן כל בני המדינה אח\"כ אמר לאוהבו יצאנו ידי חובת כל בני המדינה עתה נגלגל אני ואתה במה שנמצא ליטרא בשר כו' כמו\"כ בשמו\"ע פר א' איל א' והוא נגד נש\"י, וזהו ותן חלקינו בתורתך דבשמ\"ע אז זמן קליטת טיפת החכ', דתורה היא חכמתו ורצונו ית' רק שנתלבשה בדברים גשמים ציצית בצמר גשמי תפילין בקלף גשמי וכל ההלכות נתלבשו בדברים גשמי' וכשאדם לומד תורה וחוזר שונה הרבה הרי תופס ההשכלה זהו\"ע קליטת טיפת החכ'. אך צ\"ל תחילה קדשינו דתחילה צ\"ל אירוסין ואח\"כ נשואין, וענין הקדושין הוא הזמנה שאוסרה על כל העולם<sup data-n=\"4367\">7</sup> ולמעלה הוא מ\"ש ואבדיל אתכם מכל העמים להיות לי<sup data-n=\"4368\">8</sup> וכמ\"ש וארשתיך לי<sup data-n=\"4369\">9</sup> דמנהגם הי' דבשעת אירוסין הי' מקדשה, ועי\"ז אח\"כ ותן חלקינו בתורתך זהו בתורה. וכמו\"כ יובן בתפלה ג\"כ דתפלה הוא ל' התקשרות וכמו הטופל כלי חרס<sup data-n=\"4370\">10</sup> והוא שיהי' לו דעת והכרה והשגה ודביקות באלקות וכמ\"ש בספרי הכר את בוראך<sup data-n=\"4371\">11</sup> היינו שיהי' התקשרות הדעת",[["4361","1","<b>גן נעול</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו [ושם מתחיל: והנה בתרגום פי' גן נעול] פי\"ד-פט\"ז. וש\"נ."],["4362","2","<b>גן נעול פי' בתרגום</b>: שה\"ש ד, יב."],["4363","3","<b>מ\"ש. . קדשנו במצותיך</b>: בתפלת העמידה. ראה לקו\"ת שמע\"צ צא, א. במדבר טז, ג. בלק סח, ב. ועוד."],["4364","4","<b>במד'. . דז' ימי החג</b>: ראה במדב\"ר פכ\"א, כד. תנחומא פינחס טז."],["4365","5","<b>וע' אילים</b>: כ\"ה בגוכתי\"ק."],["4366","6","<b>פר אחד איל אחד</b>: פינחס כט, לו."],["4367","7","<b>הקדושין. . שאוסרה על כל העולם</b>: קדושין ב, ב ובתוד\"ה דאסר."],["4368","8","<b>ואבדיל אתכם מכל העמים להיות לי</b>: קדושים כ, כו [ושם מן העמים]. תניא פמ\"ו (סו, א)."],["4369","9","<b>וארשתיך לי</b>: הושע ב, (כא). כב. ראה שה\"א ט, א ובהערה 8. תו\"ח בא ח\"א קי, א הערה 541."],["4370","10","<b>דתפלה. . הטופל כלי חרס</b>: כלים פ\"ג, מ\"ה. ראה לעיל הנחה ד\"ה בן פורת יוסף הא' ובהערה 36."],["4371","11","<b>וכמ\"ש בספרי הכר את בוראך</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 423."]]],[2000470471,"ורצון פשוט לאלקות, וכמו כאשר יקח איש אשה<sup data-n=\"4372\">12</sup> צריך לקדשה והקדושין הוא בפרוטה או בשוה פרוטה<sup data-n=\"4373\">13</sup> ובזה אוסרה לכל העולם, והוא מפני ששיערו חכמים שבפרוטה יכולים לקנות דבר המחי' את הנפש<sup data-n=\"4374\">14</sup> כמו\"כ כדי שיהי' להנשמה התקשרות לאלקות נמשך ע\"ז כח מלמעלה וע\"י הקדושין יהי' אח\"כ הקליטה ובתורה הוא מלמעלמ\"ט ובתפלה הוא מ\"ש ואל אישך תשוקתך<sup data-n=\"4375\">15</sup> מלמטלמ\"ע אך בשים שלום אז גמר השפע<sup data-n=\"4376\">16</sup>, וזהו מ\"ש והתקדשתם והייתם קדושים<sup data-n=\"4377\">17</sup> כו' להיות לי כו' כמ\"ש מקודשת לי לשמי<sup data-n=\"4378\">18</sup>, והו\"ע משארז\"ל מצות צריכות כוונה<sup data-n=\"4379\">19</sup> פי' שנדע המכוון של המצוה שהוא כדי שנהי' פרוש מתאוות רעות ומדות רעות דכשיכוון שזה אסור לעשות וזה א\"צ לעשות ממילא יהי' פרוש מתאוות גשמים, וזהו\"ע קדשנו במצותיך ועי\"ז אח\"כ ותן חלקינו בתורתך.\n<b>והנה</b> שרש ענין הקדושין הנה קדושין הוא בטבעת<sup data-n=\"4380\">20</sup> שהוא עגול ומורה על למעלה שהוא בחי' א\"ס הסוכ\"ע<sup data-n=\"4381\">21</sup>, דמה שנק' סוכ\"ע היינו שאצי' ועשי' שוין לגבי'<sup data-n=\"4382\">22</sup>, וכן בכל מדרי' ומדרי' שיש בה התחלקות סוכ\"ע משווה אותם, ועי\"ז גדול ה' ומהולל מאד<sup data-n=\"4383\">23</sup> ולגדולתו אין חקר דלכאו' קשי' מרישא לסופא דאם גדול כו' מהו ולגדולתו כו' ואם ולגדולתו כו' מהו גדול כו'. אך הענין הוא דבחי' גדול שייך בה' דענין גדול הוא דמן הארץ לרקיע<sup data-n=\"4384\">24</sup> מהלך ת\"ק שנה עובי כל רקיע מהלך ת\"ק שנה בין כל רקיע מהלך ת\"ק שנה רגלי החיות כנגד כולם שוקי החיות כנגד כולם קרסולי<sup data-n=\"4385\">25</sup> החיות כנגד כולם, וזה שייך בהתפשטות אורו, אבל בעצם א\"ס אינו שייך לומר גדול, דגדול אינו שייך כ\"א בהאור אבל לא במקור האור, דמאחר שכל דבר אינו תופס מקום כלל מה שייך לומר גדול ממי הוא גדול, לכן לגדולתו אין חקר",[["4372","12","<b>כאשר יקח איש אשה</b>: תצא כד, א."],["4373","13","<b>בפרוטה או בשוה פרוטה</b>: משנה ריש קדושין."],["4374","14","<b>ששיערו חכמים שבפרוטה. . המחי' את הנפש</b>: ראה לקו\"ת שמע\"צ צא, א. הובא לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 425."],["4375","15","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["4376","16","<b>בשים שלום אז גמר השפע</b>: ראה פע\"ח שער העמידה ש\"ט, פ\"כ."],["4377","17","<b>והתקדשתם והייתם קדושים</b>: שמיני יא, מד. קדושים כ, ז. לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 427 הובא הכתוב: והייתם קדושים — קדושים כ, כו [בדילוג]."],["4378","18","<b>כמ\"ש מקודשת לי לשמי</b>: ראה גם לעיל בההמשך כאן ובהערה 428."],["4379","19","<b>מצות צריכות כוונה</b>: ערובין צה, סע\"ב."],["4380","20","<b>קדושין הוא בטבעת</b>: ראה רמ\"א בשו\"ע אבהע\"ז רסכ\"ז. סל\"א, ס\"ב."],["4381","21","<b>בטבעת שהוא עגול. . הסוכ\"ע</b>: ראה סידור ברכת נשואין קלח, ד. תורה אור ויגש מו, ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' של. מאמרי אדה\"א בראשית ע' ריט וע' רכט. אוה\"ת תצא ע' תתרכז. ברכה ע' א'תתמה."],["4382","22","<b>שאצי' ועשי' שוין לגבי'</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' יג. וש\"נ. תו\"ח שמות ח\"א קלה, א. וש\"נ."],["4383","23","<b>גדול ה' ומהולל מאד</b>: תהלים קמה, ג. ראה תו\"א וארא נו, ב."],["4384","24","<b>דמן הארץ לרקיע</b>: ראה חגיגה יג, א."],["4385","25","<b>שוקי. . קרסולי</b>: כ\"ה גם בלק\"ת מסעי פח, ג. מאמרי אדה\"א דברים ח\"א ע' קנב. סה\"מ תרכ\"ז ע' תיח. תרל\"ג ח\"א ע' קפח. בחגיגה שם: קרסולי. . שוקי."]]],[2000470472,"דשוה ומשוה קטן וגדול<sup data-n=\"4386\">26</sup>, וכשיתבונן בזה יהי' לו לב נשבר ונדכה<sup data-n=\"4387\">27</sup>, דמאחר דשוה ומשוה קטן וגדול ממילא גם עבר עתיד והוה הם ברגע אחת<sup data-n=\"4388\">28</sup>, ובזה ישקיט לבו בתאוות גשמים, דבזמן כמה שנים קודם לא עלה על דעתו לרצות תאווה זו וכמה שנים אח\"כ לא יהי' הדבר ולא ירצה אותה כ\"א על זמן הווה, ובזמן קטן זה אינו יכול לכוף א\"ע, ויהי' בעיניו כמו שכבר עבר או כמו זמן שיהי' דמאחר דעבר עתיד והווה הם ברגע א'. וזהו אתה פוררת בעזך ים<sup data-n=\"4389\">29</sup>, הנה בים יש כמה מדרי' ויש בחי' מצולת ים וכמ\"ש ותשליך במצולת ים כל חטאותם<sup data-n=\"4390\">30</sup>, וכדי שיפרר הים דכל זמן שיש איזה תאווה ה\"ז מציאות היש וכשמפררים אותו אינו נשאר מאומה, והוא ע\"י בעזך היינו תוקף עוז ההתבוננות בגדולת א\"ס ועי\"ז יפרר הים.\n<b>וזהו\"ע</b> גן נעול דהנה גן הוא להתענג בו וכמו\"כ ג\"ע הוא תענוג אלקות, וזהו גן נעול שלא יהי' לו תענוג אחר כ\"א תענוג אלקי, וכמ\"ש מי לי בשמים<sup data-n=\"4391\">31</sup> ועמך לא חפצתי בארץ, כל מה שעמך לא חפצתי רק א\"ס עצומ\"ה, ובמדרש אי' גן נעול אלו הבתולות<sup data-n=\"4392\">32</sup> דהנה אי' בכהאריז\"ל בתולה מעיינה חתום בחותם הבינה<sup data-n=\"4393\">33</sup>, וזהו ג\"כ כנ\"ל שע\"י ההתבוננות כנ\"ל עי\"ז מעיינה חתום שיהי' רצון פשוט ותענוג אלקי לבד, וזהו השבח שכ' בתורה על רבקה והנערה יפת תואר וטובת מראה<sup data-n=\"4394\">34</sup> מאד בתולה ואיש לא ידעה שלא שלט בה הקליפה, דהנה מאד הוא בלי גבול<sup data-n=\"4395\">35</sup>, ויפת תואר הוא בינה עילאה<sup data-n=\"4396\">36</sup> אי' עילאה<sup data-n=\"4397\">37</sup> ועל ל' החסידות הוא פנימיות הלב<sup data-n=\"4398\">38</sup> ורבינו ז\"ל בלקו\"ת מפרש שהו\"ע<sup data-n=\"4399\">39</sup> רעו\"ד<sup data-n=\"4400\">40</sup>, ועל ל' אהבה הו\"ע אהבה בתענוגים שיש אהבת עולם ואהבה רבה ואהבה בתענוגים למעלה משניהם והגם שהוא מעט ובלתי שכר<sup data-n=\"4401\">42</sup> שהרי הו\"א מתענג אבל מ\"מ מאחר שיש לו רעו\"ד דהיינו רצון פשוט לאלקות לבד א\"כ התענוג ג\"כ תענוג אלקי, וע\"י מה",[["4386","26","<b>דשוה ומשוה קטן וגדול</b>: ע\"פ חרוז בפיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["4387","27","<b>לב נשבר ונדכה</b>: תהלים נא, יט."],["4388","28","<b>עבר. . ברגע אחת</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["4389","29","<b>אתה פוררת בעזך ים</b>: תהלים עד, יג."],["4390","30","<b>ותשליך במצולת ים כל חטאותם</b>: מיכה ז, יט [ושם: במצלות]."],["4391","31","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם ספר המצות להצ\"צ קלח, א. תו\"ח תצוה ח\"ב שנו, ב. וש\"נ. סה\"מ תרל\"ח ע' מו. וש\"נ. סה\"מ מלוקט ו' ע' צט ובהערה 78."],["4392","32","<b>ובמדרש אי' גן נעול אלו הבתולות</b>: ויק\"ר פל\"ב, ה. במדב\"ר פ\"ג, ו. שהש\"ר פ\"ד, יב (א). אוה\"ת שה\"ש ע' תמג."],["4393","33","<b>בתולה. . בחותם הבינה</b>: מאו\"א מערכת בתולה סמ\"ד."],["4394","34","<b>והנערה יפת תואר וטובת מראה</b>: (לשון הכתוב אסתר ב, ז) ח\"ש כד, טז [ושם: והנערה טובת מראה]."],["4395","35","<b>מאד הוא בלי גבול</b>: ראה אגה\"ק סי\"ז. תו\"א מקץ לט, ג. תו\"ח וארא ח\"א סא, ב הערה 69."],["4396","36","<b>ויפת תואר הוא בינה עילאה</b>: לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 456 הובא: ויפת מראה בינה עילאה. וש\"נ. וראה לקמן הערה 39."],["4397","37","<b>בינה עילאה אי' עילאה</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"ח."],["4398","38","<b>בינה. . פנימיות הלב</b>: ראה לקו\"ת סוכות עח, ד."],["4399","39","<b>ורבינו ז\"ל בלקו\"ת מפרש שהו\"ע רעו\"ד</b>: מטות פז, ג (על יפת מראה). וראה לעיל הערה 36."],["4400","40","<b>רעו\"ד</b>: זהר וירא ק, א.\n41) ואהבה בתענוגים למעלה משניהם: תו\"א ויחי מז, ג."],["4401","42","<b>מעט ובלתי שכר</b>: כ\"ה בגוכתי\"ק."]]],[2000470473,"יבוא לבחי' יפת תואר<sup data-n=\"4402\">43</sup> זהו כא'<sup data-n=\"4403\">44</sup> בתולה ואיש לא ידעה שלא שלט בה הקליפה וזהו שנת\"ל דזכות דיצ\"מ הי' מפני שהיו מרוחקים מזנות דנא\"ף בגי' ס' מ' א' ל'<sup data-n=\"4404\">45</sup>, וז\"ש נואף אשה חסר לב<sup data-n=\"4405\">46</sup>, וזהו שכ' בזהר דמפתה לאיתתא ונטלא נהורא<sup data-n=\"4406\">47</sup>, אבל הם היו מרוחקים מזה ולכן יצאו ממצרים, וזהו בתולה ואיש לא ידעה, דהנה אי' בא נחש על חוה<sup data-n=\"4407\">48</sup> והטיל בה זוהמא והוא שנשתלשל מגבורות קשות דק\"ך צירופים דשם אלקים<sup data-n=\"4408\">49</sup> ומ\"ח צירופי' אחרונים<sup data-n=\"4409\">50</sup> הם גבורות קשות, אבל גבי שרה כתי' ולא קרב אלי'<sup data-n=\"4410\">51</sup> שלא הי' לו קורבא אלי', וכמו\"כ גבי רבקה כתי' ואיש לא ידעה היינו האיש זר לא ידעה ועי\"ז יבוא לבחי' יפת תואר.\n<b>ובעבודה</b> הוא הכעס וכמ\"ש טורף נפשו<sup data-n=\"4411\">52</sup> באפו<sup data-n=\"4412\">53</sup>, דהכעס הוא המקור לכל מיני רע דתאוות רעות ומדות רעות, וזהו גן נעול שיהי'<sup data-n=\"4413\">54</sup> בבחי' ואיש לא ידעה עי\"ז יבוא למ\"ש אח\"כ<sup data-n=\"4414\">55</sup> פתחי ל\"י<sup data-n=\"4415\">56</sup> שקאי על בחי' אוא\"ס וכמ\"ש וארשתיך לי<sup data-n=\"4416\">57</sup>, והייתם קדושים לי<sup data-n=\"4417\">58</sup>, ויקחו לי תרומה<sup data-n=\"4418\">59</sup> כביכול אותי אתם לוקחין<sup data-n=\"4419\">60</sup>, עוי\"ל לי הוא ליו\"ד וכמו יעקב יו\"ד עקב<sup data-n=\"4420\">61</sup> שהיו\"ד אפי' בבחי' עקביים ג\"כ, והוא ע\"י גן נעול וכ\"ה בהשמטות דזהר דמתפתחין לבעליהן<sup data-n=\"4421\">62</sup>, ועל פתח זה נא' ופסח ה' על הפתח<sup data-n=\"4422\">63</sup> שהו\"ע דילוג המדרי' לא בדרך הדרגה מ\"מ ופסח על הפתח, ולכן כתי' לא תצא איש מפתח ביתו<sup data-n=\"4423\">64</sup> עד בקר שהו\"ע גן נעול. ובת\"י<sup data-n=\"4424\">65</sup> פי' פתחי לי דפתחין פומא בשירין ובתושבחין<sup data-n=\"4425\">66</sup>, ולפ\"ז י\"ל גן נעול כפי' הא' שיהי' נעול מדברים בטלים שג\"ז מסתיר",[["4402","43","<b>יפת תואר</b>: ראה לעיל הערות 39 36."],["4403","44","<b>כא'</b>: כאמרו?"],["4404","45","<b>דנא\"ף בגי' ס' מ' א' ל'</b>: נסמן לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 467."],["4405","46","<b>נואף אשה חסר לב</b>: משלי ו, לב."],["4406","47","<b>דמפתה לאיתתא ונטלא נהורא</b>: ראה זהר ויקהל רג, ב."],["4407","48","<b>בא נחש על חוה</b>: שבת קמו, רע\"א."],["4408","49","<b>דק\"ך צירופים דשם אלקים</b>: ראה לעיל הנחה ד\"ה סמכוני באשישות ובהערה 73."],["4409","50","<b>ומ\"ח צירופי' אחרונים</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ה. שער הכוונות ענין הפסח דרוש א'. הובא באגרת מיום ב' ט' טבת תש\"ה (אג\"ק ח\"ב ע' כ) ע\"ש. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'סא. לעיל בהמשך מצה זו פנ\"ח על יד הערה 1659. פלח הרמון שמות ס\"ע שנג ואילך."],["4410","51","<b>ולא קרב אלי'</b>: וירא כ, ד [ושם: ואבימלך לא]."],["4411","52","<b>הכעס. . טורף נפשו</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 471."],["4412","53","<b>טורף נפשו באפו</b>: איוב יח, ד."],["4413","54","<b>שיהי'</b>: אולי כתוב: שנהי'."],["4414","55","<b>למ\"ש אח\"כ</b>: לעיל (בחלק המאמרים) המשך מצה זו כאן ניתוסף: בקאפיטול שאחר זה."],["4415","56","<b>פתחי ל\"י</b>: שה\"ש ה, ב."],["4416","57","<b>וארשתיך לי</b>: הושע ב, כא."],["4417","58","<b>והייתם קדושים לי</b>: קדושים כ, כו [בדילוג]."],["4418","59","<b>ויקחו לי תרומה</b>: תרומה כה, ב."],["4419","60","<b>ויקחו לי. . אותי אתם לוקחין</b>: ויק\"ר פ\"ל, יג."],["4420","61","<b>יעקב יו\"ד עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["4421","62","<b>בהשמטות דזהר דמתפתחין לבעליהן</b>: ראה זח\"א רסב, ב."],["4422","63","<b>ופסח ה' על הפתח</b>: בא יב, כג."],["4423","64","<b>לא תצא איש מפתח ביתו</b>: בא יב, כב [ושם: תצאו]."],["4424","65","<b>ובת\"י</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 88."],["4425","66","<b>דפתחין פומא בשירין ובתושבחין</b>: בתרגום שם: פתחי פומך ובועי ושבחי."]]],[2000470474,"וכל דיבורו יהי' בתורה. והנה ע\"י גן נעול שהו\"ע פתחי לי ממשיכים בחי' כבוד חכמים ינחלו<sup data-n=\"4426\">67</sup>, כמארז\"ל אין כבוד אלא תורה<sup data-n=\"4427\">68</sup>, דהנה כל נפש נק' כבוד<sup data-n=\"4428\">69</sup> מפני שרשו מכה\"כ, והעלי' ג\"כ לבחי' כבוד וכמ\"ש למען יזמרך כבוד<sup data-n=\"4429\">70</sup>. וי\"ל דהנה ישראל הוא ר\"ת יש ששים ריבוא אותיות<sup data-n=\"4430\">71</sup> לתורה<sup data-n=\"4431\">72</sup>, אשר כל נשמה כללית יש לה אות<sup data-n=\"4432\">73</sup> באותיות התורה, וע\"י לימוד התורה ממשיכים מאותיות התורה, וכ\"ה בס' דאי' בספרים<sup data-n=\"4433\">74</sup> דהלוחות של סנפירין<sup data-n=\"4434\">76</sup> היו<sup data-n=\"4435\">75</sup> וכמ\"ש וכמראה אבן ספיר דמות כסא<sup data-n=\"4436\">77</sup>, והלוחות נחצבו מכסה\"כ<sup data-n=\"4437\">78</sup> וע\"י לימוד ממשיכים מבחי' זו, וענין כסה\"כ הוא היכל קדה\"ק דבריאה<sup data-n=\"4438\">79</sup> דתורה שלנו הוא תורת הבריאה<sup data-n=\"4439\">80</sup>, והוא כסא לכבוד מל' דאצי'<sup data-n=\"4440\">81</sup>. ועוי\"ל כסא הוא בינה<sup data-n=\"4441\">82</sup> והוא כסא לכבוד (בפ\"א<sup data-n=\"4442\">83</sup> כתר שהוא כבוד מל'<sup data-n=\"4443\">84</sup> דא\"ס) וכמ\"ש הראיני נא את כבודיך<sup data-n=\"4444\">85</sup> (שהוא כבוד ד') מל' דא\"ס, והנה גבי לוחות כתי' והמכתב כו' חרות על הלוחות<sup data-n=\"4445\">86</sup> והו\"ע אותיות החקיקה דמיני' ובי', דהנה הרשימה שהניח הקב\"ה מא\"ס שלפני הצמצום עז\"נ גליף גליפו בטהירו עילאה<sup data-n=\"4446\">87</sup>, ונש\"י עלו במח'<sup data-n=\"4447\">88</sup> ומח' של ישראל קדמה לכל דבר שרשן ג\"כ מבחי' זו, ונת\"ל דבהאותיות לא",[["4426","67","<b>כבוד חכמים ינחלו</b>: משלי ג, לה."],["4427","68","<b>אין כבוד אלא תורה</b>: אבות פ\"ו, ג. ראה מאמרי אדה\"א בראשית ע' טז."],["4428","69","<b>כל נפש נק' כבוד</b>: ראה בחיי ס\"פ ח\"ש (כה, ח)."],["4429","70","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["4430","71","<b>ישראל. . יש ששים ריבוא אותיות לתורה</b>: ראה מגלה עמוקות אופן קפו. פני יהושע קדושין ל, א ד\"ה ת\"ר."],["4431","72","<b>ששים ריבוא אותיות לתורה</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע שם. לקו\"ש טו\"ב כסלו תשמ\"א כרך כ ע' 419 בהערה. שו\"ת הצ\"צ חאבהע\"ז סרמ\"ט (צה, א)."],["4432","73","<b>כל נשמה כללית. . אות</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רנב. וש\"נ. שה\"א צז, סע\"א ובהערה 13."],["4433","74","<b>בס' דאי' בספרים</b>: כ\"ה בגוכתי\"ק. לעיל (בחלק המאמרים) המשך מצה זו כאן מציין לבחיי תשא לא, יח בסופו."],["4434","76","<b>סנפירין</b>: ראה גם לקו\"ש עקב כרך יט ע' 106 הערה 9."],["4435","75","<b>דהלוחות של סנפירין היו</b>: ראה פדר\"א פמ\"ו. תנחומא תשא כט. עקב ח. ויק\"ר פל\"ב ב. ועוד."],["4436","77","<b>וכמראה אבן ספיר דמות כסא</b>: יחזקאל א, כו [ושם: כמראה]."],["4437","78","<b>והלוחות נחצבו מכסה\"כ</b>: ראה תנחומא עקב שם. בחיי שם."],["4438","79","<b>כסה\"כ הוא היכל קדה\"ק דבריאה</b>: ראה מאו\"א מערכת כסא סכ\"ב. סידור ערבית לשבת קסח, ד."],["4439","80","<b>דתורה שלנו הוא תורת הבריאה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספכ\"ג על יד הערה 706. לקו\"ת סוכות פא, ד מלק\"ת להאריז\"ל ר\"פ בראשית. אוה\"ת שבועות ר\"ע קצג. וראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תסו. וש\"נ. אוה\"ת שלח ר\"ע תרלז בשם הע\"ח. סה\"מ תרל\"ח ע' קנג. וש\"נ."],["4440","81","<b>כסא לכבוד מל' דאצי'</b>: ראה מאו\"א שם."],["4441","82","<b>כסא הוא בינה</b>: ראה פרדס שער כ\"ג שער ערכי הכנויים פי\"א מערכת כסא. הועתק — בשינוי — גם באוה\"ת נצבים ע' א'ריד."],["4442","83","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4443","84","<b>מל'</b>: אולי תיבה זו נמחקה."],["4444","85","<b>כתר. . הראיני נא את כבודיך</b>: תשא לג, יח. ראה זהר רע\"מ פינחס רנה, ב. אוה\"ת נצבים שם."],["4445","86","<b>והמכתב כו' חרות על הלוחות</b>: תשא לב, טז."],["4446","87","<b>גליף גליפו בטהירו עילאה</b>: ראה זהר בראשית טו, א."],["4447","88","<b>ונש\"י עלו במח'</b>: ראה ב\"ר פ\"א, ד. לקו\"ת בחוקותי מז, א. שה\"ש טז, ד. יט, ב. יז, ד. יח, ב. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."]]],[2000470475,"נגע בהם הצמצום<sup data-n=\"4448\">89</sup> אבל בהאור הי' בו שינוי ולכן ע\"י עסק התורה ממשיכים בחי' זו, ותחילה צ\"ל גן נעול שיהי' מרוחק מכל דבר רק רצון פשוט ותענוג אלקי לבד ואח\"כ בחי' פתחי לי ממשיכים מ\"ש כבוד חכמים ינחלו שהחכמים ממשיכים הכבוד וזהו ותן חלקינו בתורתך שהוא חלק שלנו, אך תחילה צ\"ל גן נעול כו' ועי\"ז אח\"כ כבוד חכמים כו'.",[["4448","89","<b>ונת\"ל דבהאותיות לא נגע בהם הצמצום</b>: הנחה ד\"ה אז ישיר משה ד\"ה אך הנה נת\"ל."]]],[2000470476,"<h3>גל נעול מעין חתום</h3>\n<b>ש\"פ אח\"ק תר\"ם לפ\"ק</b>\n<b>גל</b> נעול<sup data-n=\"4449\">1</sup> מעין חתום<sup data-n=\"4450\">2</sup> ופרש\"י גל מעין וכמ\"ש גולות עליות<sup data-n=\"4451\">3</sup>, עוד פי' גל שער וכמו דאי' בגמ' ל' ארמי טרוקי גלי<sup data-n=\"4452\">4</sup>, ובתרגום פי' ג\"כ מעין אך כ' ההוא מבועא דמיא דמפקי מתחות אילני דחייא ואתפרשין לארבעת רישין נהרא<sup data-n=\"4453\">5</sup>, מפרש שהו\"ע מ\"ש ונהר יוצא מעדן<sup data-n=\"4454\">6</sup> להשקות את הגן, ומפרש שהנהר יוצא מתחות אילנא דחייא היינו עץ החיים, והעיקר שיהי' מעין חתום והוא ע\"י גל נעול וכמ\"ש ברישי' גן נעול אחותי כלה (שע\"י גן נעול עי\"ז אחותי כלה וכמשנת\"ל בד\"ה גן נעול הא'<sup data-n=\"4455\">7</sup> ). ומה שא' כאן גן וכאן א' גל, הענין דהנה גל הוא מחיצה וכמ\"ש הנה הגל הזה<sup data-n=\"4456\">8</sup> והנה המצבה שהוא המחיצה שהי' בין יעקב ללבן אם אני אעבור אליך<sup data-n=\"4457\">9</sup> ואם אתה תעבור אלי את המצבה הזאת לרעה, הרי שהי' מחיצה המפסקת בין יעקב ללבן, וכמו\"כ למעלה הוא ההבדלה בין קדושה לסט\"א. וזהו כדי שיהי' מעין חתום הוא ע\"י גל נעול, א\"כ פי' גל מעין וי\"ל שער ג\"כ, ובעבודה הם ז' מצות דרבנן תרי\"ג מצות<sup data-n=\"4458\">10</sup> דאורייתא ומה שהם תר\"ך מצות<sup data-n=\"4459\">11</sup> הם עם ז' מצות דרבנן שהם גדרים וסייגים לתורה, וכמו עשו סיג לדבריהם<sup data-n=\"4460\">12</sup>, וכל דבריהם הוא סיג לתורה<sup data-n=\"4461\">13</sup> שלא נבוא לאיסור תורה.",[["4449","1","<b>גל נעול</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים המשך מצה זו פי\"ז-פי\"ט (ולא נגמר בכתיבתו). וש\"נ."],["4450","2","<b>גל נעול מעין חתום</b>: שה\"ש ד, יב."],["4451","3","<b>גולות עליות</b>: יהושע טו, יט."],["4452","4","<b>טרוקי גלי</b>: ברכות כח, א [ושם: טרוקו גלי — וכ\"ה ברש\"י כאן. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן]."],["4453","5","<b>ההוא מבועא. . נהרא</b>: בתרגום: כמבוע דמין חיין דנפיק מתחות אילנא ומתפרש לארבעת רישיה [נו\"א: רישי] נהרין."],["4454","6","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["4455","7","<b>בד\"ה גן נעול הא'</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו פי\"ג."],["4456","8","<b>הנה הגל הזה</b>: ויצא לא, נא."],["4457","9","<b>אם אני אעבור אליך</b>: ויצא לא, נב [בדילוג. ושם: לא אעבור. . לא תעבור. . הגל הזה ואת המצבה]."],["4458","10","<b>ז'. . תרי\"ג מצות</b>: נסמן לעיל בהנחה ד\"ה סמכוני באשישות הערות 83 — 80."],["4459","11","<b>תר\"ך מצות</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 253. מאמרי אדמו\"ר הצ\"צ הנחות תרט\"ו ס\"ע קא. המשך תער\"ב ח\"ב ע' תתקעה וע' תתקעז."],["4460","12","<b>עשו סיג לדבריהם</b>: ראה אבדר\"נ פ\"א, ה. נדה ד, ב."],["4461","13","<b>סיג לתורה</b>: אבות פ\"א, מ\"א."]]],[2000470477,"<b>וביאור</b> הענין דהנה כתי' ויבן ה' אלקים את הצלע<sup data-n=\"4462\">14</sup> ואי' בגמ' ובמד' ויבן ל' בינה ואי' בגמ' בינה יתירה ניתנה באשה<sup data-n=\"4463\">15</sup> יותר מבאיש, וצ\"ל מהו הבינה יתירה שבאשה וגם צ\"ל למה ניתנה בינה יתירה באשה מבאיש. והענין דהנה ג' דברים נק' אשה אשר בהם ניתנה בינה יתירה כו', דיבור נק' אשה וקול נק' איש<sup data-n=\"4464\">16</sup>, דאיש ואשה הוא משל משפיע ומקבל שהקול הוא משפיע בדיבור והדיבור מקבל מהקול דענין הדיבור הוא אותיות והשמעת האותיות הוא ע\"י הקול הרי הדיבור מקבל מהקול ומהבל הלב, יראה נק' אשה<sup data-n=\"4465\">17</sup> וכמ\"ש אשה יראת ד' היא תתהלל<sup data-n=\"4466\">18</sup>, תושבע\"פ נק' אשה<sup data-n=\"4467\">19</sup> וכמ\"ש לזאת יקרא אשה<sup data-n=\"4468\">20</sup> כי מאיש לוקחה זאת, זאת הוא תושבע\"פ ותושב\"כ נק' זה<sup data-n=\"4469\">21</sup>, וז\"ש וזאת התורה אשר שם משה<sup data-n=\"4470\">22</sup> הוא התושבע\"פ אשר קבל משה מסיני, (וצ\"ע משארז\"ל יבוא זה ויקבל זאת<sup data-n=\"4471\">23</sup> ). וצ\"ל תחילה מה שדיבור נק' אשה ובינה יתירה ניתנה באשה כו', דהנה אנו רואין דיש כח בדיבור דאפי' כשיושב לעצמו<sup data-n=\"4472\">24</sup> ניתוסף אצלו משא\"כ במח', רק שענין הדיבור הוא לזולתו אבל לעצמו מספיק המח'. אבל מ\"מ כשידבר בפ\"ע איזה השכלה עי\"ז יתוסף אצלו מה שבמח' אפי' אם יחשב כמה לא יתוסף אצלו כלום וגם לא הי' זה בשכלו כלל, והדיבור מוליד השכל והוא מפני דדיבור שרשו מקדמות השכל<sup data-n=\"4473\">25</sup> ר\"ל קדם לשכל רק שנשפל ונעשה לבוש לשכל וידוע דהלבוש למעלה מהדבר הלובש<sup data-n=\"4474\">26</sup> כמו\"כ האותיות מאחר שהם לבושי' מוכרח לומר שהם למעלה מההשכלה לכן יש בכחם להוליד שכל. וזהו שארז\"ל הרבה קבלתי מרבותי ומתלמידי יותר מכולם<sup data-n=\"4475\">27</sup>, ר\"ל מרבותיו והוא מפני הדיבור שע\"י ניתוסף דבר שלא הי' תחילה בשכלו, ולכן עיקר מצות לימוד התורה הוא בדיבור וכמ\"ש ודברת בם<sup data-n=\"4476\">28</sup> והוא שע\"י הדיבור מתחדש דבר חדש בתורה, וכל אחד לפי ערכו מחדש איזה דבר חדש, והוא ע\"י הדיבור. ולכן אנו רואין כשאחד מתבונן בשכלו באיזה התבוננות וצריך לילד מזה איזהו מדה, מ\"מ ההתפעלות אינו כ\"כ, רק כשאומר אותיות התפלה בקול רם, והו\"ע שמיעת הדבור ולכן ארז\"ל השמע לאזנך מה שאתה מוצא מפיך<sup data-n=\"4477\">29</sup> שישמע",[["4462","14","<b>ויבן ה' אלקים את הצלע</b>: בראשית ב, כב."],["4463","15","<b>בינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["4464","16","<b>דיבור נק' אשה וקול נק' איש</b>: ראה זהר שמות ג, א."],["4465","17","<b>יראה נק' אשה</b>: ראה זהר ח\"ש קכב, א. פקודי רלט, ב."],["4466","18","<b>אשה יראת ד' היא תתהלל</b>: משלי לא, ל."],["4467","19","<b>תושבע\"פ נק אשה</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 535."],["4468","20","<b>לזאת יקרא אשה</b>: בראשית ב, כג."],["4469","21","<b>זאת הוא תושבע\"פ ותושב\"כ נק' זה</b>: בעה\"כ לבעל סדה\"ד מערכת זאת ומערכת זה מציין: מג\"ע אופן כט פט (ובשניהם לא נמצא)."],["4470","22","<b>וזאת התורה אשר שם משה</b>: ואתחנן ד, מד."],["4471","23","<b>יבא זה ויקבל זאת</b>: מנחות נג, ב."],["4472","24","<b>דיש כח בדיבור דאפי' כשיושב לעצמו</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 537."],["4473","25","<b>דדיבור שרשו מקדמות השכל</b>: אגה\"ק ס\"ה (קז, ב). ראה גם לעיל הנחה ד\"ה מצה זו ובהערה 42."],["4474","26","<b>דהלבוש למעלה מהדבר הלובש</b>: אוצ\"ל: המלובש. ראה גם תו\"ח וארא ח\"א נח, סע\"ג ואילך. וש\"נ."],["4475","27","<b>הרבה קבלתי. . מכולם</b>: ראה תענית ז, א. הערה 538 לעיל (בחלק המאמרים) המשך מצה זו כאן."],["4476","28","<b>ודברת בם</b>: ואתחנן ו, ז."],["4477","29","<b>השמע לאזנך מה שאתה מוצא מפיך</b>: ברכות יג, ב."]]],[2000470478,"מה שאת\"ה מוצא מפיך הוא ע\"י הדיבור ויש בכח הדיבור שיבוא עי\"ז להתפעלות הרבה יותר ממה שהי' קודם ע\"י ההתבוננות בשכל, והוא מפני דז\"א בעתיקא אחיד ותליא<sup data-n=\"4478\">30</sup> למעלה משכל רק שנולד משכל אבל שרשם למעלה מהשכל, לכן דוקא ע\"י הדיבור שהוא ג\"כ למעלה מהשכל מעורר המדות כמו שהם בעצמם, וזהו קול מעורר הכונה<sup data-n=\"4479\">31</sup> שע\"י קול יכול לבוא לפנימיות נקודת הלב.\n<b>וביאור</b> ענין נקודת הלב, הנה ברתא דמלכא<sup data-n=\"4480\">32</sup> הוא נקודת ציון וכנס\"י היינו שכונס ואסיף<sup data-n=\"4481\">33</sup> בתוכו הארה מישראל דלעילא<sup data-n=\"4482\">34</sup>, וזהו בכל לבבך ולא נא' בכל לבך, שיש ב' לבבות<sup data-n=\"4483\">35</sup> היינו חיצוניות הלב ופנימיות הלב, חיצוניות הלב הוא אהבה שמצד ההתבוננות ומכל דבר יכול להתבונן, דהנה כשיתבונן איך שאין לך דבר למטה שאין לו מזל<sup data-n=\"4484\">36</sup> למעלה המכה בו וא\"ל גדל, דכל דבר יש לו שרש למעלה<sup data-n=\"4485\">37</sup> השופע חיות בתוכו וגבוה מעל גבוה שומר<sup data-n=\"4486\">38</sup> וגבוה מאליהם, וכמ\"ש וברוח פיו כל צבאם<sup data-n=\"4487\">39</sup>, ואתה מחי' את כולם<sup data-n=\"4488\">40</sup>, שכל דבר יש לו שרש למעלה. וזהו דכתי' בתורה ראה נתתי לפניך<sup data-n=\"4489\">41</sup> את החיים ואת הטוב את המות ואת הרע, דבכל דבר יש מות וחיים, מות הוא חומר גשם הדבר וחיים הוא החיות אלקי המחי' הגשם ההוא, ומזה מובן שהדבר בעצם הוא מות שאם נא' שהוא חיות בעצם א\"צ לדבר אחר שיחי' אותו אלא מוכרח לומר שהוא מות בעצם, ולכן יעץ הכ' ובחרת בחיים<sup data-n=\"4490\">42</sup> והוא עצה כללית וכמ\"ש לאהבה את ה' אלקיך כי הוא חייך<sup data-n=\"4491\">43</sup> שהו\"ע אוא\"ס חיי החיים<sup data-n=\"4492\">44</sup>, והחיות של כל דבר הוא חייך, הוא זהו החיות של כל דבר, וזהו רוממות אל בגרונם<sup data-n=\"4493\">45</sup> וחרב פיפיות בידם לעשות נקמה בגוים<sup data-n=\"4494\">46</sup>. דהנה הדיבורים והמח' והמעשים אשר לא לה' המה הוא מקליפות עמלק וכמ\"ש אשר קרך בדרך שפעל קרירות בדרך ה'<sup data-n=\"4495\">47</sup>, הוא",[["4478","30","<b>דז\"א בעתיקא אחיד ותליא</b>: ראה זהר אד\"ז האזינו רצב, א. הערה 543 לעיל (בחלק המאמרים) המשך מצה זו כאן."],["4479","31","<b>קול מעורר הכונה</b>: ראה טושו\"ע או\"ח סס\"א, ס\"ד. הערה 542 לעיל שם."],["4480","32","<b>ברתא דמלכא</b>: ראה לקו\"ת תצא לה, ג. ת\"ז סתי\"ג כט, ב. וראה גם תכ\"א מג, א."],["4481","33","<b>וכנס\"י היינו שכונס ואסיף בתוכו</b>: ראה גם תו\"א תצוה פד, ב. סה\"מ תרל\"ח ע' תיט. וש\"נ."],["4482","34","<b>מישראל דלעילא</b>: זהר שמות ה, א. יז, סע\"א. ועוד. וראה גם אוה\"ת שמות כרך ז ע' ב'תעו ממד\"ר ופדר\"א."],["4483","35","<b>בכל לבבך. . שיש ב' לבבות</b>: ואתחנן ו, ה. ראה גם לקו\"ת בלק סז, ד."],["4484","36","<b>שאין לך דבר. . מזל</b>: ראה אוה\"ת וארא כרך ח ע' ב'תתפג שמציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג."],["4485","37","<b>דכל דבר יש לו שרש למעלה</b>: ראה גם אלימה רבתי מעין ד (עין שמש), תמר א פי\"ד (קו, ריש ע\"ב). סה\"מ תרל\"ח ע' טו ואילך (פ\"ח פ\"ט)."],["4486","38","<b>וגבוה מעל גבוה שומר</b>: קהלת ה, ז."],["4487","39","<b>וברוח פיו כל צבאם</b>: תהלים לג, ו."],["4488","40","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["4489","41","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בדילוג תיבת: היום]."],["4490","42","<b>ובחרת בחיים</b>: נצבים ל, יט."],["4491","43","<b>לאהבה את ה' אלקיך כי הוא חייך</b>: נצבים ל, כ."],["4492","44","<b>חיי החיים</b>: יומא עא, א. ראה גם תניא פמ\"ד (סג, א)."],["4493","45","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["4494","46","<b>לעשות נקמה בגוים</b>: תהלים שם, ז."],["4495","47","<b>אשר קרך. . קרירות בדרך ה'</b>: תצא כה, יח. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 560."]]],[2000470479,"מ\"ש ושמרו דרך הוי'<sup data-n=\"4496\">48</sup> לעשות צדקה ומשפט כמו הדרך שהולך מעיר לעיר כמו\"כ הוא דרך ומבוא שיומשך שם ה' למטה מטה, ועמלק פעל בישראל שיהי' קרירות בהדרך שמטיל ספיקות<sup data-n=\"4497\">49</sup> מי אומר שכ\"ה עד שיבוא לדבר ולחשוב דיבורים ומח' אשר לא לה' המה עד שיפול ח\"ו במעשה, והנקמה שהו\"ע חרב פיפיות הוא ע\"י רוממות אל בגרונם ע\"י שיתבונן בגדולת ה' איך שהחיות של כל דבר הוא חיות אלקי עי\"ז יהי' אהבה לאלקות וזהו וחרב פיפיות בידם וכמ\"ש אשר לקחתי מיד אמורי בחרבי ובקשתי ות\"א בצלותא ובבעותי<sup data-n=\"4498\">50</sup> הו\"ע התבוננות התפלה וסידר שבחו של מקום דלעולם יסדר אדם שבחו של מקום תחילה ואח\"כ יתפלל<sup data-n=\"4499\">51</sup> והו\"ע הללו את ה' מן השמים<sup data-n=\"4500\">52</sup> הללוהו במרומים עי\"ז יתגבר על הרע שבנפשו, והנה התבוננות זו דחיצוניות הלב הוא מבחי' ממכ\"ע דכל השגות מלאכים ונשמות הכל מבחי' ממכ\"ע דבזה יש חילוקים מדרי' דכאו\"א לפי ערכו וזהו כולם פותחין את פיהם בקדושה וטהרה כו' ומעריצים ומקדישים וממליכים את שם<sup data-n=\"4501\">53</sup> כו' שהוא בחי' מל' ממכ\"ע וכמו\"כ גבי נשמות כתי' ברוך שם<sup data-n=\"4502\">54</sup> כבוד מל' לעולם ועד, שם הוא בחי' מל'<sup data-n=\"4503\">55</sup> שהוא ממכ\"ע, אבל פנימיות הלב הוא ביטל שלמעלה מטו\"ד רק להשתפך נפשה אל חיק אבי', והו\"ע חלק אלוקה שבנפשו שאינו מתגלה רק ביחידה שבנפש (אפ\"ל הו\"ע מ\"ש בע\"ח שמ\"א פ\"א<sup data-n=\"4504\">56</sup> שיש ניצוץ קטן כו' ע\"ש).\n<b>והנה</b> הביטל דפנימיות הלב הוא מבחי' סוכ\"ע, דחיצוניות הלב הוא כ\"א לפ\"ע שהוא בחי' ממכ\"ע אבל פנימיות הלב הוא מבחי' סוכ\"ע אשר שוה ומשוה קטן וגדול<sup data-n=\"4505\">57</sup> וכמ\"ש את השמים ואת הארץ אני מלא<sup data-n=\"4506\">58</sup> הגם דשמים לרום<sup data-n=\"4507\">59</sup> מ\"מ הוא בארץ כמו בשמים אדרבה כתי' והקדוש בשמים ובארץ<sup data-n=\"4508\">60</sup> כמו שהוא קדוש ומובדל מארץ כמו\"כ הוא מובדל משמים, דכמו שגשמיות אינו תופס מקום כמו\"כ רוחניות",[["4496","48","<b>ושמרו דרך הוי'</b>: וירא יח, יט."],["4497","49","<b>ועמלק. . ספיקות</b>: ראה גם לקו\"ש בשלח כרך כו ע' 88 הערה 37. פלח הרמון מג\"א ע' שנה (בשם הרב מברדיטשוב)."],["4498","50","<b>אשר. . בחרבי ובקשתי ות\"א בצלותא ובבעותי</b>: ויחי מח, כב. וראה בת\"א שם."],["4499","51","<b>דלעולם יסדר. . יתפלל</b>: ע\"ז ז, סע\"ב. ברכות לב, א."],["4500","52","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["4501","53","<b>כולם פותחין. . ומעריצים. . את שם</b>: ראה ברכת יוצר."],["4502","54","<b>ברוך שם</b>: פסחים נו, א (נוסח ק\"ש). ראה גם לעיל המשך זאת חנוכת המזבח פ\"ד ובהערה 66."],["4503","55","<b>שם הוא בחי' מל'</b>: ראה מאו\"א מערכת שם אות נג וביאיר נתיב שם. ש\"א לו, ב ובהערה 40. וראה גם פרדס שעה\"כ שכ\"ג, פכ\"א מערכת שם."],["4504","56","<b>חלק אלוקה. . בע\"ח שמ\"א פ\"א</b>: וכ\"ה לקמן הנחה ד\"ה צאינה וראינה על יד הערה 92. בלקו\"ת תצא לה, ד מציין: ע' ע\"ח שמ\"א פ\"ג<sup data-n=\"e257\">א</sup>. ראה גם לעיל (בחלק המאמרים) המשך מצה זו ספכ\"ו על יד הערה 867."],["4505","57","<b>שוה ומשוה קטן וגדול</b>: ע\"פ חרוז בפיוט (לימים נוראים) ”האוחז ביד מדת משפט\"."],["4506","58","<b>את השמים. . מלא</b>: ירמי' כג, כד. ראה תניא פמ\"ח. תו\"ח בשלח ח\"א קסו, ג. וש\"נ."],["4507","59","<b>דשמים לרום</b>: משלי כה, ג."],["4508","60","<b>והקדוש בשמים ובארץ</b>: ברכת ישתבח. ראה גם לקו\"ת שלח נא, ד. מאמרי אדה\"א שמות ח\"ב ס\"ע תכב. וש\"נ. דברים ח\"א ע' קפג. וש\"נ.\n\n<b>א</b>  והוא במהדורת שקלאב תק\"ס — ובדפו\"א שמ\"ב, פ\"א."]]],[2000470480,"ג\"כ אינו תופס מקום, וזהו אתה קודם שנבה\"ע<sup data-n=\"4509\">61</sup> ואתה לאחר שנברה\"ע מפני שאינו תופס מקום כלל ולכן לא שניתי<sup data-n=\"4510\">62</sup> כלל שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה, דכללות העולמות הוא משם והארה בעלמא שאינו תופס מקום כלל, והנה אמרז\"ל אין מזל לישראל<sup data-n=\"4511\">63</sup> דכתי' ואתם תהיון לי<sup data-n=\"4512\">64</sup> ממלכת קדוש לא\"ס עצומ\"ה וכמ\"ש מי לי בשמים<sup data-n=\"4513\">65</sup> ועמך לא חפצתי בארץ, שו\"א הם געה\"ת וגעה\"ע, לא חפצתי לא בגעה\"ת ולא בגעה\"ע ולא בעוה\"ב כ\"א בא\"ס עצומ\"ה וכמ\"ש כלה שארי ולבבי צור לבבי<sup data-n=\"4514\">66</sup> וחלקי אלקים לעולם וזהו הביטול שלמעלה מטו\"ד.\n<b>והנה</b> אהבה זו ישנו בכאו\"א מישראל אך היא מוסתרת ונעלמת דהיצה\"ר והנה\"ב מסתיר ומעלים מאד וטרדות האדם בשעבוד הפרנסה וכמ\"ש בנפשו יבוא לחמו<sup data-n=\"4515\">67</sup>, שהנפש משוקע בזה, וזהו רבות מח'<sup data-n=\"4516\">68</sup> בלב איש הם ריבוי המח' הטורדות ומבלבלות אותו, וכאשר יתבונן האדם מאחר דעצת ה' היא תקום א\"כ מהו הפעולה מהמח' שלו, אך היצה\"ר מסתיר ומעלים מאד, וזהו שהאהבה מוסתרת מאד, אך הנה כתי' אם יהי' נדחך<sup data-n=\"4517\">69</sup> בקצה השמים משם יקבצך ה' אלקיך, נדחך הו\"ע פזור הנפש, וזהו שא' המן ישנו עם אחד<sup data-n=\"4518\">70</sup>, עם הוא ל' עוממות<sup data-n=\"4519\">71</sup> כמו גחלים שעומדים להכבות, וזהו שעם הם בבחי' שינה, וזהו מצד קליפת עמלק, ולכן הם מפוזר ומפורד בין העמים, אבל ההארה מפנימיות הלב קובץ ואוסף<sup data-n=\"4520\">72</sup>",[["4509","61","<b>אתה קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["4510","62","<b>לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל הנחה ד\"ה ישקני מנשיקות פיהו על יד הערה 19."],["4511","63","<b>אין מזל לישראל</b>: שבת קנו, א. ראה מאמרי אדה\"א שמות ח\"ב ע' שפ. וש\"נ."],["4512","64","<b>ואתם תהיון לי</b>: יתרו יט, ו [ושם: תהיו]."],["4513","65","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה וביום הביכורים על יד הערה 92. ד\"ה ויאמר משה על יד הערה 71. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פי\"ד. פכ\"ב. וש\"נ. תו\"א נח ט, א. ספר המצות להצ\"צ קלח, א<sup data-n=\"e258\">א</sup>. תו\"ח תצוה ח\"ב שנו, ב. וש\"נ סה\"מ תרל\"ח ע' מו. וש\"נ. תרס\"ח ע' רנב. סה\"מ מלוקט ו' ע' צט ובהערה 78."],["4514","66","<b>כלה שארי ולבבי</b>: תהלים שם, כו."],["4515","67","<b>בנפשו יבוא לחמו</b>: ע\"פ פיוט (לימים נוראים) כי כשמך."],["4516","68","<b>רבות מח'</b>: משלי יט, כא."],["4517","69","<b>אם יהי' נדחך</b>: נצבים ל, ד."],["4518","70","<b>ישנו עם אחד</b>: אסתר ג, ח."],["4519","71","<b>עם הוא ל' עוממות</b>: שער היחוד והאמונה פ\"ז. ראה אוה\"ת שמות ע' פט. סה\"מ תר\"ס ע' ה."],["4520","72","<b>ואוסף</b>: ע\"כ נמצא בגוכתי\"ק. ראה ההמשך לעיל בהמשך מצה זו כאן.\n\n<b>א</b>  ראה גם סה\"מ באתי לגני ח\"ב ע' קג וע' קה. סה\"מ מלוקט ו' ע' קלה. מגדל עז ע' קעג."]]],[2000470481,"<h3>אל יתהלל החכם</h3>\n<b></b><b>ל\"ג בעומר יום ה' תר\"ם לפ\"ק</b>\nל\"ג בעומר יום ה'\n<b>אל</b> יתהלל החכם<sup data-n=\"4521\">1</sup> בחכמתו והגבור בגבורתו<sup data-n=\"4522\">2</sup> כו' כי אם בזאת יתהלל המתהלל<sup data-n=\"4523\">3</sup> השכל וידע אותי וצ\"ל למה לא יתהלל החכם כו'. והענין דהנה זאת הוא בחי' מל'<sup data-n=\"4524\">4</sup> ואמרז\"ל בינה יתירה ניתנה באשה<sup data-n=\"4525\">5</sup> מבאיש וצ\"ל מהו הבינה יתירה. והענין דהנה ארז\"ל הנחיל יצחק לב' בניו ליעקב את הקול<sup data-n=\"4526\">6</sup> וכמ\"ש הקל קול יעקב<sup data-n=\"4527\">7</sup> קלא קדמאה חסר ו' הוא קלא דלא אשתמעא קלא בתראה מלא ו' הוא קלא דאשתמעא<sup data-n=\"4528\">8</sup>. אך מה שנוגע לכאן הוא קלא דאשתמעא ואמרז\"ל הנחיל ליעקב את הפה<sup data-n=\"4529\">9</sup> שהוא קלא דאשתמעא. והנה צ\"ל תחילה ענין יעקב. הנה שרש יעקב הוא יסוד אבא שבוקע יסוד ויוצא ומאיר חוץ לז\"א<sup data-n=\"4530\">10</sup> וזהו יעקב אותיות יבקע<sup data-n=\"4531\">11</sup> פי' שבוקע יסו\"א ומאיר חוץ לז\"א, וזהו יסו\"א ארוך<sup data-n=\"4532\">12</sup> שנמשך עד למטה, וזהו שאמרז\"ל יעקב לא מת<sup data-n=\"4533\">13</sup>, דשרשו מחכ' ובחכ' לא הי' שבירה<sup data-n=\"4534\">14</sup> וכמ\"ש ימותו ולא בחכ'<sup data-n=\"4535\">15</sup>, ובכהאריז\"ל אי' שהוא מאחוריים דאבא<sup data-n=\"4536\">16</sup> [מ\"מ ה\"ז חכ'] וזהו וירא כי לא יכול לו<sup data-n=\"4537\">17</sup> שהוא דימה שרשו ממדות מפני שהי' מרכבה<sup data-n=\"4538\">18</sup> למדת הת\"ת<sup data-n=\"4539\">19</sup>, אך באמת שרשו מחכ' וזהו וירא שראה ששרשו מחכ' ולכן לא יכול לו שאין לו שליטה שם,",[["4521","1","<b>אל יתהלל החכם</b>: הנחת<sup data-n=\"e259\">א</sup> כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה<sup data-n=\"e260\">ב</sup> שנדפס לעיל בחלק המאמרים בהמשך מצה זו פ\"כ-פכ\"א. וש\"נ."],["4522","2","<b>אל יתהלל החכם. . בגבורתו</b>: ירמי' ט, כב [ושם: חכם. . ואל יתהלל הגבור — ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תתקטו]."],["4523","3","<b>כי אם בזאת. . וידע אותי</b>: שם ט, כג."],["4524","4","<b>זאת. . מל'</b>: ראה מאו\"א מערכת זאת ס\"ג. שה\"א לה, א הערה 10."],["4525","5","<b>בינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["4526","6","<b>הנחיל יצחק. . ליעקב את הקול</b>: ראה שמו\"ר רפכ\"א."],["4527","7","<b>וכמ\"ש הקל קול יעקב</b>: תולדות כז, כב. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 615."],["4528","8","<b>קלא קדמאה. . דלא אשתמעא. . קלא דאשתמעא</b>: ראה תו\"א וישב כז, ב. הנסמן באוה\"ת וישב ח\"ב ע' 526."],["4529","9","<b>הנחיל ליעקב את הפה</b>: ראה במדב\"ר פ\"כ, יג. לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 619."],["4530","10","<b>יעקב. . יסוד אבא. . חוץ לז\"א</b>: ראה ע\"ח שער הארת המוחין זו\"ן של\"ב, פ\"א."],["4531","11","<b>יעקב אותיות יבקע</b>: נסמן לעיל הנחה ד\"ה בן פורת יוסף הא' הערה 21."],["4532","12","<b>יסו\"א ארוך</b>: ראה ע\"ח שער הכללים פ\"י. מאמרי אדה\"א דברים ח\"ב ע' שעח. וש\"נ. תו\"ח תצוה ח\"ב של, א. וש\"נ."],["4533","13","<b>יעקב לא מת</b>: תענית ה, ב. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 625."],["4534","14","<b>ובחכ' לא הי' שבירה</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ."],["4535","15","<b>ימותו ולא בחכ'</b>: איוב ד, כא. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ג ובהערה 261."],["4536","16","<b>ובכהאריז\"ל. . מאחוריים דאבא</b>: ראה ע\"ח שער המלכים שי\"א, פ\"ח. אוצ\"ח שער המלכים פ\"ד."],["4537","17","<b>וירא כי לא יכול לו</b>: וישלח לב, כו. ראה גם לקמן הנחה ד\"ה ערבים עלי דברי דודיך על יד הערה 19 ואילך. וש\"נ."],["4538","18","<b>שהי' מרכבה</b>: ראה זהר וישלח קעג, ב. לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול הערה 4."],["4539","19","<b>למדת הת\"ת</b>: ראה לעיל (בחלק המאמרים) שם ובהערה 16.\n\n<b>א</b>  ולא נגמר בכתיבתו.\n\n<b>ב</b>  <b>ושם הפתיחא</b>: ויובן עוד ענין בינה יתירה."]]],[2000470482,"וזהו ויצא יעקב מבאר שבע<sup data-n=\"4540\">20</sup> וילך חרנה, יעקב הוא יסו\"א מבאר שבע יסוא\"י<sup data-n=\"4541\">21</sup>, חרנה מל'<sup data-n=\"4542\">22</sup> ובאמת לבי\"ע ג\"כ.\n<b>והנה</b> מדרי' יעקב יש בכל עולם<sup data-n=\"4543\">23</sup>, דהנה כתי' ועמדו רגליו ביום ההוא על הר הזתים, ומפרשים רגליו הם רגלי א\"ק<sup data-n=\"4544\">24</sup> שמסתיימים בעשי'<sup data-n=\"4545\">25</sup>, ומאחר שיש רגל מוכרח לומר שיש ראש ג\"כ דבמדרי' שאינו שייך שום התחלקות אינו שייך ראש ורגל, אלא מאחר שיש רגל יש ראש, וא\"כ הרי יש מדרי' יעקב מחכ' דא\"ק עד תחתיות עשי', אך יש בזה חילוקי מדרי' דאינו דומה בי\"ע לאצי', ובי\"ע גופא א\"ד זל\"ז, וזהו יעקב י' עקב<sup data-n=\"4546\">26</sup> י' הוא בחי' חכ'<sup data-n=\"4547\">27</sup> ונמשך עד עקביים, וזהו מעלת יעקב על ישראל<sup data-n=\"4548\">28</sup> בעצם, והנה גילוי בחי' זו הוא ע\"י תורה שהוא קלא דאשתמע<sup data-n=\"4549\">29</sup>, וזהו הנסתרות לה' אלקינו והנגלות לנו ולבנינו<sup data-n=\"4550\">30</sup>, הנסתרות הם י\"ה חו\"ב, והנגלות ו\"ה נגלות שהו\"ע קול ודיבור הו\"ע<sup data-n=\"4551\">31</sup> קלא דאשתמע, וזהו אל יתהלל החכם בחכמתו כו' הו\"ע החכ' בעצם כי אם בזאת הו\"ע ח\"ת שהו\"ע קלא דאשתמע עי\"ז דוקא השכל ויודע אותי ששרשו מבחי' שלמעלה מהשתל', דהנה בחכ' יש ב' מדרי'<sup data-n=\"4552\">32</sup> עצם החכ' כמו שהיא חכים ולא בחכ' ידיעה<sup data-n=\"4553\">33</sup>, ב' התפשטות החכ' לצורך הבירורים, והתפשטות הוא למעלה מעצם החכ' דכל שלמעלה יותר מתפשט למטה יותר<sup data-n=\"4554\">34</sup>, וכמו עד\"מ ראי' ושמיעה<sup data-n=\"4555\">35</sup>, הרי ראי' למעלה משמיעה מ\"מ ראי' תופס דבר גשמי דוקא ושמיעה תופס את הקול שהוא רוחני ולכאו' הי' צ\"ל בהיפך דראי' שהוא כח היותר נעלה",[["4540","20","<b>ויצא יעקב מבאר שבע</b>: ויצא כח, י."],["4541","21","<b>מבאר שבע יסוא\"י</b>: ראה זהר ויצא קמו, ב ואילך. מק\"מ שם קמז, א ד\"ה נפיק מכללא. ביאוה\"ז ויצא טז, ג. לקו\"ת להאריז\"ל ר\"פ ויצא. אוה\"ת ויצא כרך ה ס\"ע תתלה<sup data-n=\"e261\">ג</sup>."],["4542","22","<b>חרנה מל'</b>: ראה בהערה שלפנ\"ז. ביאוה\"ז שם יז, א. ד. אוה\"ת וארא ע' קעט."],["4543","23","<b>יעקב יש בכל עולם</b>: תו\"א וישב כז, ב."],["4544","24","<b>ועמדו רגליו. . רגלי א\"ק</b>: זכרי' יד, ד. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערות 633 634."],["4545","25","<b>רגלי א\"ק שמסתיימים בעשי'</b>: ראה ע\"ח דרוש עגו\"י ש\"א ענף ד. מאמרי אדה\"א ויקרא ח\"א ע' טו. וש\"נ."],["4546","26","<b>יעקב. . י' עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["4547","27","<b>י'. . חכ'</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן לשם."],["4548","28","<b>מעלת יעקב על ישראל</b>: ראה לקו\"ת בלק ע, ב [נעתק בשינוי קל לעיל (בחלק המאמרים) המשך מצה זו כאן ספ\"כ]."],["4549","29","<b>תורה שהוא קלא דאשתמע</b>: זהר בראשית נ, ב."],["4550","30","<b>הנסתרות לה' אלקינו והנגלות לנו ולבנינו</b>: נצבים כט, כח. ראה ת\"ז ת\"ע קכט, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם."],["4551","31","<b>שהו\"ע. . הו\"ע</b>: כ\"ה בגוכתי\"ק."],["4552","32","<b>בחכ' יש ב' מדרי'</b>: ראה מאמרי אדה\"ז הנחות הר\"פ ע' עט. תקס\"ח ח\"א ס\"ע מב ואילך. ח\"ב ס\"ע תשכו ואילך. אוה\"ת ויצא רז, ב. ירמי' כרך ב ע' תתעח (ס\"ג). ע' תתפ."],["4553","33","<b>חכים ולא בחכ' ידיעה</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."],["4554","34","<b>דכל שלמעלה יותר מתפשט למטה יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. תו\"ח שמות ח\"א כא, ב הערה 863."],["4555","35","<b>ראי' ושמיעה</b>: ראה מאמרי אדה\"ז תקס\"ט ע' פט ואילך. ע' קא.\n\n<b>ג</b>  <b>ושם נדפס</b>: יסוד ראי' — וכנצ\"ל: יסוד דאי'."]]],[2000470483,"יתפוס דבר רוחני ושמיעה יתפוס דבר גשמי, אך היא הנותנת מפני שראי' הוא כח היותר נעלה לכן יוכל להתפשט למטה יותר, אבל שמיעה אינו יכול להתפשט כ\"כ, וזהו שהמילוי הוא גבוה במדריגה יותר מעצם האות וכמ\"ש ועתה יגדל נא<sup data-n=\"4556\">36</sup> כח אד', כח הוא מילוי דמילוי שהוא רק התפשטות האור וכמו יו\"ד העיקר הוא רק האות י' רק ממילא מתפשט גם הו\"ד ושרשו למעלה מעצם היו\"ד וכמו\"כ יובן כאן דהתפשטות החכ' הוא למעלה מעצם החכ', והנה אי' בזהר<sup data-n=\"4557\">37</sup> תרין אינון דלא אשתמעין<sup data-n=\"4558\">38</sup>",[["4556","36","<b>ועתה יגדל נא</b>: שלח יד, יז. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תקצה ואילך (ב' הנוסחאות). אוה\"ת שלח ע' תקב ואילך."],["4557","37","<b>אי' בזהר</b>: בראשית נ, ב."],["4558","38","<b>אשתמעין</b>: ע\"כ נרשם בגוכתי\"ק. ראה לעיל המשך מצה זו כאן המשך הענין."]]],[2000470484,"<h3>צאינה וראינה</h3>\n<b>ש\"פ ב\"ב תר\"ם לפ\"ק</b>\n<b>צאינה</b> וראינה<sup data-n=\"4559\">1</sup> בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו<sup data-n=\"4560\">2</sup> וארז\"ל ביום חתונתו זו מ\"ת<sup data-n=\"4561\">3</sup>, א\"כ הרי כנס\"י נק' כלה והקב\"ה חתן<sup data-n=\"4562\">4</sup> ותורה הוא ג\"כ בחי' חתן<sup data-n=\"4563\">5</sup>, וצ\"ל והלא אמרז\"ל ע\"פ תורה צוה<sup data-n=\"4564\">6</sup> לנו משה מורשה א\"ת מורשה אלא מאורסה<sup data-n=\"4565\">7</sup> הרי תורה היא כלה וכנס\"י חתן, והנה צ\"ל תחילה משארז\"ל בינה יתירה ניתנה באשה<sup data-n=\"4566\">8</sup> יותר מבאיש. והנה ג' דברים נק' אשה דיבור ויראה ותושבע\"פ, ודיבור כבר נת\"ל מה שיש בו בינה יתירה<sup data-n=\"4567\">9</sup>, ועתה צ\"ל ביראה ג\"כ שיש בו בינה יתירה על אהבה, (בפ\"א<sup data-n=\"4568\">10</sup> דהנה כתי' בזאת יבוא אהרן<sup data-n=\"4569\">11</sup> אל הקודש זאת הוא בחי' יראה<sup data-n=\"4570\">12</sup> וכתי' זה השער להוי'<sup data-n=\"4571\">13</sup> שהוא שער ומבוא שיבוא לבחי' קדש העליון,",[["4559","1","<b>צאינה וראינה</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פכ\"ה-פכ\"ז. וש\"נ."],["4560","2","<b>צאינה וראינה. . חתונתו</b>: שה\"ש ג, יא."],["4561","3","<b>ביום חתונתו זו מתן תורה</b>: תענית כו, ב (במשנה). ראה מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' לד. מאמרי אדה\"א דברים ח\"ג ע' תתמז בהערה."],["4562","4","<b>כנס\"י נק' כלה והקב\"ה חתן</b>: וכל שה\"ש מיוסד ע\"ז כידוע במדרשי רז\"ל. ראה גם מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. תו\"ח וארא ח\"א עב, ג ובהערה 7."],["4563","5","<b>ותורה. . חתן</b>: ראה לקו\"ת ברכה צד, א. מאמרי אדה\"א קונטרסים ע' רעג. וש\"נ."],["4564","6","<b>תורה צוה</b>: ברכה לג, ד."],["4565","7","<b>א\"ת מורשה אלא מאורסה</b>: ברכות נז, א. ראה גם שער האמונה סט, א הערה 12. סה\"מ תרל\"ח ע' קנה."],["4566","8","<b>בינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["4567","9","<b>ודיבור. . נת\"ל. . בינה יתירה</b>: הנחה ד\"ה גל נעול (ד\"ה וביאור הענין דהנה)."],["4568","10","<b>בפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4569","11","<b>בזאת יבוא אהרן</b>: אחרי טז, ג."],["4570","12","<b>זאת הוא בחי' יראה</b>: ראה זהר אחרי נו, ב. בהר קח, א. מאמרי אדה\"א ויקרא ח\"א ע' סב."],["4571","13","<b>זה השער להוי'</b>: תהלים קיח, כ."]]],[2000470485,"וביאור הענין) דהנה אהוי\"ר הם מ\"ע ומל\"ת אהבה הוא מקור רמ\"ח מ\"ע יראה הוא מקור שס\"ה ל\"ת<sup data-n=\"4572\">14</sup> וכשנבין ההפרש בין מ\"ע למל\"ת יובן ההפרש בין אהוי\"ר, דהנה מל\"ת הוא ביטל שכופה א\"ע ואינו רוצה בשום דבר והוא בבחי' שב ואל תעשה, הגם דמ\"ע הוא ג\"כ ביטל היש אך הוא קום ועשה אבל מל\"ת הוא שאינו רוצה בשום דבר א\"כ הרי הביטל גדול עד מאד.\n<b>והענין</b> דהנה בעבודה יש ב' מדרי' חותם שוקע וחותם בולט, חותם שוקע הוא ביטל דמ\"ע וחותם בולט הוא ביטל דמל\"ת דאי' בע\"ח שיש (בפ\"א בעליות) בביטל ב' מדרי' א' כמו עליות העולמות שבשבת<sup data-n=\"4573\">15</sup> שעולם התחתון נתעלה לעולם העליון (בפ\"א מלביש חיצונית דעולם העליון) ועולם העליון מתלבש תוך פנימיות דעולם התחתון, הרי מלמטלמ\"ע הוא חותם בולט שה\"ה מתעלה כו' ומלמעלמ\"ט הוא חותם שוקע ביטל הב' הוא ענין העבור תלת כלילן גו תלת<sup data-n=\"4574\">16</sup> ראשו בין ברכיו<sup data-n=\"4575\">*17</sup> שהוא בביטל כ\"כ עד שאין בו התחלקות דראש ורגל וזהו שהעולם התחתון נכלל בעולם העליון הרי מלמטלמ\"ע הוא חותם שוקע ומלמעלמ\"ט הוא חותם בולט שעי\"ז נמשך מוחין חדשים והו\"ע יצ\"מ דשעבוד מצרים הוא בחי' עבור והגאולה הוא שנמשך מוחין חדשים ואי' בפע\"ח<sup data-n=\"4576\">17</sup> שהם מוחין גבוהים שאינם נמשכים בסדר הדרגה, דכל הגילוים הם בסדר הדרגה אבל מוחין אלו הם שלא בסדר הדרגה, וכמ\"ש קול דודי הנה זה בא מדלג על ההרים<sup data-n=\"4577\">18</sup> וכתי' עד שנגלה עליהם<sup data-n=\"4578\">19</sup> מלך מלכי המלכים הקב\"ה ה\"ז שלא בסדר הדרגה, וזהו משארז\"ל אשה מזרעת תחלה<sup data-n=\"4579\">20</sup> יולדת זכר אשה הוא יסוד דנוק' חותם שוקע מלמטלמ\"ע יולדת זכר נמשך מלמעלה חותם בולט, דבגילוים יש ב' מדרי' א' מה שנמשך התלבשות אוב\"כ<sup data-n=\"4580\">21</sup>, ב' בחי' שלמעלה מהתלבשות אוב\"כ, וזהו איש מזריע תחילה יולדת נקבה הו\"ע התלבשות אוב\"כ, אך אשה מזרעת תחילה יולדת זכר הוא כמ\"ש חשף ה' את זרוע קדשו<sup data-n=\"4581\">22</sup> הוא מדרי' שלמעלה מהתלבשות אוב\"כ, ובד\"כ הוא חותם שוקע וחותם בולט, חותם שוקע הו\"ע מל\"ת שהוא ביטל היש באתכפיי' ואתהפכא עד שיהי' שב ואל תעשה רק חותם שוקע היינו כלי ריקן לקבל, ומ\"ע הם חותם בולט שהו\"ע אהבה אך מ\"מ מי<sup data-n=\"4582\">*23</sup> שאוהב<sup data-n=\"4583\">**23</sup> לכן נק' חותם בולט.",[["4572","14","<b>אהבה. . רמ\"ח מ\"ע יראה. . שס\"ה ל\"ת</b>: ראה תניא פ\"ד ובמ\"מ, הגהות והע\"ק לשם. של\"ה מאמר ג ומאמר ד נא, ב. מאמרי אדה\"א קונטרסים ע' פז, וש\"נ."],["4573","15","<b>בע\"ח. . עליות העולמות שבשבת</b>: ראה שם שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667."],["4574","16","<b>תלת כלילן גו תלת</b>: ראה זהר תוספתא בשלח נ, סע\"א. ע\"ח שער הכללים פ\"ג. שער הולדת או\"א וזו\"ן שט\"ז, פ\"ה. ביאוה\"ז בשלח מז, ג ואילך. שעה\"י קל, ב הערה 18."],["4575","*17","<b>ראשו בין ברכיו</b>: נדה ל, ב."],["4576","17","<b>בפע\"ח</b>: שער חהמ\"צ שכ\"א, פ\"א."],["4577","18","<b>קול דודי. . ההרים</b>: שה\"ש ב, ח."],["4578","19","<b>עד שנגלה עליהם</b>: נוסח ההגדה. ראה לקו\"ת שה\"ש יד, ד."],["4579","20","<b>אשה מזרעת תחלה</b>: נדה לא, א."],["4580","21","<b>אוב\"כ</b>: אור בכלי."],["4581","22","<b>חשף ה' את זרוע קדשו</b>: ישעי' נב, י."],["4582","*23","<b>מי</b>: אוצ\"ל: יש מי."],["4583","**23","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם תו\"א וארא נו, א. יתרו סז, ג. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."]]],[2000470486,"<b>והנה</b> להבין מה נק' למעלה חותם שוקע וחותם בולט, הנה תרי\"ג מצות דאורייתא וז' מצות דרבנן הם תר\"ך<sup data-n=\"4584\">23</sup> עמודי אור שהוא בגימ' כתר<sup data-n=\"4585\">*24</sup> דהנה תרי\"ג מצות הם תרי\"ג ארחין דגולגלתא<sup data-n=\"4586\">24</sup> וז' מצות דרבנן הם למעלה מתרי\"ג<sup data-n=\"4587\">25</sup> מצות דאורייתא דהז' מצות הם מ\"ע קום ועשה מ\"מ כלול בהם ל\"ת ג\"כ הרי שרשם למעלה מתרי\"ג כו'. והנה מ\"ע הם ו\"ה היינו ז\"ת דאריך או ז\"ת דעתיק דאו\"א שהלבישו לזרועות דא\"א<sup data-n=\"4588\">27</sup> הרי חו\"ב מלבישים חו\"ג וא\"כ מכ\"ש ג\"ר דא\"א מלבישים ז\"ת דעתיק וזהו\"ע מ\"ע שהם ז\"ת דעתיק שהם חותם שוקע, אבל מל\"ת הם י\"ה<sup data-n=\"4589\">26</sup> והיינו ג\"ר דעתיק שאינם מתלבשים בא\"א וזה נק' חותם בולט, והנה אי' בע\"ח<sup data-n=\"4590\">28</sup> דז\"ת דעתיק כשהם מתלבשי' בא\"א שייך בהם השגה אבל ג\"ר דעתיק שאינם מתלבשים בא\"א אינו שייך בהם השגה כלל ולכן נק' (רדל\"א) רישא דלא ידע ולא אתיידע שבא\"א גופא ג\"כ אינו ידוע וזה ממשיכים ע\"י מל\"ת וזהו בינה יתירה ניתנה באשה שהוא מל\"ת שעי\"ז ממשיכים מג\"ר דעתיק, (ובפ\"א<sup data-n=\"4591\">29</sup> מ\"ע ו\"ה ז\"ת דא\"א ונק' חותם שוקע דאו\"א שהלבישו כו' לכן נק' חותם שוקע, ומל\"ת הם ג\"ר דא\"א שאינם מתלבשים לכן נק' חותם בולט, וזהו כמ\"ש במ\"א דע\"י מ\"ע ממשיכים מז\"ת וע\"י מל\"ת ממשיכים מג\"ר<sup data-n=\"4592\">30</sup>, ובע\"ח אי' דז\"ת דעתיק הם מתלבשים בג\"ר דא\"א אבל ג\"ר דעתיק אינם מתלבשים כלל וא\"כ י\"ל שזהו\"ע חותם שוקע היינו ז\"ת דעתיק וחותם בולט היינו ג\"ר דעתיק שאינם מתלבשים כלל, וזהו שנק' רישא כו' שבא\"א כו' ידוע, אך עיקר הפי' הוא כמ\"ש בע\"ח דחיצוניות עתיק אפשר להתגלות עכשיו ג\"כ אבל פנימיות דעתיק<sup data-n=\"4593\">31</sup> א\"א שיתגלה עכשיו כ\"א לע\"ל דוקא א\"כ אפי' פנימיות יסוד דעתיק נק' ג\"כ חותם בולט וזהו מ\"ש וברית שלומי לא תמוט לעולם<sup data-n=\"4594\">32</sup> ).\n<b>והנה</b> כמו שנת\"ל במ\"ע ומל\"ת כמו\"כ יובן בתורה ג\"כ דהנה כתי' וקבלו היהודים את אשר החלו לעשות<sup data-n=\"4595\">33</sup> ואמרז\"ל דבמ\"ת רק החלו לעשות והדר",[["4584","23","<b>תרי\"ג. . וז'. . תר\"ך</b>: ראה גם לעיל הנחה ד\"ה סמכוני באשישות ובהערות 80-84."],["4585","*24","<b>תר\"ך. . בגימ' כתר</b>: ראה ע\"ח שער ז\"א שי\"ז, ספ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'רצט. וש\"נ."],["4586","24","<b>תרי\"ג מצות. . ארחין דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["4587","25","<b>וז' מצות. . למעלה מתרי\"ג</b>: ראה גם מאמרי אדה\"ז תקס\"ד (כאן) ע' נב וע' נו. מאמרי אדה\"א נ\"ך ע' סד."],["4588","27","<b>דאו\"א שהלבישו לזרועות דא\"א</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד."],["4589","26","<b>מ\"ע הם ו\"ה. . מל\"ת הם י\"ה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו רפי\"ב ובהנסמן שם."],["4590","28","<b>אי' בע\"ח</b>: שער א\"א שי\"ג, פ\"א-ב."],["4591","29","<b>ובפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4592","30","<b>מ\"ע. . מז\"ת. . מל\"ת. . מג\"ר</b>: ראה לקו\"ת שה\"ש י, ב."],["4593","31","<b>בע\"ח דחיצוניות עתיק. . פנימיות דעתיק</b>: וכ\"ה לקמן קרוב לסיום פיסקא והענין דהנה. לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 798 מציין: בפע\"ח — שער הק\"ש ש\"ח, רפט\"ו. שער הכוונות שם דרוש ב. וראה גם רמ\"ז לזהר בראשית ד, ד (יא, א) נעתק בלקו\"ת שה\"ש ט, רע\"ג."],["4594","32","<b>וברית שלומי לא תמוט לעולם</b>: ישעי' נד, י [בהוספת תיבת: לעולם]. ראה גם לקו\"ת שה\"ש מו, סע\"ב. אוה\"ת בראשית כרך ו ע' תתרמט. המשך תער\"ב ח\"ב ע' א'ל."],["4595","33","<b>וקבלו היהודים. . לעשות</b>: אסתר ט, כג [ושם: וקבל<sup data-n=\"e262\">א</sup>]. ראה שבת פח, א. לעיל הנחה ד\"ה ויהי בימי אחשורוש בסופה. וש\"נ.\n\n<b>א</b>  ראה לעיל בהנחה ד\"ה ויהי בימי אחשורוש בסופה. וש\"נ."]]],[2000470487,"קבלוהו בימי אחשורוש אז הי' גמר הקבלה, וצ\"ל והלא במעמד הר סיני כתי' ויחן ישראל כולם כאיש אחד<sup data-n=\"4596\">34</sup> והי' במס\"נ דעל כל דיבור ודיבור פרחה נשמתן<sup data-n=\"4597\">35</sup> ה\"ז רק החלו לעשות וגמר הקבלה הוא בימי אחשורוש דוקא, אך מ\"מ כ\"ה האמת. והענין דהנה כתי' איש יהודי הי' בשושן הבירה ושמו מרדכי כו' איש ימיני<sup data-n=\"4598\">36</sup>, ופירש\"י שהי' משבט יהודה<sup data-n=\"4599\">37</sup> וצ\"ל למה נק' איש יהודי מורה שהי' משבט יהודה, וגם צ\"ל דבגזירת המן כתי' להשמיד כו' את כל היהודים<sup data-n=\"4600\">38</sup> והלא בקך\"ז מדינות<sup data-n=\"4601\">39</sup> ודאי גם<sup data-n=\"4602\">40</sup> מאפרים ומנשה ושארי שבטים ומהו אומרו היהודים שבט יהודה דוקא. אך צ\"ל דשם יהודה הוא שם כללי שהוא מורה בכללות עם בנ\"י, דיהודה הו\"ע ביטל והודאה וכמו מודה אני<sup data-n=\"4603\">41</sup>, וכל עיקר השם דיהודה הוא ע\"ש ההודאה וכמ\"ש הפעם אודה את ה'<sup data-n=\"4604\">42</sup> ע\"כ קראה שמו יהודה, וזה יש בכאו\"א מישראל וכמ\"ש יהודה אתה יודוך אחיך ומפרשים שקאי על הביטל דש\"ע<sup data-n=\"4605\">43</sup> דזה יש בכאו\"א מישראל. ולכן נק' בנ\"י בשם יהודים להורות על הביטל. ומרדכי נק' איש יהודי וכמשארז\"ל איש הר הבית<sup data-n=\"4606\">44</sup> שפי' שר, שהוא שר ומושל ומקור המשפיע בנש\"י ולכן נק' איש יהודי.\n<b>וביאור</b> הענין דהנה ארז\"ל מרדכי מן התורה מנין<sup data-n=\"4607\">45</sup> כתי' מר דרור ומתרגמינן מירא דכיא<sup data-n=\"4608\">46</sup>, והנה מור הוא מה שקוראין אותו בגמ' מושקי<sup data-n=\"4609\">47</sup> ומפרשים",[["4596","34","<b>ויחן ישראל כולם כאיש אחד</b>: ראה יתרו יט, ב (בדילוג] וברש\"י. לקו\"ש יתרו כרך כא ע' 104."],["4597","35","<b>דעל כל. . פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג<sup data-n=\"e263\">ב</sup>. וש\"נ. נ\"ך ע' שפא. וש\"נ. תו\"ח בראשית יז, ב. וראה גם תו\"א מג\"א צב, ד<sup data-n=\"e264\">ג</sup> צח, ד<sup data-n=\"e265\">ד</sup>."],["4598","36","<b>איש יהודי. . איש ימיני</b>: אסתר ב, ה."],["4599","37","<b>ופירש\"י שהי' משבט יהודה</b>: ברש\"י: שגלה עם גלות יהודה. . קרוים יהודים. . ואפילו משבט אחר. במגילה יב, סע\"ב: אמר רבב\"ח. . אמו מיהודה. ראה הרי\"ף בע\"י למגילה שם ד\"ה ור\"י אמר. מנות הלוי עה\"פ. תו\"א מג\"א צא, ב. צט, א. לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 808: ופי' רש\"י איש ימיני שהי' משבט בנימין, וא\"כ צ\"ל למה קרי לי' איש יהודי דמשמע שהי' משבט יהודה. ואולי גם כאן צ\"ל כן."],["4600","38","<b>להשמיד. . כל היהודים</b>: אסתר ג, יג."],["4601","39","<b>בקך\"ז מדינות</b>: שם א, א."],["4602","40","<b>ודאי גם</b>: כנצ\"ל: ודאי הי' גם."],["4603","41","<b>מודה אני</b>: לשון המשנה ב\"ב פ\"ט, מ\"י. ועוד. ברכות כח, ב. ועוד. נוסח השכמת הבקר. ועוד."],["4604","42","<b>הפעם אודה את ה'</b>: ויצא כט, לה."],["4605","43","<b>יהודה אתה. . דש\"ע</b>: ויחי מט, ח. ראה תו\"א שם מה, ג."],["4606","44","<b>איש הר הבית</b>: מדות פ\"א, מ\"ב ובתוי\"ט שם. ראה גם אוה\"ת בראשית כרך ג ע' תקמה ואילך."],["4607","45","<b>מרדכי מן התורה מנין</b>: ראה חולין קלט, ב."],["4608","46","<b>מר דרור. . דכיא</b>: תשא ל, כג ובת\"א."],["4609","47","<b>בגמ' מושקי</b>: ברכות מג, א.\n\n<b>ב</b>  וכן במדבר ח\"ב ע' תקמו ואילך. המשך תער\"ב ח\"א ע' ז. סה\"ש תש\"נ ח\"ב ע' 520 (תענוג).\n\n<b>ג</b>  אוה\"ת שם ע' ב'שלב (ובמהדורת תש\"נ ע' קלח).\n\n<b>ד</b>  מאמרי אדה\"ז תקע\"א הנחת כ\"ק אדה\"א ע' קלב. ומגוכתי\"ק הצ\"צ ע' קלט (וכן צ\"ל ברשימת המאמרים שם ע' שיב). אוה\"ת מג\"א ע' רצ."]]],[2000470488,"הרמב\"ם (בהלכות כלי המקדש פ\"א ה\"ב<sup data-n=\"4610\">48</sup> ) ורוב מפרשים<sup data-n=\"4611\">49</sup> לבד הראב\"ד<sup data-n=\"4612\">50</sup> (בהשגות שם) והרמב\"ן (בפי' החומש פ' כי תשא<sup data-n=\"4613\">51</sup> ) שיש מין חי' ידוע שיש חטוטרות בצוארה והדם נצרר שם ומצד חום השמש וחום הטבעי נקרש שם ונעשה בשם הנק' מור (ע' בכ\"מ שם וברמב\"ן שם<sup data-n=\"4614\">52</sup> ) ובעבודה הנה דם הוא ענין תאוות זרות ורצונות זרות (ובפ\"א<sup data-n=\"4615\">53</sup> דם הוא החיוני וכמ\"ש כי הדם הוא הנפש<sup data-n=\"4616\">54</sup> והוא מלא מתאוות כו') וצריכים להפוך אותו וכמ\"ש מאן דמהפך מחשוכא לנהורא<sup data-n=\"4617\">55</sup> וממרירא למיתקא (ובפ\"א מין חי' ידועה<sup data-n=\"4618\">56</sup> הוא ידעוני<sup data-n=\"4619\">57</sup> שבפסוק והוא מגקה\"ט<sup data-n=\"4620\">58</sup> לגמרי וכמ\"ש ושואל לב הידעוני<sup data-n=\"4621\">59</sup> ודורש אל המתים וצריכים להפוך אותו לאלקות). ובזה יובן הפלוגתא בין הפוסקים<sup data-n=\"4622\">60</sup> דעת רבינו יונה דמור מותר באכילה<sup data-n=\"4623\">61</sup> ויש דעה שאינו מותר רק ריחו אבל עצמו אסור באכילה<sup data-n=\"4624\">62</sup>. ולהבין במה קא מיפלגי ע\"ד החסידות, דהנה בענין תשובה יש פלוגתא בגמ' אם זדונות נעשה לו כשגגות או כזכיות<sup data-n=\"4625\">63</sup> ושניהם אומרים שהרע נהפוך לטוב אך כמה הוא נהפוך דעה א' שמתהפכים כמו ממזיד לשוגג ודעה הב' שמתהפכים כ\"כ עד שנעשים זכיות היינו מצוה והוא ע\"י תשובה מאהבה יש בכח להפך הזדון שיהי' זכות ממש היינו מצוה, וזהו ר\"י שמתיר באכילה הוא כדיעה שהזדונות נעשו כזכיות והוא ע\"י תשובה מאהבה, ודעת האוסרים הוא כהדיעה הב' בגמ' שהזדונות נעשים כשגגות שרק ריחו מותר אבל עצם הדבר אסור, והנה מרדכי הוא מירא דכיא (בפ\"א שהוא יסו\"א<sup data-n=\"4626\">64</sup> ) שהי' מקור המשפיע ביטל בנש\"י מבחי' יסו\"א שהוא בחי' חכ' כח מה<sup data-n=\"4627\">65</sup> ביטל לאלקות, והלעו\"ז הי' המן שהי' גס הרוח שהחשיב א\"ע למציאות היש עד שכל דבר לא תפס מקום אצלו כלל וזהו שאמר למי יחפוץ המלך<sup data-n=\"4628\">66</sup> לעשות יקר יותר ממני שהי' מציאות היש מאד שהי' מזרעו של",[["4610","48","<b>הרמב\"ם. . ה\"ב</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 816."],["4611","49","<b>ורוב מפרשים</b>: ראה גם לעיל שם הערה 818."],["4612","50","<b>הראב\"ד</b>: ראה גם לעיל שם הערה 820."],["4613","51","<b>והרמב\"ן. . כי תשא</b>: ל, כג."],["4614","52","<b>וברמב\"ן שם</b>: ראה גם לעיל (בחלק המאמרים) שם הערה 822."],["4615","53","<b>ובפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4616","54","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["4617","55","<b>מאן דמהפך מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. לעיל (בחלק המאמרים) המשך מצה זו הערה 286."],["4618","56","<b>מין חי' ידועה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן שוה\"ג הב' להערה 817."],["4619","57","<b>חי' ידועה הוא ידעוני</b>: ראה רש\"י קדושים יט, לא. פ' שופטים יח, יא. פרישה לטור שם אותיות ה-ו."],["4620","58","<b>ידעוני. . מגקה\"ט</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערות 831-832."],["4621","59","<b>ושואל לב הידעוני</b>: פ' שופטים יח, יא [ושם: אוב וידעוני]."],["4622","60","<b>הפלוגתא בין הפוסקים</b>: ראה טושו\"ע או\"ח סרט\"ז, ס\"ב ובנו\"כ שם."],["4623","61","<b>דעת רבינו יונה. . באכילה</b>: לברכות שם ד\"ה ורבינו מאיר הלוי. וראה גם רמב\"ן תשא שם. מאמרי אדה\"ז תקע\"א ע' קלד."],["4624","62","<b>ויש דעה. . אסור באכילה</b>: רמ\"הה ברבינו יונה שם. מאמרי אדה\"ז תקע\"א שם."],["4625","63","<b>אם זדונות. . כזכיות</b>: יומא פו, ב."],["4626","64","<b>מרדכי. . יסו\"א</b>: ראה פע\"ח שער הפורים שי\"ט, פ\"ה."],["4627","65","<b>חכ' כח מה</b>: זהר רע\"מ צו כח, א. לד, א."],["4628","66","<b>למי יחפוץ המלך</b>: אסתר ו, ו."]]],[2000470489,"עמלק<sup data-n=\"4629\">67</sup> אשר עליו נא' ראשית גוים עמלק<sup data-n=\"4630\">68</sup> דז' אומות הכנעני והחתי<sup data-n=\"4631\">70</sup> כו' הם ז' מדות רעות<sup data-n=\"4632\">69</sup> וראשית גוים עמלק שהי' גס הרוח שהוא מקור של כל המדות<sup data-n=\"4633\">71</sup> רעות והמן הי' מזרע של עמלק לכן גס הרוח ובקש להשמיד את כל היהודים מפני שהיו בטל לאלקות וא\"כ אינו נחשב הוא למציאות, והוא הי' (כופר) בכל לכן רצה לבטל את כל הענין, וזהו שכ' להשמיד את כל היהודים דוקא מפני שהם יהודים דהיינו שהם בטלים לאלקות אבל אם היו עוזבים<sup data-n=\"4634\">72</sup> דת יהודים לא הי' רוצה להשמידם, אך מ\"מ לא עלה על לב א' מהם ועמדו במס\"נ כל השנה<sup data-n=\"4635\">73</sup> והי' מוכנים למות ולא לעזוב דת יהודים ח\"ו, וזהו ענין מס\"נ שישנו בכאו\"א מישראל אפי' קל שבקלים<sup data-n=\"4636\">74</sup> יש בו כח למס\"נ לה'<sup data-n=\"4637\">75</sup> הגם שעושה עבירות חמורות שכ' בתורה אשר לא תעשינה הרי אמרז\"ל אין אדם עובר עבירה<sup data-n=\"4638\">76</sup> אא\"כ נכנס בו רוח שטות המכסה על האמת ונדמה לו אשר עודנו ביהדותו ואינו נעשה בזה נפרד מאלקות שהרי מניח טלית ותפילין ומתפלל, אבל אם הי' יודע שבזה נעשה נפרד מאלקות לגמרי לא הי' עושה זאת כלל, והו\"ע האהבה המוסתרת שיש בכאו\"א מישראל רק שהיא מוסתרת ונעלמת וצריכים להוציא אותה מכח אל הפועל.\n<b>והנה</b> אהבה מוסתרת זו הוא למעלה מהשכל ולכן אינו נמצא בתורה ציווי על מס\"נ<sup data-n=\"4639\">77</sup> רק כתי' לאהבה את ה' אלקיך כי הוא חייך<sup data-n=\"4640\">78</sup> אבל מס\"נ אינו נמצא בפסוק ציווי ע\"ז והוא דמ\"ש לאהבה את ה' אלקיך כי הוא חייך כמו שאדם אוהב חיי נפשו כמו\"כ יהי' לו אהבה לאלקות ה\"ז השכל מחייב ועז\"נ<sup data-n=\"4641\">79</sup> ציווי בתורה אבל מס\"נ הוא למעלה מהשכל אינו נא' בתורה ציווי ע\"ז. דהנה לאהבה את ה' אלקיך כי הוא חייך ה\"ז בחי' ממכ\"ע וסוכ\"ע<sup data-n=\"4642\">80</sup> שהוא מקור על עולמות וכמ\"ש ואתה מחי' את כולם<sup data-n=\"4643\">81</sup>, אבל הנה כתי' אני ה' לא שניתי<sup data-n=\"4644\">82</sup> שלא יש שום שינוי בין קודם הבריאה",[["4629","67","<b>מזרעו של עמלק</b>: אסתר ג, א ובתרגום שם. ראה לקו\"ש פ' זכור כרך ג ע' 913 הערות 1-2."],["4630","68","<b>ראשית גוים עמלק</b>: בלק כד, כ. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 844."],["4631","70","<b>הכנעני והחתי</b>: נחמי' ט, ח. ראה גם לעיל בההמשך כאן הערה 846."],["4632","69","<b>דז' אומות. . הם ז' מדות רעות</b>: ראה גם לעיל לעיל (בחלק המאמרים) כאן ובהערה 845."],["4633","71","<b>המדות</b>: אולי כצ\"ל."],["4634","72","<b>אם היו עוזבים</b>: נסמן לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 851."],["4635","73","<b>במס\"נ כל השנה</b>: ראה גם תו\"א מג\"א צז, א. מאמרי אדה\"ז תקס\"ו ע' קכב. סה\"מ מלוקט ב' ע' ער ובהערה 56."],["4636","74","<b>קל שבקלים</b>: ע\"פ ר\"ה כה, ב. תוספתא שם ספ\"א. קה\"ר פ\"א ד [ד]. רש\"י ויצא כט, כא."],["4637","75","<b>קל שבקלים. . למס\"נ לה'</b>: ראה תניא פי\"ח. מאמרי אדה\"א הנחות תקע\"ז ע' קלד. וש\"נ. לקו\"ש חנוכה כרך ג ע' 818 בהערה. סה\"מ מלוקט ד' ע' קפח בהערה."],["4638","76","<b>אין אדם עובר עבירה</b>: סוטה ג, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תרמה. וש\"נ."],["4639","77","<b>אינו נמצא בתורה ציווי על מס\"נ</b>: וכ\"ה בסמוך בפנים. ראה הלשון לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 855."],["4640","78","<b>לאהבה את ה' אלקיך כי הוא חייך</b>: נצבים ל, כ."],["4641","79","<b>ועז\"נ</b>: אולי: ועז\"כ."],["4642","80","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["4643","81","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["4644","82","<b>אני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל הנחה ד\"ה ויהי הענן והחשך על יד הערה 13. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי על יד הערה 102. ד\"ה יפה שעה הא' על יד הערה 95. ד\"ה אני לדודי הא' על יד הערה 31. ד\"ה ובחודש השביעי על יד הערה 94. ד\"ה כנשר יעיר קנו על יד הערה 29. אוה\"ת על ענינים ע' קל ואילך."]]],[2000470490,"לאחר הבריאה אתה הוא קודם שנברה\"ע<sup data-n=\"4645\">83</sup> ואתה הוא לאחר שנברה\"ע שאינו תופס מקום כלל דכללות השתל' המדרי' הוא רק משם והארה בעלמא שאינו נוגע לעצמות כלל וכתי' כי נשגב שמו לבדו<sup data-n=\"4646\">84</sup> שאפי' בחי' נשגב שהוא סוכ\"ע הוא רק שם והארה בעלמא שאינו נוגע לעצמות, כמו שם האדם שאינו עצם, כמו<sup data-n=\"4647\">85</sup> למעלה השם הוא רק הארה בעלמא שאינו נוגע לעצמות כלל, אפי' חיי החיים<sup data-n=\"4648\">86</sup> מקור החיים הרי כתי' כי עמך מקור חיים<sup data-n=\"4649\">87</sup> אפי' מקור החיים הוא רק עמך טפל ובטל לך לכן אתה הוא קודם שנברה\"ע ואפי' אחר שנברה\"ע בשוה, ואם לא הי' ברה\"ע כלל אין זה נוגע לעצמותו כלל ולכן נק' הבריאה בריאה יש מאין<sup data-n=\"4650\">88</sup>, פי' מאין והארה בעלמא, ומ\"ש ואתה מחי' את כולם ותי' ואתה מורה על עצמות אוא\"ס אין זה רק אותיות דמא' עד ת' וה' מוצאות הפה<sup data-n=\"4651\">89</sup> וכמו אותיות בנפש האדם שהם רק בחי' אחרונה כמו\"כ למעלה הם בחי' אחרונה לבד (ע' בלקו\"ת בד\"ה להבין מ\"ש<sup data-n=\"4652\">90</sup> באוצ\"ח<sup data-n=\"4653\">91</sup> אבל עצמות א\"ס הוא מרומם ונשגב מגדר עולמות אפי' מלהיות מקור עליהם דלא שניתי כלל, וזהו\"ע האהבה מוסתרת שיהי' לו אהבה לבחי' שלא שניתי כלל, דלאהבה את ה' אלקיך כו' הוא בחי' ממכ\"ע וסוכ\"ע שהוא מקור העולמות אבל עצמות א\"ס אינו שייך שיהי' מקור על עולמות והאהבה מוסתרת הוא שיהי' לו אהבה לבחי' זו. וכח זה יש בכאו\"א מישראל דהנה בע\"ח (שמ\"א פ\"א)<sup data-n=\"4654\">92</sup> שיש ניצוץ קטן מאד שהוא בחי' אחרונה שבבורא וניצוץ דיחידה שהוא נקרא נשמה דקה ורוחניות מאד ונק' יחידה ע\"ש<sup data-n=\"4655\">93</sup> שמקבלת מא\"ס שהוא יחיד והניצוץ קטן מתלבש בניצוץ זה, (ע\"ש שכ' וניצוץ זה מתלבשת בכח ניצוץ נברא כו', ואפ\"ל שמתלבש בבחי' יחידה שביחידה ע\"ש) ולכן יש בכאו\"א מישראל למס\"נ לה' אחד. ועפ\"ז יובן מ\"ש הדר קבלוה בימי אחשורוש דבמ\"ת רק החלו לעשות כו' הגם דבמעמד הר סיני כתי' וירד ה' על הר סיני<sup data-n=\"4656\">94</sup> והיו במס\"נ דעל כל דבור ודיבור פרחה נשמתן והקדימו נעשה לנשמע<sup data-n=\"4657\">95</sup> ה\"ז רק החלו לעשות וגמר הקבלה הי' בימי אחשורוש דוקא.",[["4645","83","<b>אתה הוא קודם שנברה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["4646","84","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג. ראה תו\"א מג\"א כאן צח, ב. לקו\"ת אמור לא, ג. לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול על יד הערה 49."],["4647","85","<b>כמו</b>: אוצ\"ל: כמו\"כ."],["4648","86","<b>חיי החיים</b>: יומא עא, א. ראה גם תניא פמ\"ד (סג, א)."],["4649","87","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה לקו\"ת אמור לא, ד. לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 50."],["4650","88","<b>בריאה יש מאין</b>: ראה גם תו\"א בשלח סא, ד."],["4651","89","<b>דמא' עד ת' וה' מוצאות הפה</b>: ראה שער היחוד והאמונה פ\"ב."],["4652","90","<b>בלקו\"ת בד\"ה להבין מ\"ש באוצ\"ח</b>: הוספות לויקרא נג, ב ואילך."],["4653","91","<b>באוצ\"ח</b>: כנצ\"ל: באוצ\"ח)."],["4654","92","<b>בע\"ח (שמ\"א פ\"א)</b>: ראה גם לעיל הנחה ד\"ה גל נעול ובהערה 56."],["4655","93","<b>ע\"ש</b>: אינו ברור בגוכתי\"ק."],["4656","94","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["4657","95","<b>והקדימו נעשה לנשמע</b>: שבת פח, א."]]],[2000470491,"<b>והענין</b> דהנה במ\"ת אמרז\"ל כפה עליהם הר כגיגית<sup data-n=\"4658\">96</sup> והיינו אתעדל\"ע המעורר אתעדל\"ת הגם שפעל האתעדל\"ע שנתעוררו ע\"י, אך מ\"מ לא יתעוררו מצ\"ע, אבל בימי אחשורוש התעוררו מצ\"ע שעמדו במס\"נ כל השנה במה שנשאו ע\"ע שם יהודים היינו שהיו בטל לאלקות וההתעוררות הי' מצ\"ע ה\"ז מ\"ש אשה מזרעת תחלה יולדת זכר, דהנה כתי' מה ראו על ככה<sup data-n=\"4659\">97</sup> ומה הגיע עליהם, דבחי' מ\"ה הגיע עליהם, דהנה יש ב' מדרי' מ\"ה וב\"ן<sup data-n=\"4660\">98</sup>, ב\"ן הוא ירידת האור בהשתל' המדרי', ומ\"ה הו\"ע ביטל לאלקות, ובימי אחשורוש שהיו בטלים לאלקות במס\"נ בפ\"מ ומצ\"ע המשיכו בחי' מ\"ה וזהו מ\"ה הגיע כו' רק דאלמלא עזרו<sup data-n=\"4661\">99</sup> לא היה יכול אין זה שייך להאתעדל\"ע<sup data-n=\"4662\">100</sup>, אבל מ\"ת הי' באתעדל\"ע אתעדל\"ת לא המשיכו רק בחי' ב\"ן, וה\"ז ע\"ד ההפרש בין ביטל דאלי' לביטל דמשה, דאלי' זיכך גופו עד שעלה בסערה השמימה שגם גופו נתעלה<sup data-n=\"4663\">101</sup>, מ\"מ הביטל דמשה הוא גבוה יותר, דאלי' זיכך גופו אבל בתחילה כשהי' נשמה מלובשת בגוף הי' באו\"א, אבל משה נא' עליו ואנחנו<sup data-n=\"4664\">102</sup> מה<sup data-n=\"4665\">103</sup> דגם כמו שהי' מלובש בגוף הי' ג\"כ בבחי' מה, או י\"ל ע\"ד ההפרש בין משה ואהרן דעל שניהם נא' ואנחנו מה מ\"מ יש הפרש ביניהם דאהרן הי' ב\"ן<sup data-n=\"4666\">104</sup> ומשה הי' מה דמה<sup data-n=\"4667\">105</sup>, ב\"ן דמה הוא בחי' יולדת נקבה ומ\"ה דמ\"ה הוא בחי' יולדת זכר, וזהו שבמ\"ת הי' רק ההתחלה ובימי אחשורוש הי' גמר הקבלה, דהנה בתורה יש כמה מדרי' וע\"י המס\"נ שלהם המשיכו מדרי' בתורה מה שנק' משל הקדמוני<sup data-n=\"4668\">106</sup> שהוא משל לא\"ס קדמונו ש\"ע<sup data-n=\"4669\">107</sup> מקדם אשר לא נעשה<sup data-n=\"4670\">108</sup> ובכלל הוא מדרי' חכ', וזהו תורה צוה לנו משה מורשה א\"ת מורשה אלא מאורסה שהתורה נק' כלה וכנס\"י חתן, והיינו מה שהמשיכו במ\"ת והו\"ע יולדת נקבה, אבל בימי אחשורוש שאז הי' גמר הקבלה זהו מה שהתורה נק' חתן<sup data-n=\"4671\">109</sup> שהוא בחי' יולדת זכר וכנס\"י נק' חתן ע\"ש כלתה נפשי<sup data-n=\"4672\">110</sup> שהוא כליון ותשוקה לאלקות והו\"ע אשה מזרעת תחילה עי\"ז יולדת זכר. והנה לפי' הא' שהו\"ע מ\"ע ומל\"ת יובן ג\"כ כנ\"ל",[["4658","96","<b>כפה עליהם הר כגיגית</b>: שבת פח, א. ראה תו\"א מג\"א כאן צח, ד. ש\"א ב, ב הערה 33."],["4659","97","<b>מה ראו על ככה</b>: אסתר ט, כו [ושם ומה — אבל כ\"ה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 877]."],["4660","98","<b>ב' מדרי' מ\"ה וב\"ן</b>: ראה ע\"ח שער שביה\"כ ש\"ט, פ\"ז. לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 879."],["4661","99","<b>דאלמלא עזרו</b>: ראה קדושין ל, ב. סוכה נב, ב. תניא רפי\"ג."],["4662","100","<b>אין זה שייך להאתעדל\"ע</b>: לעיל (בחלק המאמרים) המשך מצה זו כאן הלשון: א\"כ נמשך גם אתעדל\"ע להולדת בחי' ביטול זה."],["4663","101","<b>דאלי'. . שגם גופו נתעלה</b>: ראה מלכים-ב ב, יא. לעיל (בחלק המאמרים) המשך מצה זו ספ\"ד ובהערה 157."],["4664","102","<b>ואנחנו</b>: ראה גם לעיל הנחה ד\"ה הנה אנכי כורת ברית ובהערה 29."],["4665","103","<b>ואנחנו מה</b>: ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח ספכ\"א הערה 593."],["4666","104","<b>ב\"ן</b>: כנצ\"ל: ב\"ן דמה."],["4667","105","<b>דאהרן הי' ב\"ן דמה ומשה הי' מה דמה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 884."],["4668","106","<b>בתורה. . משל הקדמוני</b>: שמואל-א כד, כג וברש\"י שם. ראה גם לעיל (בחלק המאמרים) כאן ובהערה 885."],["4669","107","<b>קדמונו ש\"ע</b>: ב\"ר פל\"ח, ז. זהר לך פד, א."],["4670","108","<b>מקדם אשר לא נעשה</b>: ע\"פ ישעי' מו, י."],["4671","109","<b>חתן</b>: אוצ\"ל: כלה."],["4672","110","<b>כלתה נפשי</b>: תהלים פד, ג. ראה גם תו\"ח בשלח ח\"א רח, א ובהערה 19."]]],[2000470492,"דמ\"ע הם ו\"ה ז\"ת דעתיק ומל\"ת הם י\"ה ג\"ר דעתיק, ובאמת הנה אי' בע\"ח דחיצוניות דעתיק אפשר שיאיר ויתגלה עכשיו ג\"כ אבל פנימית דעתיק א\"א שיתגלה עכשיו רק לע\"ל דוקא וא\"כ גם פנימיות דיסוד דעתיק הוא ג\"כ נק' חותם בולט (וזהו מ\"ש בע\"ח דבעתיק יש מ\"ה וב\"ן<sup data-n=\"4673\">111</sup> הגם שאינו שייך שם זו\"נ [דלית שמאלא בהאי עתיקא<sup data-n=\"4674\">112</sup> ] מ\"מ ה\"ז פנים ואחור, ב\"ן שבו הוא בחי' יולדת נקבה ומ\"ה שבו הוא בחי' יולדת זכר) ובד\"כ הם ז\"ת דעתיק וג\"ר דעתיק, וזהו בינה יתירה ניתנה באשה כו' בינה הוא בן י\"ה<sup data-n=\"4675\">113</sup> וזהו סתם בינה, אך בינה יתירה הוא ג\"ר דעתיק וע\"ד מ\"ש אד' מי יעמוד<sup data-n=\"4676\">114</sup>, אד' כמו שהוא בבחי' מי הוא בינה דעתיק, וכמו\"כ יובן כאן דבינה יתירה היינו ג\"ר דעתיק [ובד\"כ] הוא מדרי' חכ' ויר\"ע שרשו בחכ'<sup data-n=\"4677\">115</sup> ויר\"ת שרשו מיר\"ע<sup data-n=\"4678\">116</sup> וזהו בזאת יבא אהרן אל הקדש ע\"י יר\"ת יבא לבחי' קדש העליון שהוא קדש מילי' בגרמי'<sup data-n=\"4679\">117</sup>.\n<b>וזהו</b> צאינה וראינה כו' בעטרה שעטרה לו אמו ביום חתונתו זו מ\"ת, דהנה מה שהדר קבלוה בימי אחשורוש מ\"מ לא הי' מ\"ת עוד הפעם ומוכרח לומר שבמ\"ת הי' ע\"ז<sup data-n=\"4680\">118</sup> ג\"כ, וסמכוהו חכמים על מה שכתוב צאינה כו' בעטרה שעטרה לו אמו הוא בחי' כתר עטרה ע\"ג הראש ביום חתונתו שהוא מה שהתורה נק' חתן, וכח זה הי' במ\"ת רק שלא הי' אפ\"ל בגילוי דבמ\"ת הי' באתעדל\"ע אתעדל\"ת אך כח ע\"ז הי' במ\"ת ג\"כ ואחר שכבר קבלוה בימי אחשורוש מצאו חכמים את בחי' בתורה<sup data-n=\"4681\">119</sup> מ\"ש צאינה וראינה בעטרה כו' ביום חתונתו שכנס\"י נק' כלה שהי' כליון ותשוקה לאלקות ותורה נק' בחי' חתן והו\"ע יולדת זכר וזהו צאינה וראינה כו'.",[["4673","111","<b>דבעתיק יש מ\"ה וב\"ן</b>: ראה ע\"ח שער עתיק שי\"ב, פ\"א. פ\"ב."],["4674","112","<b>דלית שמאלא בהאי עתיקא</b>: ראה זהר אד\"ר נשא קכט, א. ע\"ח שער עתיק שי\"ב, פ\"ב. שער הארת המוחין של\"ב, פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["4675","113","<b>בינה בן י\"ה</b>: ראה זהר רע\"מ תרומה קנח, א. נשא קכג, סע\"א. אגה\"ת פ\"ח. תו\"ח שמות ח\"א מז, א. וש\"נ."],["4676","114","<b>אד' מי יעמוד</b>: תהלים קל, ג. ראה זהר בלק קפה, ב. לקו\"ת שלח מ, א. אוה\"ת קרח ע' תשא. סה\"מ תרכ\"ו ע' קמה. ע' רנט."],["4677","115","<b>ויר\"ע שרשו בחכ'</b>: ראה תו\"א מקץ מא, ג."],["4678","116","<b>ויר\"ת שרשו מיר\"ע</b>: ראה תו\"א ויקהל קיד, ד. מאמרי אדה\"א דברים ח\"ב ע' תרנט. וש\"נ. תו\"ח בראשית כא, ג ובהערה 22."],["4679","117","<b>קדש מילי' בגרמי'</b>: זהר אמור צד, ב."],["4680","118","<b>הי' ע\"ז</b>: אוצ\"ל: הי' כח ע\"ז."],["4681","119","<b>בחי' בתורה</b>: אוצ\"ל: בחינתה בתורה? בחי' זו בתורה?"]]],[2000470493,"<h3>וירא העם וינועו</h3>\n<b></b><b>ש\"פ במדבר ערב חגה\"ש תר\"ם לפ\"ק</b>\nש\"פ במדבר ערב חגה\"ש\n<b>וירא</b> העם וינועו<sup data-n=\"4682\">1</sup> ויעמדו מרחוק<sup data-n=\"4683\">2</sup>. הנה זה הי' קודם מ\"ת<sup data-n=\"4684\">3</sup>, וינועו מפרשים ל' זיעה (ע' בסד\"ה וביום<sup data-n=\"4685\">4</sup> ) שהיראה הי' כ\"כ עד שהזיעו, וצ\"ל מה שייך יראה למ\"ת, והנה אמרז\"ל אלפים שנה קדמה תורה לעולם<sup data-n=\"4686\">5</sup> וג\"ז גופא צ\"ל מהו הנ\"מ לן עתה במה שקדמה לעולם, אלא צ\"ל שהוא להורות על מעלות ומדרי' התורה אשר שרשה מאלפים שנה שקדמה לעולם<sup data-n=\"4687\">6</sup> שהוא מדרי' שאינו שייך לעולמות, והנה כתי' בזאת יבא אהרן<sup data-n=\"4688\">7</sup> אל הקדש, ע\"י זאת שהוא יראה<sup data-n=\"4689\">8</sup> יבא אל הקדש העליון שהוא בחי' חכ'<sup data-n=\"4690\">9</sup> וזהו ששייך יראה למ\"ת. ולהבין זה צ\"ל תחילה משארז\"ל בינה יתירה נתנה באשה יותר מבאיש<sup data-n=\"4691\">10</sup>, אשה הוא בחי' יראה<sup data-n=\"4692\">11</sup> וכמ\"ש אשה יראת ה'<sup data-n=\"4693\">12</sup> ויש מעלה יתירה על אהבה וכמ\"ש לע\"ל נקבה תסובב גבר<sup data-n=\"4694\">13</sup> דעכשיו משפיע למעלה ממקבל אבל לע\"ל יהי' המקבל גבוה מהמשפיע.\n<b>וביאור</b> הענין דהנה כתי' כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"4695\">14</sup>, הגם דגילוי של לע\"ל יהי' במדרי' גבוה יותר מ\"מ יהי' הגילוי באופן אחד דכמו במצרים כתי' קול דודי הנה זה בא מדלג על ההרים כמו\"כ לע\"ל יהי' ג\"כ בדרך דילוג, רק ההפרש הוא בין דילוג לקפוץ וזהו מדלג על ההרים מקפץ על הגבעות<sup data-n=\"4696\">15</sup>, דילוג ברגל א' קיפוץ בב' רגלים. (ע' בלקו\"ת בד\"ה קול דודי<sup data-n=\"4697\">16</sup> וכמ\"ש באהלות פ\"ח מ\"ה דולג ממקום למקום וקופץ ממקום למקום ופי' הרמב\"ם<sup data-n=\"4698\">17</sup> דולג שרגל א' קיים בארץ ודולג בשני, קופץ שעוקר ב' רגליו כאחת, וע' בד\"ה ששים המה מלכות<sup data-n=\"4699\">18</sup> וצ\"ע). וצ\"ל תחילה שם דילוג, הנה הוא להורות על המשכות אוא\"ס שלמעלה מסדר והדרגה דכל המשכות הם בסדר והדרגה ויש בהם השתל' עו\"ע ובאו\"א<sup data-n=\"4700\">19</sup> אבל דילוג",[["4682","1","<b>וירא העם וינועו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פכ\"ח-פ\"ל. וש\"נ."],["4683","2","<b>וירא העם וינועו ויעמדו מרחוק</b>: יתרו כ, טו."],["4684","3","<b>וירא. . זה הי' קודם מ\"ת</b>: רמב\"ן עה\"פ."],["4685","4","<b>וינועו. . זיעה (ע' בסד\"ה וביום</b>: ראה גם בסיום ההנחה. ולע\"ע לא נתברר לאיזה דרוש כוונתו. ראה גם תו\"ח ויקהל ח\"ב תי, א."],["4686","5","<b>אלפים שנה קדמה תורה לעולם</b>: ראה מדרש תהלים צ, ד. שבת פח, ב וברש\"י שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ. מאמר ד\"ה זה תשי\"א יום ב' דחה\"ש."],["4687","6","<b>התורה. . שקדמה לעולם</b>: ראה גם לקמן הנחה ד\"ה וביום הביכורים על יד הערה 13. פיה\"מ יב, ג ואילך. מאמרי אדה\"א תקע\"ז ע' קלו. סה\"מ תרל\"ח ע' טז. וש\"נ."],["4688","7","<b>בזאת יבא אהרן</b>: אחרי טז, ג."],["4689","8","<b>זאת שהוא יראה</b>: ראה זהר אחרי נו, ב. בהר קח, א. מאמרי אדה\"א ויקרא ח\"א ע' סב."],["4690","9","<b>הקדש. . חכ'</b>: ראה לקמן על יד הערה 62 ואילך ובהנסמן שם."],["4691","10","<b>בינה יתירה. . מבאיש</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["4692","11","<b>אשה. . יראה</b>: ראה זהר ח\"ש קכב, א. פקודי רלט, ב."],["4693","12","<b>אשה יראת ה'</b>: משלי לא, ל."],["4694","13","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["4695","14","<b>כימי צאתך. . נפלאות</b>: מיכה ז, טו."],["4696","15","<b>קול דודי. . ההרים. . מקפץ על הגבעות</b>: שה\"ש ב, ח."],["4697","16","<b>בלקו\"ת בד\"ה קול דודי</b>: שה\"ש טו, סע\"ב."],["4698","17","<b>ופי' הרמב\"ם</b>: אהלות שם."],["4699","18","<b>בד\"ה ששים המה מלכות</b>: לקו\"ת שה\"ש מב, ב."],["4700","19","<b>ובאו\"א</b>: כ\"ה בגוכתי\"ק."]]],[2000470494,"הוא מד' שא\"א שיומשך בסדר והדרגה כ\"א למעלה מהשתל', ודוקא ברגל דאפי' מה שמאיר בסדר והדרגה אינו נמשך רק בחי' אחרונה (בפ\"א<sup data-n=\"4701\">20</sup> נה\"י שבו) וכמו עד\"מ רב המשפיע שכל לתלמיד א\"א שישפיע לו עצם השכל רק הארה ובמספר נק' חלק עשירי<sup data-n=\"4702\">21</sup>, והוא מפני שבמספר שוה חכ' עם דיבור אבל באמת אין ערוך כלל, וכמו\"כ למעלה מה שנמשך הוא רק בבחי' רגל וכמ\"ש ועמדו רגליו<sup data-n=\"4703\">22</sup> כו' והארץ הדום רגלי<sup data-n=\"4704\">23</sup>, ויראו את אלקי ישראל<sup data-n=\"4705\">24</sup> שהי' גילוים כתי' ותחת רגליו כו' וא\"כ מכ\"ש מה שלמעל' מסדר והדרגה א\"א שיומשך רק בחי' רגל, אך דילוג הוא ברגל אחת הוא בחי' אהבה וקיפוץ בב' רגלים הוא אהבה ויראה (בפ\"א קו הימין וקו השמאל, וזהו מ\"ש ובמורא גדול זו גילוי שכינה<sup data-n=\"4706\">25</sup> הוא מל' דא\"ס שהוא בחי' יראה שיתגלה לע\"ל, והגם דבמצרים הי' ג\"כ גילוי ובמורא גדול, היינו מפני שהי' הכנה למ\"ת שהוא [מ\"ע ומל\"ת] לכן לפי שעה האיר אז בחי' ובמורא גדול אבל עיקר הגילוי יהי' לע\"ל דוקא) ויראה הוא מד' היותר גבוה מאהבה ולכן במעט התבוננות שיתבונן האדם איך מה גדלו מעשיך<sup data-n=\"4707\">26</sup> ומה רבו מעשיך<sup data-n=\"4708\">27</sup> יבוא לאהבה ותשוקה לאלקות אבל ליראה לא יבוא במעט התבוננות רק בריבוי התבוננות ובהעמקת הדעת באלקות ועי\"ז יבוא ליראה שצריכים ריבוי יגיעה ע\"ז והוא דשרש האהבה מה\"א עילאה והוא השגה והבנה לכן ע\"י מעט התבוננות יבוא לזה אבל יראה הוא מיו\"ד<sup data-n=\"4709\">28</sup> דשם הוי' לכן צריכים לזה העמקת הדעת.\n<b>והנה</b> ידוע דהרים וגבעות הם אבות<sup data-n=\"4710\">29</sup> ואמהות<sup data-n=\"4711\">30</sup>, הרים אבות וגבעות אמהות, וצ\"ל והלא האבות הם למעלה במדרי' מהאמהות שהם משפיעים ולמה מדלג על ההרים ומקפץ על הגבעות. והענין דהנה יש מעלה באמהות שהם משפיעים, דהנה כתי' כל אשר תאמר אליך שרה שמע בקולה<sup data-n=\"4712\">31</sup> הרי הי' ציווי על אברהם שכל מה שיאמר לו שרה צריך לקבל ממנה ואמרז\"ל אברהם הי' טפל לשרה בנביאות<sup data-n=\"4713\">32</sup>, וצ\"ל והלא אחד הי' אברהם<sup data-n=\"4714\">33</sup> וכתי' מי האיר ממזרח<sup data-n=\"4715\">34</sup> קאי על אברהם, והי' מרכבה",[["4701","20","<b>בפ\"א</b>: ראה גם לעיל בהנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4702","21","<b>רב המשפיע שכל. . חלק עשירי</b>: ראה גם לעיל (בחלק המאמרים) בהמשך מצה זו ספ\"ה ובהערה 198. לעיל הנחה ד\"ה ויהי הענן והחשך על יד הערה 61. לקמן הנחה ד\"ה וביום הביכורים על יד הערה 26."],["4703","22","<b>ועמדו רגליו</b>: זכרי' יד, ד."],["4704","23","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["4705","24","<b>ויראו את אלקי ישראל</b>: משפטים כד, י."],["4706","25","<b>ובמורא גדול זו גילוי שכינה</b>: תבוא כו, ח ובספרי שם. הגדה של פסח."],["4707","26","<b>מה גדלו מעשיך</b>: תהלים צב, ו. ראה בהערה הבאה."],["4708","27","<b>ומה רבו מעשיך</b>: תהלים קד, כד. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול על יד הערה 36 ואילך ובהנסמן שם."],["4709","28","<b>האהבה מה\"א. . יראה הוא מיו\"ד</b>: ראה זהר רע\"מ נשא קכג, סע\"א. תו\"א מקץ מ, ד ואילך. מא, סע\"ג. ש\"א מ, א ואילך."],["4710","29","<b>דהרים. . אבות</b>: ראה ר\"ה יא, א. תו\"ח וארא ח\"א עז, ג. וש\"נ."],["4711","30","<b>וגבעות. . ואמהות</b>: ראה ר\"ה שם. מכילתא בשלח יז, ט."],["4712","31","<b>כל אשר תאמר.. בקולה</b>: וירא כא, יב."],["4713","32","<b>אברהם הי' טפל לשרה בנביאות</b>: תנחומא ושמו\"ר ר\"פ שמות. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 917."],["4714","33","<b>אחד הי' אברהם</b>: יחזקאל לג, כד."],["4715","34","<b>מי האיר ממזרח</b>: ישעי' מא, ב [ושם: העיר — ראה ב\"ר פ\"ב, ג: א\"ת העיר אלא האיר]."]]],[2000470495,"למדת החסד<sup data-n=\"4716\">35</sup> דכמו שלמטה הי' נדיב בגופו בנפשו ובממונו<sup data-n=\"4717\">36</sup> שהי' מאכיל ומשקה לכולם כמו\"כ למעלה הי' מרכבה למדת החסד ואיך אפ\"ל שהי' טפל כו' (ובפ\"א וכן רבקה כתי' והנערה טובת מראה מאד<sup data-n=\"4718\">37</sup> ונת\"ל דמאד הוא בחי' בלי גבול<sup data-n=\"4719\">38</sup>, וזהו שכ' ותאמר שתה<sup data-n=\"4720\">39</sup> וגם לגמליך אשאב<sup data-n=\"4721\">40</sup> שהיתה בחי' משפיע, וזהו ותרד העיינה<sup data-n=\"4722\">41</sup> כו' ותרד כדה<sup data-n=\"4723\">42</sup> כו' כדה הם ך\"ד ספרי אורייתא<sup data-n=\"4724\">43</sup> הוא ירידה והשפלה לגבה). אך הענין הוא דהנה אמרז\"ל ג' הטעימן הקב\"ה<sup data-n=\"4725\">44</sup> מעין עוה\"ב אברהם יצחק ויעקב שנא' בהם בכל מכל כל<sup data-n=\"4726\">45</sup> וע\"ד לע\"ל כתי' נקבה תסובב גבר וכמ\"ש א\"ח עט\"ב<sup data-n=\"4727\">46</sup>, וזהו נעוץ תחילתן בסופן<sup data-n=\"4728\">47</sup> שנעיצת התחילה הוא בסוף<sup data-n=\"4729\">48</sup> יותר מבראש המתפשט, תחילה הוא למעלה מראשית והוא דוקא בסוף יותר מבראש המתפשט, ולא שנא' שהאבות אינם משפיעים כלל, דהנה ידוע שיש מלמעלמ\"ט ומלמטלמ\"ע, דמלמעלמ\"ט המשפיע למעלה מהמקבל אבל מלמטלמ\"ע המקבל נעשה משפיע (וזהו ביום ההוא יצאו מ\"ח<sup data-n=\"4730\">49</sup> מירושלים חצים אל הים הקדמוני הוא ים החכ'<sup data-n=\"4731\">50</sup> ) ואז המקבל למעלה מהמשפיע, והגם שהאבות הם ודאי משפיעים אך זה אינו דבר חדש דכל מלמעלמ\"ט המשפיע למעלה מהמקבל, אבל זהו דבר חדש שהמקבל יהי' למעלה מהמשפיע והיינו מלמטלמ\"ע, ולכן כתי' מדלג על ההרים מקפץ על הגבעות. והנה ב' בחי' אלו הם תומ\"צ, ולכן לפעמים מצינו מעלה בתורה וכמשארז\"ל גדול תלמוד<sup data-n=\"4732\">51</sup> שמביא לידי מעשה, שהתורה מפרש ומבאר איך לעשות המצוה ולולי זאת לא היו יודעים כלל איך לעשות המצוה והתורה מפרש ומבאר שאם יעשה באופן זה ה\"ז מצוה וא\"ל אין זה מצוה כלל הרי התורה עושה אותה למצוה, ופעמים נת' שהמצוה למעלה מהתורה שהרי גדול תלמוד שמביא לידי מעש\"ה<sup data-n=\"4733\">52</sup> הרי מעשה גדול, ותרי\"ג מצות דאורייתא וז' מצות דרבנן הם תר\"ך<sup data-n=\"4734\">53</sup> בגימ' כתר<sup data-n=\"4735\">54</sup>, ותורה",[["4716","35","<b>אברהם. . מרכבה למדת החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם."],["4717","36","<b>אברהם. . נדיב בגופו בנפשו ובממונו</b>: ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 12."],["4718","37","<b>והנערה טובת מראה מאד</b>: ח\"ש כד, טז."],["4719","38","<b>ונת\"ל דמאד הוא בחי' בלי גבול</b>: הנחה ד\"ה גן נעול הב' ובהערה 35."],["4720","39","<b>ותאמר שתה</b>: ח\"ש שם, יח."],["4721","40","<b>וגם לגמלך אשאב</b>: ח\"ש כד, יט [ושם: ותאמר גם]."],["4722","41","<b>ותרד העיינה</b>: ח\"ש שם טז."],["4723","42","<b>ותרד כדה</b>: ח\"ש שם, יח."],["4724","43","<b>כדה הם ך\"ד ספרי אורייתא</b>: ראה ת\"ז תכ\"א (מו, ב). תו\"א תולדות יז, ד. תו\"ח וארא פ, א. וש\"נ."],["4725","44","<b>ג' הטעימן הקב\"ה</b>: ב\"ב טז, סע\"ב ואילך."],["4726","45","<b>בכל מכל כל</b>: ח\"ש כד, א. תולדות כז, לג. וישלח לג, יא."],["4727","46","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["4728","47","<b>נעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["4729","48","<b>שנעיצת התחילה הוא בסוף</b>: ראה סה\"מ תר\"ל ע' שכ. ראה גם סה\"מ תרל\"ח ע' רלב ובהערה 56."],["4730","49","<b>ביום ההוא יצאו מ\"ח</b>: זכרי' יד, ח."],["4731","50","<b>הים הקדמוני. . החכ'</b>: ראה גם סה\"מ תרל\"ח ע' תמ ובהערה 78."],["4732","51","<b>גדול תלמוד</b>: ראה קדושין מ, ב. ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע על יד הערה 20."],["4733","52","<b>גדול תלמוד. . מעש\"ה</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' שצג. וש\"נ. ש\"א נד, א."],["4734","53","<b>ותרי\"ג. . וז'. . תר\"ך</b>: ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת עמך ברית הערה 44 ואילך."],["4735","54","<b>תר\"ך בגימ' כתר</b>: ראה ע\"ח שער ז\"א שי\"ז, ספ\"א. מאמרי אדה\"א דברים ח\"ד ע' א'רצט. וש\"נ."]]],[2000470496,"אורייתא מחכ' נפקת<sup data-n=\"4736\">55</sup>, דתרי\"ג מצות דאורייתא הם תרי\"ג ארחין דגולגלתא<sup data-n=\"4737\">56</sup> שהוא בחי' כתר עטרה ע\"ג הראש, הנה תומ\"צ הם הרים וגבעות, תורה נק' הרים וכמ\"ש ישאו הרים שלום וכתי' או יחזיק במעוזי<sup data-n=\"4738\">58</sup> יעשה שלום לי, שלום יעשה לי, כל העוסק בתורה משים שלום<sup data-n=\"4739\">59</sup> בפמליא שלמעלה ושלום בפמליא של מטה, ומצות נק' גבעות וכמ\"ש וגבעות בצדקה<sup data-n=\"4740\">57</sup>, וכללות כל המצות נק' בשם צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"4741\">60</sup> כי נשמור לעשות כל המצוה הזאת, ובד\"כ הם אהוי\"ר, וזהו בינה יתירה ניתנה באשה כו' דאהבה למעלה מיראה וכמו שם ב\"ן יהי' למעלה מש' מ\"ה<sup data-n=\"4742\">61</sup>, וזהו בזאת יבוא אהרן אל הקדש ע\"י יראה יבא לבחי' קדש העליון.\n<b>והנה</b> קדש הוא קדש מילי' בגרמי'<sup data-n=\"4743\">62</sup>, וזהו והחכ' מאין תמצא שהחכ' ג\"כ אין<sup data-n=\"4744\">63</sup>, וזהו מה פשפשת<sup data-n=\"4745\">64</sup> שלמעלה מהשגה, דהנה יש קדש וקדוש בוא\"ו<sup data-n=\"4746\">65</sup>, קדש הוא קדש מילי' בגרמי' וקדוש הוא מה שנמשך מחכ' בבינה שבא לידי השגה, וזהו חכמ\"ה כח מ\"ה<sup data-n=\"4747\">66</sup>, כח הוא התפשטותו אל הבינה ומה הביטל אל הכתר וזהו מה פשפשת, והנה אי' בזהר אימתי זיווגא<sup data-n=\"4748\">67</sup> דכנס\"י במלכא קדישא בזימנין דנטלא מבי אבא וכדין קדש קרינן לה דהא מבוא אבא נטלא שמה דא<sup data-n=\"4749\">68</sup>. והענין דהנה יחודים עליונים התחילו מזמן מ\"ת, ויש דעות בקבלה שההתחלה הי' מזמן האבות<sup data-n=\"4750\">69</sup>, והיינו דהאבות עשו הכנה למ\"ת<sup data-n=\"4751\">70</sup>. וענין יחוד העליון הוא להמשיך אוא\"ס שלמעלה מסדר",[["4736","55","<b>אורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4737","56","<b>דתרי\"ג מצות. . ארחין דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א. אגה\"ק ס\"כ. לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"א ובהערה 219."],["4738","58","<b>או יחזיק במעוזי</b>: ישעי כז, ה."],["4739","59","<b>כל העוסק בתורה משים שלום</b>: נסמן לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 939."],["4740","57","<b>ישאו הרים שלום. . וגבעות בצדקה</b>: תהלים עב, ג."],["4741","60","<b>כל המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה [בדילוג]. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 65."],["4742","61","<b>שם ב\"ן. . מש' מ\"ה</b>: ראה ע\"ח שער פנימיות וחצוניות ש\"מ, ד\"ד. לקו\"ת בחוקותי מז, ג ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' קעט ואילך. מאמרי אדה\"א דברים ח\"ב ע' תקעג ואילך."],["4743","62","<b>קדש מילי' בגרמי'</b>: זהר אמור צד, ב."],["4744","63","<b>והחכ' מאין תמצא. . אין</b>: איוב כח, יב. ראה לעיל (בחלק המאמרים) המשך מצה זו פכ\"ב ובהערה 682. ראה גם לקמן שם ספ\"ל. הנחה ד\"ה וביום הביכורים על יד הערה 12. ספר המאמרים תרל\"ח ע' רכז. וש\"נ."],["4745","64","<b>מה פשפשת</b>: זהר בהקדמה א, ב."],["4746","65","<b>קדש וקדוש בוא\"ו</b>: ראה ביאוה\"ז אמור פ, ג. ראה גם לעיל בהנחה ד\"ה הנה אנכי כורת ברית הערה 30."],["4747","66","<b>חכמה כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א. ראה גם לעיל הנחה ד\"ה כי הנה יוצר הרים ובהערה 39."],["4748","67","<b>אי' בזהר אימתי זיווגא</b>: אמור ק, ב [בשינוי לשון — ראה לקמן הנחה ד\"ה וביום הביכורים ובהערות 38-39]."],["4749","68","<b>מבוא. . שמה</b>: לעיל (בחלק המאמרים) המשך מצה זו כאן פכ\"ט: מבי. . שמא."],["4750","69","<b>יחודים עליונים. . מזמן מ\"ת. . מזמן האבות</b>: ראה לקו\"ת להאריז\"ל ר\"פ לך. אוה\"ת ח\"ש ע' קכו ואילך. בהעלותך ע' שלז ואילך. פינחס ע' א'קנב. סה\"מ תר\"ל ע' קא. תרל\"ב ח\"ב ע' שנה. תער\"ב ח\"א ר\"ע רכב. ס\"ע שט ואילך."],["4751","70","<b>דהאבות עשו הכנה למ\"ת</b>: ראה תו\"א לך יא, ג (הועתק גם לעיל בחלק המאמרים בהמשך מצה זו פכ\"ד). אוה\"ת לך כרך ד ע' תרצב."]]],[2000470497,"השתל' שיומשך תוך נקודת הלב וכמ\"ש לבי ובשרי ירננו לאל חי<sup data-n=\"4752\">71</sup> שגם לב ובשר הגשמי יהי' אהבה ותשוקה לאלקות, שזהו\"ע הק\"ש שהו\"ע יחודים עליונים לכן אומרים בק\"ש שמע ישראל ה' אלקינו ה' אחד<sup data-n=\"4753\">72</sup>, שמע הוא ל' השגה והבנה<sup data-n=\"4754\">73</sup> ושיהי' נתפס אצלו דה' אחד, חו\"ד הם ז' רקיעים וארץ וד' רוחות העולם<sup data-n=\"4755\">74</sup> ושיהי' בטלים לאל\"ף הוא א\"ס אלופו ש\"ע<sup data-n=\"4756\">75</sup>, דבשכמל\"ו<sup data-n=\"4757\">76</sup>, לעולם ועד היינו כללות השתל' הוא רק משם והארה בעלמא שאינו נוגע לעצמיות וכמו שם האדם שאינו נוגע לעצמות האדם, וכן כבוד הוא לבר מעצמותו ה\"ה רק הארה בעלמא, ומל' הוא רק מלך שמו נקרא עליהם<sup data-n=\"4758\">77</sup> הרי הארה והארה דהארה והארה דהארה דהארה, ומזה נעשה לעולם ועד הוא כללות השתל' וגם נו\"ן אלפים יובלות<sup data-n=\"4759\">78</sup> בכלל, ולכן אני ה' לא שניתי<sup data-n=\"4760\">79</sup> שלא יש שום שינוי בין קודם הבריאה לאחר הבריאה אתה הוא קודם שנבה\"ע<sup data-n=\"4761\">80</sup> ואתה הוא לאחר שנברה\"ע דכללות השתל' העולמות הוא רק משם והארה בעלמא שאינו נוגע לעצמיות, ועי\"ז ואהבת שרש דאהבה אבה<sup data-n=\"4762\">82</sup> ל' רצון שיהי' לו רצון ותשוקה לאלקות, את ה' אלקיך<sup data-n=\"4763\">81</sup> דה' דכתי' עליו לא שניתי יהי' בבחי' אלקיך אלוה שלך<sup data-n=\"4764\">83</sup>, וזה מצינו רק בשם אלקים שנא' בו אלקינו אלקיך משא\"כ בשאר שמות, וזהו שהוי' יהי' בבחי' אלקיך, עד שיהי' בכל לבבך, ב' לבבות<sup data-n=\"4765\">84</sup> שגם היצה\"ר יהי' לו אהבה לאלקות וזהו לאכפיא לסט\"א, וזהו ענין ירידת הנשמה בגוף אינו בשביל עצמו<sup data-n=\"4766\">85</sup> דהנשמה היא חלק אלוה ממעל<sup data-n=\"4767\">86</sup> וכל עיקר ירידתה בגוף ונה\"ב המעלים ומחשיך ומסתיר הוא לבקוע החשך ושגם היצה\"ר יהי' לו אהבה לאלקות וכמ\"ש לבי ובשרי ירננו אל אל חי שגם לב ובשר הגשמי יהי' לו אהבה ותשוקה לאלקות, וכ\"ז ע\"י",[["4752","71","<b>לבי ובשרי ירננו לאל חי</b>: תהלים פד, ג [ושם: אל-אל. וכ\"ה בסמוך בפנים]."],["4753","72","<b>שמע. . אחד</b>: ואתחנן ו, ד."],["4754","73","<b>שמע. . השגה והבנה</b>: ראה זהר אד\"ר נשא קלח, ב. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 145. מאמרי אדה\"א ויקרא ח\"ב ע' תשלו. וש\"נ. הנחות תקע\"ז ע' קמח. וש\"נ."],["4755","74","<b>חו\"ד הם ז' רקיעים וארץ וד' רוחות העולם</b>: נסמן לעיל (בחלק המאמרים) מאמר ד\"ה סמוכים לעד הערה 50."],["4756","75","<b>אלופו ש\"ע</b>: לשון ב\"ר פ\"כ, ב."],["4757","76","<b>דבשכמל\"ו</b>: פסחים נו, א (נוסח ק\"ש). ראה גם המשך וככה תרל\"ז פכ\"ו ס\"ע לב ואילך. וראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 157 (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא' על יד הערה 71."],["4758","77","<b>מלך שמו נקרא עליהם</b>: ראה פיוט אדון עולם. לעיל הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 16."],["4759","78","<b>נו\"ן אלפים יובלות</b>: ראה ש\"ך ר\"פ בהר. לעיל הנחה ד\"ה בן פורת יוסף הא' ובהערה 20."],["4760","79","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["4761","80","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["4762","82","<b>שרש דאהבה אבה</b>: ראה ס' שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב (צב, רע\"א). לעיל הנחה ד\"ה סמכוני ובהערה 10."],["4763","81","<b>ואהבת. . את ה' אלקיך</b>: ואתחנן ו, ה."],["4764","83","<b>דה'. . אלקיך אלוה שלך</b>: ראה גם תו\"א תצוה פב, רע\"ג. לעיל בהנחה שם ובהערה 11."],["4765","84","<b>בכל לבבך ב' לבבות</b>: נסמן לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 18."],["4766","85","<b>ירידת הנשמה. . אינו בשביל עצמו</b>: ראה תניא פל\"ז (מח, ב). ש\"א ט, א הערה 4."],["4767","86","<b>דהנשמה היא חלק אלוה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. לעיל הנחה ד\"ה ואתה תצוה ובהערה 54."]]],[2000470498,"שממשיכים קדש העליון למטה, וזהו יחוד קוב\"ה ושכינתי'<sup data-n=\"4768\">87</sup> קוב\"ה הוא מה שא\"ס קדוש ומובדל ואני ה' לא שניתי, ושכינתי' הוא מ\"ש בשכמל\"ו, יחוד קוב\"ה ושכינתי' הוא שמה שקדוש ומובדל יומשך למטה, ובד\"כ שכינתי' הוא המשכת הקו והוא רק הארה מפני שהוא מצומצם, וקוב\"ה הוא האוא\"ס שלפני הצמצום, והעגול שלפני הקו יומשך בהקו.\n<b>והנה</b> קדש הוא מילי' בגרמי' וזהו והחכ' מאין תמצא, וזהו ההפרש בין מוחין למדות, דמדות הם שייכים לעולם<sup data-n=\"4769\">88</sup> דוקא כמו עד\"מ מי שהוא חסדן או רחמן שייך דוקא כשיש על מי להתחסד או על מי להתרחם, הגם שיש התעוררות שהאדם מעורר ע\"ע זה לפני הקב\"ה אבל אינו שייך שיעורר לפני עצמו, הגם שמה שנמשך החסד הוא רק השפעת החסד אבל לא עצם המדה, אך אם לו<sup data-n=\"4770\">*89</sup> ההשפעה לא היו יודעין המדה כלל כמו וותרן הוא שנותן וקמצן אינו נותן, וכשוותרן אינו נותן אינו יודעין שהוא וותרן, וכן מדיבור יודעין דוותרן אומר שצריכין ליתן ומי שהוא קמצן אומר שא\"צ ליתן, אבל לולי זאת אינו יודעין המדה כלל, אבל מוחין יוכל לישב לעצמו ולהשכיל השכלות וכמו גדולי הראשונים הי' מתבודדים ביערות<sup data-n=\"4771\">89</sup> כדי שלא יבלבלם שום דבר ויהי'<sup data-n=\"4772\">90</sup> תמיד מקושר לאלקות מצד ההתבוננות בגדולת הא\"ס, וכן השבטים היו רועה צאן<sup data-n=\"4773\">91</sup> כדי שלא יבלבלם שום דבר, והרשב\"י שישב במערה זמן רב נתוסף אצלו חכ' דתחילה כשהי' מותיב רשב\"י הי' רפב\"י אומר י\"ב פרוקי ואח\"כ כשהי' מותיב רפב\"י הי' רשב\"י מותיב<sup data-n=\"4774\">93</sup> כ\"ד פרוקי הרי שנתוסף לו ריבוי חכ' והי' בפ\"ע הגם שהי' עם ר\"א בנו<sup data-n=\"4775\">92</sup> אין זה השפעה, וכן סנהדרין היו נושאין ונותנין ואי' פלוגתא רש\"י והרמב\"ם<sup data-n=\"4776\">94</sup> כ\"א לעצמו או בן זוגו הכל אינו השפעה, הגם שאמרז\"ל ומתלמידיי יותר מכולם<sup data-n=\"4777\">95</sup> היינו להוציא מהעלם אל הגילוי",[["4768","87","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם לעיל הנחה ד\"ה הנה אנכי כורת ברית על יד הערה 26. תו\"ח וארא ח\"א נא, ג."],["4769","88","<b>דמדות. . לעולם</b>: ראה גם אוצרות חיים בתחלתו. הובא בלקו\"ת מסעי צג, רע\"א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי הערה 261. תרל\"ח ס\"ע שצ. וש\"נ."],["4770","*89","<b>לו</b>: אוצ\"ל: לא."],["4771","89","<b>גדולי הראשונים הי' מתבודדים ביערות</b>: ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ ובהערה 25."],["4772","90","<b>ויהי'</b>: אולי כתוב: והיו."],["4773","91","<b>השבטים היו רועה צאן</b>: וישב לז, ב. ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' קצב. תקע\"א ע' פח. סה\"מ תרכ\"ט ע' קעב. וש\"נ. ע' רפא. וש\"נ."],["4774","93","<b>מותיב</b>: אוצ\"ל: אומר."],["4775","92","<b>והרשב\"י. . עם ר\"א בנו</b>: ראה שבת לג, ב. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 30. סה\"מ תרל\"ח ע' יד וע' תקיח. וש\"נ. עטר\"ת ע' תז. ש\"ת ע' 82. מאמר ד\"ה בכ\"ה בכסלו יומי דחנוכה ש\"מ טבת תשח\"י."],["4776","94","<b>סנהדרין. . רש\"י והרמב\"ם</b>: רש\"י סנהדרין מ, א ד\"ה כל הלילה: איש איש לעצמו. רמב\"ם הל' סנהדרין פי\"ב ה\"ג: כל אחד ואחד עם זוג שלו או עם עצמו בביתו. ראה גם סה\"מ תרל\"ח ע' יד. וש\"נ."],["4777","95","<b>ומתלמידיי יותר מכולם</b>: תענית ז, א. ראה גם לעיל הנחה ד\"ה גל נעול על יד הערה 27 (ובחלק המאמרים המשך מצה זו ובהערה 538). לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 28. (ובחלק ההנחות) בהנחה שם על יד הערה 24."]]],[2000470499,"מה שיש במשכיל לכה\"פ אבל לא דבר חדש, וכמו\"כ למעלה מדות הם שייך לזולת וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"4778\">96</sup>, זכור רחמיך וחסדיך כי מעולם המה<sup data-n=\"4779\">97</sup>, רחמים וחסדים הם שייכים לעולם דוקא, וזהו שכ' בע\"ח כשעלה ברצונו הפשוט<sup data-n=\"4780\">98</sup> לברוא העולמות מצד טבע הטוב<sup data-n=\"4781\">99</sup> להטיב<sup data-n=\"4782\">100</sup> נאצל אצי' ונברא בריאה ונוצר יצי' ונעשה עשי', שבלא אבי\"ע אינו שייך ענין המדות, אבל מוחין הוא מדרי' שלמעלה מהעולם וזהו והחכ' מאין תמצא שהחכ' ג\"כ אין, וצ\"ל מאין יודעין מפסוק זה שהחכ' ג\"כ אין, אך ל' תמצא הוא שבדרך מציאה הוא כמו ראובן מצא מה שאבד שמעון צ\"ל שהוא אותו דבר כמו שהוא דאל\"כ אינו מציאה וזהו ואלו חייב להכריז<sup data-n=\"4783\">101</sup> שאומר סמנים<sup data-n=\"4784\">102</sup> והוא להורות שהוא אותו דבר שאבד רק כשהי' ברשות שמעון הי' בהעלם ועתה יצא מהעלם אל הגילוי, כמו\"כ למעלה החכ' נמצא מכתר וכמו שהכתר הוא אין<sup data-n=\"4785\">103</sup> כמו\"כ החכ' ג\"כ אין, רק שבמשל אח\"כ כשיוצא מרשות שמעון הוא מושג עצם הדבר אבל בנמשל עצם הדבר אינו מושג אח\"כ ג\"כ שהוא אין, וזהו בחי' קדש מילי' בגרמי'.\n<b>והנה</b> כתי' בזאת יבא אהרן אל הקדש כדי שיבא לבחי' קדש העליון הוא ע\"י יראה, ולכן קודם מ\"ת כתי' וירא העם וינועו, דתורה אמרז\"ל אלפים שנה קדמה תורה לעולם שקדמה למעלת ומדרי' העולם והוא בחי' חכ' קדש מילי' בגרמי', וכדי שיהי' מ\"ת כתי' תחילה ויחרד כל העם<sup data-n=\"4786\">104</sup> אשר במחנה, שהו\"ע מטיל חרדה, והיראה הי' כ\"כ עד שהזיעו, והזיעה הוא מצד שמתרכך הבשר ונפתחים נקבי הזיעה ויוצא הפנימיות (ע' בסד\"ה וביום ) וכמו\"כ במ\"ת עד שבאו לבחי' לבי ובשרי ירננו אל אל חי שגם לב ובשר הגשמי יש לו אהבה לאלקות אז הי' מ\"ת שהוא גילוי בחי' קדש כו'.",[["4778","96","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א ובהערה 22."],["4779","97","<b>זכור רחמיך. . המה</b>: תהלים כה, ו [בדילוג השם]. ראה גם המשך וככה תרל\"ז פכ\"ח. לקמן ח\"ב שם הנחה ד\"ה לכל תכלה ראיתי קץ ובהערה 22."],["4780","98","<b>שכ' בע\"ח כשעלה ברצונו הפשוט</b>: ראה דרוש עגו\"י ש\"א, ענף ב."],["4781","99","<b>בע\"ח. . טבע הטוב להטיב</b>: נסמן לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 977."],["4782","100","<b>טבע הטוב להטיב</b>: ראה שער היחוה\"א פ\"ד. לעיל (בחלק המאמרים) מאמר ד\"ה להבין ענין ר\"ח ובהערה 44."],["4783","101","<b>ואלו חייב להכריז</b>: ב\"מ רפ\"ב."],["4784","102","<b>שאומר סמנים</b>: ראה שם כז, א ואילך."],["4785","103","<b>שהכתר הוא אין</b>: ראה זהר שלח קנח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תנח. וש\"נ. הנחות תקע\"ז ע' ב. וש\"נ."],["4786","104","<b>ויחרד כל העם</b>: יתרו יט, טז."]]],[2000470500,"<h3>וביום הביכורים</h3>\n<b></b><b>יום א' דחה\"ש אחר התפלה תר\"ם לפ\"ק</b>\nיום א' דחה\"ש אחר התפלה\n<b>וביום</b> הביכורים<sup data-n=\"4787\">1</sup> בהקריבכם מנחה חדשה לה' בשבועותיכם מקרא קדש יהי' לכם כל מלאכת עבודה לא תעשו<sup data-n=\"4788\">2</sup>, הנה מנחה חדשה הוא שתי הלחם שהי' בשבועות, ועליהם נא' סלת תהיינה חמץ תאפינה<sup data-n=\"4789\">3</sup> וארז\"ל כל המנחות באות מצה<sup data-n=\"4790\">4</sup> חוץ מחמץ שבתודה ושתי הלחם, וצ\"ל למה כל המנחות אסור להקריב חמץ וכמ\"ש כי כל שאור<sup data-n=\"4791\">5</sup> וכל דבש כו' הגם שהי' נאכל לכהנים<sup data-n=\"4792\">6</sup> אך באמת אין זה לגריעותא שתי הלחם צריכים להיות דוקא חמץ. והנה צ\"ל תחילה ההפרש בין שבת ליו\"ט<sup data-n=\"4793\">7</sup>, שבת הוא קדש וכמ\"ש ושמרתם את השבת<sup data-n=\"4794\">8</sup> כי קדש היא ויו\"ט נק' מקראי קדש וכמ\"ש אלה מועדי ה'<sup data-n=\"4795\">9</sup> מקראי קדש, דהנה קדש הוא קדש מילי' בגרמי'<sup data-n=\"4796\">10</sup> וכמ\"ש והחכ' מאין תמצא<sup data-n=\"4797\">11</sup> שהחכ' ג\"כ אין דזהו תמצא ל' מציאה<sup data-n=\"4798\">12</sup>, ועז\"נ אלפים שנה קדמה תורה לעולם<sup data-n=\"4799\">13</sup> שקדמה למעלת ומדרי' העולם, דאלפים אין ר\"ל בזמן אלא אלפך חכ' ואלפך בינה<sup data-n=\"4800\">14</sup> והוא בחי' קדש כו' ונק' אין, ומקרא קדש הוא הארת החכ' בבינה ואי' בע\"ח שהארה זו הוא בדרך חלון<sup data-n=\"4801\">15</sup>, דהנה בכל ספי' יש פרצוף והיינו הע\"ס הכלולים בה, והיסוד של כל ספי' הוא נק' חלון ופעמים נק' יו\"ד שהוא נקודה חדא, ומ\"ש חלון הוא כוונה א', להורות על הצמצום, כמו עד\"מ כשאין דופן לבית הרי השמש זורח בכל הבית והדופן מעלים ומסתיר וע\"י החלון מאיר הארה מצומצמת וכמו\"כ למעלה הארת יסו\"א שמאיר בבינה הוא הארה מצומצמת, וגם זאת משתנה בבינה שה\"ה קדוש בוא\"ו ומה שנתוסף אינו מעלה שהרי אינו קדש<sup data-n=\"4802\">16</sup> וגם ציור הוא\"ו הוא י' ברישא<sup data-n=\"4803\">17</sup> וכשנמשך ממנו קו ה\"ז ו' הרי נתוסף בו וגם זה אינו מעלה שהרי נשתנה, וגם היו\"ד כולל מספר היותר גדול מו', דיו\"ד כולל עשרה ווא\"ו כולל ששה, נמצא שהארת החכ' המאיר בבינה הוא רק הארה מצומצמת וג\"ז נשתנה בבינה.",[["4787","1","<b>וביום הביכורים</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פל\"א-פרק ג\"ל. וש\"נ.\nהנחה אחרת מדרוש זה נדפסה לקמן בחלק ההנחות."],["4788","2","<b>וביום הביכורים. . לא תעשו</b>: פינחס כח, כו. ראה מנחות פד, ב."],["4789","3","<b>סולת תהיינה חמץ תאפינה</b>: אמור כג, יז."],["4790","4","<b>כל המנחות באות מצה</b>: מנחות נב, ב (במשנה)."],["4791","5","<b>כי כל שאור</b>: ויקרא ב, יא."],["4792","6","<b>הגם שהי' נאכל לכהנים</b>: מנחות עד, ב במשנה."],["4793","7","<b>ההפרש בין שבת ליו\"ט</b>: ראה פע\"ח שער מקראי קדש ש\"כ, פ\"א. (לעיל בחלק המאמרים) המשך מצה זו כאן ובהערה 994."],["4794","8","<b>ושמרתם את השבת</b>: תשא לא, יד."],["4795","9","<b>אלה מועדי ה'</b>: אמור כג, ד."],["4796","10","<b>קדש מילי' בגרמי'</b>: זהר אמור צד, ב."],["4797","11","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה לעיל הנחה ד\"ה וירא העם וינועו ובהערה 63."],["4798","12","<b>תמצא לשון מציאה</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו פ\"ל ובהערה 981."],["4799","13","<b>אלפים שנה קדמה תורה לעולם</b>: ראה לעיל הנחה ד\"ה וירא העם וינועו ובהערות 5-6."],["4800","14","<b>אלפך חכ' ואלפך בינה</b>: כנצ\"ל: ואאלפך — איוב לג, ג. שבת קד, א."],["4801","15","<b>ואי' בע\"ח. . חלון</b>: ראה שער הכללים פ\"א. ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן רפל\"א."],["4802","16","<b>קדוש בוא\"ו. . קדש</b>: ראה ביאוה\"ז אמור פ, ג. ראה גם לעיל הנחה ד\"ה הנה אנכי כורת ברית הערה 30."],["4803","17","<b>הוא\"ו הוא י' ברישא</b>: ראה תו\"א בראשית ג, ג. מאמרי אדה\"א דברים ח\"ב ע' תרעח. וש\"נ. תו\"ח בשלח ח\"א קנ, ג. וש\"נ."]]],[2000470501,"<b>והנה</b> כמשנ\"ת כאן ההפרש בין חכ' לבינה הוא לפי הדעה דהנה יש אבי\"ע ובאצי' גופא יש אבי\"ע הרי חכ' הוא אצי' שבאצי' בינה בריאה<sup data-n=\"4804\">18</sup> שבאצי' ז\"א יצי' שבאצי' ומל' עשי' שבאצי', וההפרש בין חו\"ב הוא כמו בין אצי' לעשי'<sup data-n=\"4805\">19</sup> דחכ' הוא קדש כו' והו\"ע והחכ' מאין תמצא ובינה הוא קדוש בוא\"ו וה\"ז כמו ההפרש בין אצי' לברי' דנברא לגבי אלקות אינו בערך, דאצי' הוא בחי' קדש ובינה הוא בחי' קדוש בוא\"ו וכ\"ה בלקו\"ת בשם פע\"ח דהמסך בין אצי' לבריאה כדי שיתהווה עולם הבריאה הוא מבינה<sup data-n=\"4806\">20</sup> שמלבשת אוא\"ס וחכ' הלבשה גמורה ומזה נעשה המסך כו', ומאחר שהוא מקור לבריאה מובן כמו שהוא באצי' הוא ג\"כ בריאה שבאצי', ולפ\"ז כתר דאצי' שהוא א\"א הוא למעלה מהשתל' אפי' מאצי' שבאצי' וכמו ד' יסודות שהם ארמ\"ע ויש כח היולי הכוללם ומקור עליהם ואינו אחד מכולם שאינו אש ולא רוח כו' ומ\"מ הוא מקור עליהם וכמו\"כ בחי' א\"א הוא למעלה גם מאצי' שבאצי'.\n<b>אך</b> יש דעה דא\"א הוא אצי' שבאצי'<sup data-n=\"4807\">21</sup> וחכ' בריאה שבאצי', וכ\"ה בלקו\"ת (בד\"ה את שבתותי תשמרו<sup data-n=\"4808\">22</sup> ) ע\"פ בורא קדושים שאפי' קדושים שהוא חכ' וכמ\"ש וקדושים בכ\"י יהללוך סלה<sup data-n=\"4809\">23</sup> (ע' שם בד\"ה הנ\"ל) הם רק בדרך בריאה יש מאין הארה בעלמא, וכן פי' הרמ\"ז<sup data-n=\"4810\">24</sup> ורוב מפרשי הזהר, אכן כפי מה שנת' כאן צ\"ל דהחכ' הוא אצי' שבאצי' כו' וכ\"ה בס' אשל אברהם<sup data-n=\"4811\">25</sup> פי' על הזהר, ולפ\"ז דהחכ' הוא אצי' שבאצי' ובינה בריאה שבאצי' ההמשכה מחכ' לבינה הוא עד\"מ רב המשפיע איזה שכל לתלמיד בדיבור אין עצם החכ' מתלבש בדיבור רק הארה מהחכ' וכמשנת\"ל ובמספר הוא חלק עשירי<sup data-n=\"4812\">26</sup> דבמספר שוה חכ' עם דיבור וכמו אם נניח זהב כסף ונחושת הזהב א' כמו הנחשת, ונחשת לגבי זהב אין לו דמיון כלל וכמו\"כ הדיבור אין לו דמיון וערך כלל לחכ', א\"כ א\"ז רק הארה מהחכ', והארה זו התלמיד אינו מקבלה כמו שהיא והראי' דאח\"כ מבין שכך כוונתו הרי מתחלה לא הבין כוונתו וגם ה\"ה משנה האותיות, הרי לבד מה דלא קאים איש אדעתי' דרבי'<sup data-n=\"4813\">27</sup> עד מ' שנין זהו אדעתי', אפי' ההארה המלובשת בדיבור אינו מובן כמו שהיא, וכמו\"כ יובן",[["4804","18","<b>אבי\"ע. . חכ'. . אצי' שבאצי' בינה בריאה</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1002."],["4805","19","<b>לעשי'</b>: אוצ\"ל: לבריאה."],["4806","20","<b>בלקו\"ת בשם פע\"ח דהמסך. . מבינה</b>: ראה שם שה\"ש לט, ג [ושם<sup data-n=\"e266\">א</sup>: בע\"ח — צויין לעיל בההמשך כאן בפנים על יד הערה 1007]."],["4807","21","<b>יש דעה דא\"א הוא אצי' שבאצי'</b>: ראה מאמרי אדה\"ז תקס\"ז ע' שיא."],["4808","22","<b>בלקו\"ת (בד\"ה את שבתותי תשמרו)</b>: בהר מא, ד."],["4809","23","<b>וקדושים בכ\"י יהללוך סלה</b>: נוסח ברכת אתה קדוש."],["4810","24","<b>וכן פי' הרמ\"ז</b>: בפ' ויצא בדף קנ ע\"א (ד\"ה חמא). ר\"פ קרח — קעו, ב."],["4811","25","<b>וכ\"ה בס' אשל אברהם</b>: ראה (לעיל בחלק המאמרים) בההמשך כאן הערות 1015 1014."],["4812","26","<b>וכמשנת\"ל. . חלק עשירי</b>: ראה לעיל הנחה ד\"ה ויהי הענן והחשך על יד הערה 61. ד\"ה וירא העם וינועו על יד הערה 21. (בחלק המאמרים) המשך מצה זו ספ\"ה ובהערה 198."],["4813","27","<b>דלא קאים איש אדעתי' דרבי'</b>: ראה ע\"ז ה, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תמד. וש\"נ. תו\"ח בשלח ח\"א ריז, ג הערה 418. המשך וככה תרל\"ז ספל\"ה.\n\n<b>א</b>  וכן הוא לקמן (בחלק ההנחות) בהנחה כאן."]]],[2000470502,"למעלה שהארת החכ' שמאיר בבינה הוא רק הארה מצומצמת וכמו נקודה לבד וג\"ז נשתנה בבינה.\n<b>והנה</b> אי' בזהר<sup data-n=\"4814\">28</sup> ע\"פ אודך ה' כי עשית פלא<sup data-n=\"4815\">29</sup> שיש ב' נקודות בחכ' א' נקודת החכ' שמאיר בבינה והב' נקודת החכ' עצמה כמו שהיא מקבלת מכתר ונקודה זו נק' נקודא עילאה סתימאה, ונקודה הא' נק' נקודה סתם, וכמו שביו\"ד יש ב' קוצים<sup data-n=\"4816\">30</sup> קוץ העליון וקוץ התחתון, קוץ התחתון היינו שמשם מאיר בבינה (והיינו החלון שנת\"ל), ונקודה הב' הוא כמו שעצם היו\"ד מקבל מכתר, וכן י\"ל בח\"ס שיש ג\"כ ב' נקודת<sup data-n=\"4817\">*31</sup> א' שמשפיע בחכ' דאצי' ב' כמו שמקבל מכתר שבכתר. והנה עצם החכ' הוא אין והו\"ע קדש מילי' בגרמי', ואפי' הארות החכ' שמאיר בבינה נק' ג\"כ אין שהרי נשתנה בבינה מעצם החכ' (ר\"ל עצם ההארה) הוא אין [דעצם הברק המבריק<sup data-n=\"4818\">31</sup> לעולם אינו בא לידי השגה והבנה] ועמ\"ש בד\"ה אימתי זיווגא דכנס\"י במ\"ק (של אאזמו\"ר<sup data-n=\"4819\">32</sup> זצללה\"ה) שמן ההארה שנמשך בבינה נמשך הארה לבד ובא לידי השגה והבנה וכמו המשל דלעיל שהתלמיד אינו מבין כל הנקודה בשלימות אך אפשר שיבין אותה בהמשך זמן אבל עצם כמו שמבין הרב לא יבין לעולם הרי אותה הארה שבה<sup data-n=\"4820\">33</sup> לידי גילוי אינו בא לידי השגה רק הארה ממנה, וזהו\"ע אור מים רקיע עי\"ש)<sup data-n=\"4821\">34</sup>, וזהו וא\"ו שנשתנה מיו\"ד רק ברישא יו\"ד שיש בו יו\"ד, דבינה הוא יש וכמ\"ש להנחיל אוהבי יש<sup data-n=\"4822\">35</sup> והחכ' אין וה\"ז כמו האין המהווה היש שעומד תמיד בהיש<sup data-n=\"4823\">36</sup> להחיותו ולהוותו מאין ליש ואם יסתלק כרגע נעשה אין ואפס, ומ\"מ כמו שעומד בהיש ה\"ה אין וכמו\"כ אפי' הארת החכ' שמאיר בבינה נק' אין ומה שבא לידי השגה והבנה הוא יש וזהו קדוש בוא\"ו.\n<b>וז\"ש</b> בזהר (ח\"ג ד\"ק<sup data-n=\"4824\">37</sup> ) אימתי זיווגא דכנס\"י במלכא קדישא בזמנין דנטלא מבי\"א<sup data-n=\"4825\">38</sup> וכדין קדש קרינן לה דהא מבי אבא נטלא שמה דא<sup data-n=\"4826\">39</sup>, דהנה שבת נק' קדש וכמ\"ש ושמרתם את השבת כי קדש היא, דהנה שבת הוא ל' שביתה כמו עד\"מ אדם",[["4814","28","<b>בזהר</b>: בלק קצג, ב."],["4815","29","<b>אודך ה' כי עשית פלא</b>: בזהר: ה'. . אודה שמך כי עשית וגו' — ישעי כה, א."],["4816","30","<b>שביו\"ד יש ב' קוצים</b>: ראה שו\"ע אדה\"ז הל' תפילין סל\"ו אות יו\"ד. ראה גם תו\"ח לך פב, ב ובהערה 11. שמות ח\"א לד, א. וש\"נ."],["4817","*31","<b>נקודת</b>: אוצ\"ל: נקודות."],["4818","31","<b>הברק המבריק</b>: ראה גם בענין ברק המבריק פלח הרמון אמור ע' של. לעיל הנחה ד\"ה כי הנה יוצר הרים ובהערה 21."],["4819","32","<b>בד\"ה אימתי. . של אאזמו\"ר</b>: מהסיום דבסמוך אור מים רקיע, משמע שזהו לשון כ\"ק אדמו\"ר מהורש\"ב — ראה ביאוה\"ז להצ\"צ אמור כרך א ע' תכא ואילך."],["4820","33","<b>שבה</b>: אוצ\"ל: שבאה? שבא?"],["4821","34","<b>עי\"ש)</b>: בגוכתי\"ק לא נסמן התחלת הסוגר."],["4822","35","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["4823","36","<b>האין. . שעומד תמיד בהיש</b>: ראה שער היחוד והאמונה פ\"א. פ\"ב."],["4824","37","<b>בזהר. . ד\"ק</b>: ע\"ב — השווה לעיל הנחה ד\"ה וירא העם וינועו על יד הערה 67. (בחלק המאמרים) המשך מצה זו פכ\"ט."],["4825","38","<b>קדישא בזמנין דנטלא מבי\"א</b>: שם: קדישא. . בזמנא. . מבי אבא נטלא האי (לקמן שם הובא זמנא דנטלא מבי אבא)."],["4826","39","<b>וכדין. . דא</b>: שם: וכדין מזדווגא כחדא בגין דמלכא קדש אקרי."]]],[2000470503,"שעוסק במלאכה כמו בכתיבה עד\"מ הרי מוחי' וכל כחות נפשו מלובשים בהעשי' היינו בההשכלה או במלאכתו, ואחר שגומר מלאכתו אז החזרות המוחין למקורן ונפשט מההלבשה, וכמו\"כ יובן למעלה דכתי' ששת ימים עשה<sup data-n=\"4827\">40</sup> היינו הבל העליון שמלובש בע\"מ ויש בו גם בחי' חכ' וכמארז\"ל בעשרה דברים ברא הקב\"ה<sup data-n=\"4828\">41</sup> את עולמו בחכ' ובתבונה ובדעת ובכח ובגערה כו' ושבת הוא שביתה הוא החזרות המוחין למקורן היינו לבחי' קדש מילי' בגרמי', ולכן אז זמן הולדת נשמות חדשות<sup data-n=\"4829\">42</sup>, דהנה כתי' אין כל חדש תחת השמש<sup data-n=\"4830\">43</sup> רק חידוש הישנות וכמ\"ש המחדש בטובו<sup data-n=\"4831\">44</sup> בכ\"י ובכ\"ע ובכל רגע מאין ליש, אך זהו חידוש הישנות לא התחדשות גמורה, אבל לעילא משימשה יש התחדשות.\n<b>וביאור</b> מה שמחלקים תחת השמש ולעילא משימשא, דהנה אי' בהרמ\"ז דאור הגנוז<sup data-n=\"4832\">45</sup> הוא פנימיות יסו\"א ועז\"נ ופני לא יראו<sup data-n=\"4833\">46</sup>, והארת יסודו מאיר בת\"ת דז\"א (וכמו\"כ בבינה וכמו עד\"מ רב המשפיע שכל לב' בנ\"א א' בעל שכל גדול והב' קטן ממנו, הבעל שכל גדול מקבל את השכל טוב יותר מהשני וכמו\"כ יובן בבינה ות\"ת שבשניהם מאיר הארת החכ' אך ה\"ז כמו הב' מקבלים)<sup data-n=\"4834\">47</sup> וזהו הנק' שמש ועז\"נ כולם בחכ' עשית<sup data-n=\"4835\">48</sup> שאפי' בעשי' יש ג\"כ חכ', וכ' שבכ\"מ שנז' בזהר ובמקובלים הקדמונים דשמש הוא ת\"ת דז\"א ר\"ל הארות יסו\"א שמאיר בת\"ת דז\"א, ולפ\"ז יש ג' מדרי' הארות יסו\"א שמאיר בבינה וזה נק' תחת השמש והוא רק חדוש הישנות, ב' עצם יסו\"א שנק' אין דאפי' הארת החכ' שמאיר בבינה ששניהם מוחין מ\"מ עצם החכ' (אפי' כמו שהיא בבינה) הוא אין (כנ\"ל) מכ\"ש כמו שהוא בחכ' ה\"ז אין והוא לעילא משמשא, ג' פנימיות יסו\"א שחשוב כפנימיות ע\"י שאינו מתגלה עכשיו רק לע\"ל.\n<b>והנה</b> הגם שנת\"ל דחכ' יש בכל המדרי' וכמ\"ש כולם בחכ' כו' מ\"מ הנה כתי' ה' בחכ' יסוד<sup data-n=\"4836\">49</sup> כונן שמים בתבונה, הרי השמים שרשו מתבונה היינו החכ' כמו שנתלבשה בבינה אבל ארץ שרשה מחכ' בעצם, והנה צ\"ל תחילה והלא שמים גבהה מעלתו על ארץ מפני מה שמים הוא מתבונה וארץ מחכ'. והענין דהנה",[["4827","40","<b>ששת ימים עשה</b>: יתרו כ, יא. תשא לא, יז."],["4828","41","<b>בעשרה דברים ברא הקב\"ה</b>: וכ\"ה לקמן ח\"ב (בחלק המאמרים) בהמשך יונתי על יד הערה 471 (ובשתי ההנחות שם). המשך מים רבים תרל\"ו פצ\"ו. (פקי\"ח). סה\"מ תרל\"ח ע' נא. ע' תפ. המשך תער\"ב ח\"א ע' צז. ועד\"ז בשער האמונה סט, א. מאמרי אדה\"א שמות ח\"א ע' ריג. סה\"מ תרכ\"ז ע' רמט. ראה חגיגה יב, א."],["4829","42","<b>ושבת. . נשמות חדשות</b>: ראה גם ביאוה\"ז תרומה כרך ב ע' תתיט ואילך ובהנסמן שם."],["4830","43","<b>אין. . השמש</b>: קהלת א, ט [ושם: ואין]. ראה גם מאמרי אדה\"א דברים ח\"א ע' רעו."],["4831","44","<b>המחדש בטובו</b>: ברכת יוצר. ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה מי כהוי' אלקינו ובהערה 41."],["4832","45","<b>בהרמ\"ז דאור הגנוז</b>: ר\"פ בהעלותך קמח, ב (ד\"ה והוא שמשא וכו')."],["4833","46","<b>ופני לא יראו</b>: תשא לג, כג."],["4834","47","<b>(וכמו\"כ. . מקבלים)</b>: בגוכתי\"ק נסמן עיגול קטן בהתחלת וסיום הסוגר."],["4835","48","<b>כולם בחכ' עשית</b>: תהלים קד, כד."],["4836","49","<b>ה' בחכמה יסוד</b>: משלי ג, יט [ושם: יסד ארץ]."]]],[2000470504,"שמים הם אש ומים<sup data-n=\"4837\">50</sup> מדות העליונות חו\"ג<sup data-n=\"4838\">52</sup> אך התגברות החסדים ולכן תיבת מים בפי' בשמים ומתי' אש אינו רק ש'<sup data-n=\"4839\">51</sup>, דרק ש מים בקמץ והקמץ מוציא אלף וה\"ז כמו ז\"א רובו חסדים<sup data-n=\"4840\">53</sup>, והנה אהבה הרי יש מי שאוהב<sup data-n=\"4841\">54</sup> שה\"ה מציאות היש ויש לו אהבה לאלקות אבל ביראה א\"א לומר כן שה\"ה בטל וא\"כ אינו בחי' יש, אף ששניהם מדות מ\"מ א\"ד כלל, ולכן כונן שמים בתבונה דוקא דאהבה הוא מצד השגה וכמו עד\"מ כשרואה בא' איזה הנהגה טובה ה\"ה אוהב אותו וכרוך אליו ויראה הוא מצד העדר השגה מפני שאינו משיג אותו לכן הוא ירא מפניו, וזהו כונן שמים בתבונה דאינו שייך שיאהב האדם מה שאינו מובן<sup data-n=\"4842\">55</sup> בשכלו רק כשמתבונן בו וטוב לו הדבר ה\"ה אוהב אותו וא\"ל ה\"ה שונא אותו, אבל ארץ שרשו מעצם החכ', דהנה ארץ הוא בחי' מל'<sup data-n=\"4843\">56</sup> ותמיד הוא בטל ולכן הכל דורסין עליו וכל הבנינים עומדים על הארץ וצמיחה ג\"כ על הארץ דוקא וה\"ז כמו ביטל העבד לאדונו שמשתחווה אליו שהראש והרגל שוים ור\"ל כמו שהרגל אינו שייך שיאמר דעה בהנהגה כמו\"כ הראש ג\"כ אינו אומר שום דעה כלל, וה\"ז כמו הביטל דחכ' לכן שרשה מחכ' דוקא.\n<b>וזהו</b> שכ' בזהר באורייתא ברי עלמא<sup data-n=\"4844\">57</sup>, כד ברי קוב\"ה עלמא<sup data-n=\"4845\">58</sup> אחזייא דלא אתקיים וברי אורייתא, פי' קוב\"ה א\"ס המאציל, עלמא אצי', עד דברי אורייתא היינו חכ' דאצי' שהוא חכ' התורה וזהו ה' בחכ' דוקא יסד ארץ, הגם דביטל דחכ' הוא ביטל אמיתי משא\"כ ביטל דמל' הוא ביטל היש לאין מ\"מ בעבודה יש מעלה בביטל היש, דביטל אמיתי ה\"ה אינו מהות כלל וא\"כ לא יש עבודה אבל ביטל היש ה\"ה מציאות היש דאל\"כ ה\"ז ביטל אמיתי רק שהיש בטל להאין וכמו העבד שהוא מציאות בפ\"ע רק שמבטל דעתו ורצונו לגמרי הרי יש עבודה וכמו המעלה שיש באתכפיי' על אתהפכא, מ\"מ ביטל אמיתי הוא ביטל העליון יותר, אך ביטל היש הוא בערך ביטל אמיתי ולכן הם שוים בשמותם וכמו משה עבדי<sup data-n=\"4846\">59</sup> ודוד עבדי<sup data-n=\"4847\">60</sup>, משה עבדי הוא ביטל אמיתי ודוד עבדי הוא ביטל היש ומ\"מ נק' שניהם עבד, וזהו שא' דוד ע\"ע ואנכי תולעת ולא איש חרפת אדם ובזוי עם<sup data-n=\"4848\">61</sup> שהי' בטל לגמרי, וכן חכ' עילאה וחכ' תתאה יראה עילאה ויר\"ת יו\"ד בראש ויו\"ד בסוף<sup data-n=\"4849\">62</sup>, והוא מפני ששניהם ביטל.",[["4837","50","<b>שמים הם אש ומים</b>: ראה חגיגה יב, סע\"א. רש\"י בראשית א, ח."],["4838","52","<b>שמים. . מדות העליונות חו\"ג</b>: ראה (לעיל בחלק המאמרים) שם ובהערה 1039."],["4839","51","<b>שמים הם אש ומים. . רק ש'</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן פל\"ב ובהערה 1038."],["4840","53","<b>ז\"א רובו חסדים</b>: ראה גם תו\"ח וירא קד, ד ובהערה 33."],["4841","54","<b>יש מי שאוהב</b>: מובא בכ\"מ בדא\"ח ומהם תו\"א וארא נו, א. יתרו סז, ג. סה\"מ תרל\"ח ס\"ע קלה. וש\"נ."],["4842","55","<b>מובן</b>: אולי כתוב: מבין."],["4843","56","<b>ארץ הוא בחי' מל'</b>: ראה זהר תוספתא בראשית לא, ב."],["4844","57","<b>באורייתא ברי עלמא</b>: ראה זהר בהקדמה ה, א. בראשית כד, ב. מז, א."],["4845","58","<b>כד ברי קוב\"ה עלמא</b>: ראה זהר ויגש רז, א."],["4846","59","<b>משה עבדי</b>: יהושע א, ב. ז. מלאכי ג, כב."],["4847","60","<b>ודוד עבדי</b>: שמואל-ב ג, יח. ועוד. ראה גם מאמרי אדה\"ז תקס\"ז ע' שסט."],["4848","61","<b>ואנכי תולעת. . עם</b>: תהלים כב, ז."],["4849","62","<b>יו\"ד בראש ויו\"ד בסוף</b>: ראה מגן דוד להרדב\"ז אות היוד. מאמרי אדה\"א בראשית ע' תכד. וש\"נ. או\"ת ר\"פ לך הובא באוה\"ת ואתחנן ס\"ע רעו ואילך."]]],[2000470505,"<b>ועפ\"ז</b> יובן ההפרש בין שבת ליומין דחול, יומין דחול הוא כמו מלך שיצא לעבדיו והם משתחוים לפניו כמו שצריכים להיות בטל לפני המלך מ\"מ א\"ז כמו מי שנכנס בחדרי המלך לפני ולפנים שהוא בטל במציאות לגמרי, דכשהמלך עובר במדינה והעבדים משתחווים לפניו הרי העבד הוא על עמדו ועל מקומו רק שבטל, אבל כשנכנס להמלך ה\"ה נתבטל במציאות לגמרי, וכמו\"כ יובן הביטל דשבת דמל' נתעלה בחכ' הרי אז בחי' ביטל במציאות וזהו כדין קדש קרינן לה, דהביטל הוא ע\"י שמאיר הארה מחכ' ונתעלה לקדש ובטל שם במציאות א\"כ ה\"ה ג\"כ בחי' קדש וזהו כדין קדש כו' דמבי אבא כו', הגם דבחול בשמ\"ע נמשך ג\"כ בחי' חכ'<sup data-n=\"4850\">63</sup> והו\"ע הביטל דשמ\"ע, מ\"מ א\"ז רק לחדש הישנות (ר\"ל לגבי נשמות חדשות דבשבת נק' זה חדוש הישנות ע' בד\"ה הנ\"ל<sup data-n=\"4851\">64</sup> ) אבל בשבת נמשך להוליד נשמות, אך צ\"ל אתעדל\"ת הגם דשבת נעשה ממילא מ\"מ כתי' לעשות השבת<sup data-n=\"4852\">65</sup>, והיינו מה שנמשך הארה מבחי' חכ' (בשבת ע' בד\"ה הנ\"ל) וזהו שבת בחי' קדש מילי' בגרמי', ויו\"ט הוא מקרא קדש והו\"ע קדוש וא\"ו, מ\"מ הוא ג\"כ קדוש ומובדל.\n<b>וזהו</b> וביום הביכורים כו' דהנה שבועות היו\"ט הוא שהוא יום החמשים<sup data-n=\"4853\">66</sup>, נוסף על שבו הי' מ\"ת<sup data-n=\"4854\">67</sup> והוא בחי' חכ' וכמ\"ש אורייתא מחכ' נפקת<sup data-n=\"4855\">68</sup> ור\"ל שמתלבש בכמה לבושים מ\"מ יש בו נקודות החכ' וכשנתנה תורה למטה ממילא האיר בחי' חכ' ג\"כ, לכן אז חמץ תאפינה, דכל המנחות באות מצה, דחמץ הוא הגבה והתנשאות<sup data-n=\"4856\">69</sup>, וזהו בינה מינה דינין מתערין בסופא<sup data-n=\"4857\">70</sup> וכמו אברהם יצא ממנו ישמעאל<sup data-n=\"4858\">71</sup> יצחק כו' עשו וכמו הידים שגדולים בהם צפרנים ויש צואה שתחת הצפורן, אבל בחכ' לא יש יניקת החיצונים לכן בשבועות דוקא חמץ כו' להורות על הגילוי דשבועות שמאיר בחי' חכ', הגם שהי' אכילת כהנים<sup data-n=\"4859\">72</sup>, הנה באמת הוא מדרי' גבוה וכמארז\"ל ע\"פ ואם האכל יאכל<sup data-n=\"4860\">73</sup> בשתי אכילות הכתוב מדבר א' אכילת כהנים וא' אכילת מזבח, אכילת",[["4850","63","<b>דבחול בשמ\"ע. . חכ'</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן פרק ג\"ל ובהערה 1060."],["4851","64","<b>בד\"ה הנ\"ל</b>: שבהערה 32 ע' תכה."],["4852","65","<b>לעשות השבת</b>: תשא לא, טז [בדילוג]."],["4853","66","<b>שבועות. . יום החמשים</b>: אמור כג, טז. כא. פ' ראה טז, י. פינחס כח, כו. תשא לד, כב."],["4854","67","<b>שבועות. . שבו הי' מ\"ת</b>: ראה נוסח התפלה וקידוש. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"א. לקו\"ש שבועות כרך ח ע' 21."],["4855","68","<b>אורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["4856","69","<b>דחמץ הוא הגבה והתנשאות</b>: ראה לקו\"ת צו יג, ג. שה\"ש יד, ד."],["4857","70","<b>בינה מינה דינין מתערין בסופא</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["4858","71","<b>אברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. וש\"נ. שע\"ת פה, ג ובהערה 14. תו\"ח בא ח\"א קכז, ב."],["4859","72","<b>בשבועות. . חמץ. . אכילת כהנים</b>: מנחות עד, ב במשנה."],["4860","73","<b>ואם האכל יאכל</b>: צו ז, יח. זבחים יג, ב. ראה לקו\"ת צו ז, ד ואילך. מאמרי אדה\"ז תקס\"ה ח\"א ע' קסג ואילך. סה\"מ תרכ\"ז ע' שלז. תרכ\"ט ע' רמט ואילך. וש\"נ. ראה (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז על יד הערה 112 ואילך. לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 72 ואילך."]]],[2000470506,"מזבח הוא ארי' דאכיל קורבנין<sup data-n=\"4861\">74</sup> והיינו ד' חיות המרכבה<sup data-n=\"4862\">75</sup> אך הנה כתי' ועל דמות הכסא דמות כמראה אדם עליו מלמעלה<sup data-n=\"4863\">76</sup> הוא מראה דמות כבוד ה'<sup data-n=\"4864\">77</sup>, ואכילת כהנים מעורר אכילת אדם למעלה, וזהו חמץ תאפינה מפני שהאיר בחי' חכ'. אך צ\"ל דהנה שבת הוא מוחין דאבא מפני מה חמץ אסור, וי\"ל דבשבת הוא בדרך העלאה מלמטלמ\"ע, והגם דמל' מתעלה מ\"מ אינו יכול להעלות את החמץ ג\"כ, אבל בשבועות נמשך בחי' חכ' למטה וממילא נתברר גם החמץ לכן אפשר להתעלות, וזהו סולת תהיינה היינו נקיי' מבוררת, וזהו הכל מודים דמ\"ת הי' בשבת<sup data-n=\"4865\">78</sup> והיינו שנמשך בחי' חכ' למטה. וזהו וביום הביכורים בהקריבכם מנחה חדשה שהוא דבר חדש, והשתי לחם הי' מחטה הם ך\"ב אתוון דאורייתא<sup data-n=\"4866\">79</sup> והיינו שהאיר בחי' חכ' ולכן אז דוקא סולת תהיינה חמץ תאפינה.",[["4861","74","<b>ארי' דאכיל קורבנין</b>: ראה זהר בהקדמה ו, ב. המשך זאת חנוכת המזבח שם פ\"ה. מאמרי אדה\"א ויקרא ח\"ב ע' תקלא. וש\"נ. שה\"א עט, ב הערה 13."],["4862","75","<b>ד' חיות המרכבה</b>: יחזקאל א, ה ואילך."],["4863","76","<b>ועל דמות הכסא. . מלמעלה</b>: יחזקאל א, כו."],["4864","77","<b>הוא מראה דמות כבוד ה'</b>: יחזקאל שם, כח."],["4865","78","<b>הכל מודים דמ\"ת הי' בשבת</b>: ראה גם לקמן (בחלק ההנחות) בהנחה ד\"ה וביום הביכורים כאן על יד הערה 106. המשך תער\"ב ח\"ב ע' א'צא: וכמא' הכל מודים כו'. שבת פו, ב. תורת לוי יצחק תענית ג, רע\"א."],["4866","79","<b>מחטה הם ך\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."]]],[2000470507,"<h3>ויאמר משה אל העם אל תיראו</h3>\n<b></b><b>יום ב' דחה\"ש אחר התפלה</b>\nיום ב' דחה\"ש אחר התפלה\n<b>ויאמר</b> משה אל העם אל<sup data-n=\"4867\">1</sup> תיראו<sup data-n=\"4868\">2</sup> כי לבעבור נסות אתכם בא ולבעבור<sup data-n=\"4869\">3</sup> תהי' יראתו על פניכם לבלתי תחטאו. וצ\"ל<sup data-n=\"4870\">4</sup>",[["4867","1","<b>ויאמר משה אל העם אל תיראו</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים בהמשך מצה זו פל\"ד-פל\"ו. וש\"נ.\nהנחה אחרת מדרוש זה נדפסה לקמן בחלק ההנחות."],["4868","2","<b>ויאמר משה אל העם אל תיראו</b>: יתרו כ, יז."],["4869","3","<b>ולבעבור</b>: שם: האלקים ובעבור."],["4870","4","<b>וצ\"ל</b>: ע\"כ נרשם בגוכתי\"ק. ראה לקמן ע' תפ."]]],[2000470508,"<h3>כי טובים דודיך מיין</h3>\n<b>ש\"פ נשא תר\"ם לפ\"ק</b>\n<b>כי</b> טובים דודיך<sup data-n=\"4871\">1</sup> מיין<sup data-n=\"4872\">2</sup> וארז\"ל ערבים עלי דברי דודים<sup data-n=\"4873\">3</sup> יותר מיינה ש\"ת, ופרש\"י דברי דודים הם ד\"ס מיינה ש\"ת מעיקרי'<sup data-n=\"4874\">4</sup> ש\"ת, דיינה ש\"ת הוא תושב\"כ והוא בחי' בינה יין<sup data-n=\"4875\">5</sup> המשמח<sup data-n=\"4876\">6</sup>, וד\"ס הם תושבע\"פ הם למעלה מתושב\"כ דבינה יתירה ניתנה באשה<sup data-n=\"4877\">7</sup> יותר מבאיש.\n<b>וביאור</b> הענין הנה כתי' החדלתי את תירושי<sup data-n=\"4878\">8</sup> המשמח אלקים ואנשים, ואמרז\"ל אם אנשים משמח אלקים במה משמח מכאן שאין אומרים שירה אלא על היין<sup data-n=\"4879\">9</sup>, והיינו שיר הלוים הוא על יין, דהנה היין בתחילה הוא כנוס בענביו וע\"י הדריכה הוא יוצא מהעלם אל הגילוי וכמו\"כ כל דבר שהוא בגילוי הי' תחילה בהעלם (בפ\"א<sup data-n=\"4880\">10</sup> וכל שהוא יותר בהעלם<sup data-n=\"4881\">11</sup> הוא יוצא לידי גילוי משובח יותר) וכמו הולד שהוא נעלם תחילה בבטן האם ט' ירחי לידה<sup data-n=\"4882\">12</sup> ואח\"כ יוצא לידי גילוי וזהו ההולדה, וכל שהוא יותר בהעלם הוא יוצא בריא ומזוכך יותר<sup data-n=\"4883\">13</sup>. וכן הגרעין שמתעלם בהארץ ונרקב שם וממנו הצמיחה<sup data-n=\"4884\">14</sup> הן פירות הן תבואה, וכל מה שישתהה יותר בהארץ ויורקב יותר, יהי' הצמיחה בריבוי ותוס', וכמו\"כ יובן למעלה כשהי' צ\"ל מ\"ת הי' תחילה גלות מצרים שהוא העלם ואח\"כ הי' מ\"ת, ומפני שהוא גילוי גליא של תורה לבד דפנימיות התורה לא נתגלה עתה לכן הי' די רד\"ו שנה<sup data-n=\"4885\">15</sup> ולע\"ל יהי' גילוי סתים דאורייתא לכן ההעלם גדול יותר, וזהו מ\"ש זורע צדקות מצמיח ישועות<sup data-n=\"4886\">16</sup>, דהנה כללות כל המצות נק' צדקה וכמ\"ש וצדקה תהי' לנו<sup data-n=\"4887\">17</sup> כי נשמור",[["4871","1","<b>כי טובים דודיך מיין</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר ד\"ה זה שנדפס לעיל בחלק המאמרים [ושם הפתיחא: והנה גם בתושבע\"פ שנק' אשה] בהמשך מצה זו פל\"ז-פט\"ל. וש\"נ.\nהמאמר כנראה לא נגמר בכתיבתו וראה המשך הענין לעיל בחלק המאמרים שם."],["4872","2","<b>כי טובים דודיך מיין</b>: שה\"ש א, ב."],["4873","3","<b>ערבים עלי דברי דודים</b>: ראה ע\"ז לה, א. וראה בפרש\"י שם."],["4874","4","<b>מעיקרי'</b>: אולי כתוב: מעיקרי."],["4875","5","<b>בינה יין</b>: ראה זהר נשא קכז, א. מאמרי אדה\"א ויקרא ח\"א ע' לג. וש\"נ. בראשית ע' תקעא."],["4876","6","<b>יין המשמח</b>: ראה להלן הערה 8."],["4877","7","<b>דבינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["4878","8","<b>החדלתי את תירושי</b>: ס' שופטים ט, יג. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א."],["4879","9","<b>אם אנשים משמח. . שירה אלא על היין</b>: ראה ברכות לה, א."],["4880","10","<b>בפ\"א</b>: ראה גם לעיל הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4881","11","<b>וכל שהוא יותר בהעלם</b>: ראה בסמוך הערה 13."],["4882","12","<b>ט' ירחי לידה</b>: ראה נדה לא, א."],["4883","13","<b>וכל שהוא יותר בהעלם. . יותר</b>: ראה גם סידור שער הלולב רסג, ב. לקו\"ש לך ח\"ב ע' 458."],["4884","14","<b>הגרעין. . ונרקב. . הצמיחה</b>: ראה אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. תו\"ח שמות ח\"א ב, ב. וש\"נ. לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד 118. לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 1159."],["4885","15","<b>גלות מצרים. . רד\"ו שנה</b>: ראה תנחומא מקץ ח. במדב\"ר פי\"ג, כ. רש\"י מקץ מב, ב לך שם בא יב, מ מגילה ט, א."],["4886","16","<b>זורע צדקות מצמיח ישועות</b>: בברכת יוצר. ראה גם בהנחה ובההמשך דלעיל הערה 14."],["4887","17","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה [בדילוג]. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה סמכוני באשישות ובהערה 65."]]],[2000470509,"לעשות<sup data-n=\"4888\">18</sup> כל המצוה הזאת, וגם עצם מצות צדקה עי\"ז מצמיח ישועות הם שע\"ה נהורין<sup data-n=\"4889\">19</sup>, וכמו ע\"י זריעת הגרעין יצמחו הפירות הגם שאינו בערך שמהגרעין יצמח אילן עם ענפים ועלים ופירות מ\"מ אנו רואין שנצמח כ\"ז מהגרעין כמו\"כ ע\"י המצות מצמיח שע\"ה נהורין הגם שאינם בערך מ\"מ זהו ענין הצמיחה כך. וזהו יין המשמח אלקים, דהנה אלקים הוא המצמצם ומסתיר וכמ\"ש כי שמש ומגן<sup data-n=\"4890\">20</sup> ה' אלקים כמו המגן שמכסה ומסתיר על השמש ובלתי לא<sup data-n=\"4891\">21</sup> היו יכולים לקבל אור השמש, ככה שם אלקים הוא מכסה ומסתיר על שם הוי', ויין הו\"ע יציאה מהעלם אל הגילוי וזהו יין המשמח אלקים (שמגלה) הצמצומים דשם אלקים, ושרש דיין זה מיין המשומר בענביו משי\"ב<sup data-n=\"4892\">22</sup> שהוא מדרי' גבוה כ\"כ א\"א לבוא לידי גילוי כ\"א משומר בענביו משימ\"ב. וזהו יין המשמח כו' היינו שנמשך שם הוי', וזהו במקדש היו קוראין את השם ככתבו<sup data-n=\"4893\">23</sup> שהי' שם גילוי שם הוי', וזהו נכנס יין יצא סוד<sup data-n=\"4894\">24</sup> והוא סוד ה'<sup data-n=\"4895\">25</sup> וכמ\"ש ושם העיר מעולם ה' שמה<sup data-n=\"4896\">26</sup>, מה שנק' עתה עיר אלקינו<sup data-n=\"4897\">27</sup> יקרא לע\"ל שם ה'.\n<b>והנה</b> כ\"ז הוא העלם וגילוי שהוא סדר השתל' דהעלם וגילוי הוא סוכ\"ע וממכ\"ע<sup data-n=\"4898\">28</sup>, וכמו השלשלת שהתחתון אחוז בהעליון, שאחיזתו בתחתיתו מ\"מ הוא בערכו מאחר שיש לו אחיזה בו, וכמו\"כ העלם וגילוי מאחר שלפעמים בא לידי גילוי מוכרח לומר שהוא בערכו, אבל כי טובים דודיך מיין שלמעלה גם מההעלם, דהנה העלם וגילוי הוא כמו חושך ואור וכמו מאפילה לאור גדול<sup data-n=\"4899\">29</sup>, דהנה כתי' העם היושבים בחשך<sup data-n=\"4900\">30</sup> ראו אור גדול, חשך הוא כמ\"ש החשך יכסה ארץ<sup data-n=\"4901\">31</sup> שנראה שהעולם כמנהגו נוהג<sup data-n=\"4902\">32</sup>, דהשמש זורח ממזרח ושוקע למערב וקיץ וחורף ויום ולילה לא ישבותו<sup data-n=\"4903\">33</sup>, אך באמת אינו כן דלכל דבר יש אין המהווהו מאין ליש וכשיסתלק כרגע יתבטל ממציאותו, רק שהעין הגשמי אינה רואה רק היש אבל באמת אלמלי ניתנה רשות לעין לראות לא יש שום יש כלל וכמ\"ש בסש\"ב<sup data-n=\"4904\">34</sup> דאלמלי מתכנסין כל באי עולם<sup data-n=\"4905\">35</sup>",[["4888","18","<b>לעשות</b>: אולי כתוב: ולעשות."],["4889","19","<b>שע\"ה נהורין</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז ובהערה 121."],["4890","20","<b>כי שמש ומגן</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["4891","21","<b>ובלתי לא</b>: אולי צ\"ל: ובלתי המגן לא."],["4892","22","<b>מיין המשומר בענביו משי\"ב</b>: ראה ברכות לד, ב. מאמרי אדה\"א דברים ח\"א ע' סז. וש\"נ. תו\"ח לך צא, ג הערה 32."],["4893","23","<b>במקדש היו קוראין את השם ככתבו</b>: ראה תמיד פ\"ז, מ\"ב."],["4894","24","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם תו\"ח ויחי רלו, ב."],["4895","25","<b>סוד הוי'</b>: תהלים כה, יד."],["4896","26","<b>ושם העיר מעולם הוי' שמה</b>: יחזקאל מח, לה [ושם: ושם העיר מיום הוי' שמה]. ראה גם סה\"מ תרל\"ח ע' כו."],["4897","27","<b>עיר אלקינו</b>: תהלים מח, ב."],["4898","28","<b>סוכ\"ע וממכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["4899","29","<b>מאפילה לאור גדול</b>: פסחים קטז, ב (במשנה). הגדה פיסקא לפיכך."],["4900","30","<b>העם היושבים בחשך</b>: וכ\"ה לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 1177 — ובישעי' ט, א: ההולכים."],["4901","31","<b>החשך יכסה ארץ</b>: ישעי' ס, ב."],["4902","32","<b>שהעולם כמנהגו נוהג</b>: ע\"ז נד, ב."],["4903","33","<b>וקיץ וחורף. . ישבותו</b>: נח ח, כב."],["4904","34","<b>אלמלי ניתנה רשות. . בסש\"ב</b>: ראה שער היחוד והאמונה פ\"ג."],["4905","35","<b>דאלמלי מתכנסין כל באי עולם</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. אוה\"ת בראשית כרך ו ע' 2040. המשך מים רבים תרל\"ו פכ\"ה. לקו\"ש משפטים כרך כו ע' 366. לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים על יד הערה 54 ואילך."]]],[2000470510,"אינם יכולים לברוא אפי' כנף יתוש אחד א\"כ הכל אלקות (המהווה הכל) וזהו נק' אור וחושך, אבל ערבים עלי ד\"ס שהוא בחי' דחשך ואור שוים לקמי' וכמ\"ש גם חשך לא יחשיך כל נהוראין מתחשכאין קמי'<sup data-n=\"4906\">36</sup> כתר עליון אע\"ג דאיהו אור צח אור מצוחצח אוכם הוא<sup data-n=\"4907\">37</sup> קדם עילת העלות, הרי שאפי' בחי' אור צח או מצוחצח מ\"מ אוכם כו' פי' שחרות היינו שהוא מציאות של שחרות ביטל.\n<b>וביאור</b> ענין יין המשמח אלקים, דהנה כתי' אם הבנים שמחה<sup data-n=\"4908\">38</sup>, אם הבנים הוא בינה ושם שייך שמחה, דשמחה הוא מצד השגה והבנה, דכשהשכל עדיין בברק המבריק<sup data-n=\"4909\">39</sup> אינו שייך שמחה רק כשבא לידי השגה והבנה אז שייך שמחה, ולכן בינה שהו\"ע השגה והבנה שייך שם שמחה, אך ידוע דבינה הוא עלמא דאתכסייא<sup data-n=\"4910\">40</sup> וזהו הי' עבודת הלוים דכתי' ועבד הלוי הוא<sup data-n=\"4911\">41</sup>, דיש אתה והוא, אתה הוא גילוי, והוא הסתר, וזהו הי' עבודתם להמשיך מעלדאת\"כ שיומשך למטה.",[["4906","36","<b>כל נהוראין מתחשכאין קמי'</b>: ראה זהר בראשית כג, א."],["4907","37","<b>כתר עליון. . אוכם הוא</b>: ראה ת\"ז ת\"ע קלה, ב. מאמרי אדה\"א דברים ח\"ג ע' תתיא. וש\"נ. המשך והחרים תרל\"א ע' סט. סה\"מ תרל\"ד ע' רמז. המשך תער\"ב ח\"א ע' כא."],["4908","38","<b>אם הבנים שמחה</b>: תהלים קיג, ט. ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 208. וראה גם בהבא בסמוך לקו\"ת צו יא, ד ואילך."],["4909","39","<b>בברק המבריק</b>: ראה גם בענין ברק המבריק לעיל הנחה ד\"ה כי הנה יוצר הרים ובהערה 21."],["4910","40","<b>דבינה הוא עלמא דאתכסייא</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 1185."],["4911","41","<b>ועבד הלוי הוא</b>: קרח יח, כג."]]],[2000470511,"<h3>ערבים עלי דברי דודיך</h3>\n<b>ש\"פ שלח תר\"ם לפ\"ק</b>\n<b>ערבים</b> עלי דברי דודיך<sup data-n=\"4912\">1</sup> (פי' ד\"ס) יותר מיינה ש\"ת<sup data-n=\"4913\">2</sup>, ונת\"ל שהו\"ע בינה יתירה שנתנה באשה<sup data-n=\"4914\">4</sup> יותר מבאיש, דמל\"ת הם השגת השלילה<sup data-n=\"4915\">3</sup> אבל ז\"מ דרבנן<sup data-n=\"4916\">5</sup> הם קום ועשה ודוחה יניקת החיצונים וכמו מצות נט\"י שהיא עשי' ודוחה יניקת החיצונים. והנה להבין ענין מצות נט\"י צ\"ל תחילה שם נטיל\"ת ידים דוקא, ולכאו'",[["4912","1","<b>ערבים עלי דברי דודיך</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הי\"ד מהמשך מצה זו (פמ\"ג — פמ\"ה) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: ויובן כו' ענין נט\"י]. וש\"נ."],["4913","2","<b>ערבים עלי. . מיינה ש\"ת</b>: ע\"ז לה, א וברש\"י שם."],["4914","4","<b>בינה יתירה שנתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["4915","3","<b>ונת\"ל. . דמל\"ת הם השגת השלילה</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו פ\"מ ואילך."],["4916","5","<b>ז\"מ דרבנן</b>: נסמן לעיל בהנחה ד\"ה סמכוני באשישות הערות 82-83."]]],[2000470512,"הול\"ל רחיצת ידים<sup data-n=\"4917\">6</sup>, והנה יש מפרשים שפי' מפני שהכלי נק' נטלא<sup data-n=\"4918\">7</sup> לכן קוראין זה נט\"י ובאמת דוחק לומר כן דהכלי הוא פרט א' מהפעולה והעיקר הוא המים ולמה נק' ע\"ש הכלי דוקא וקבעו הברכה כן, אך הנה נטילת ידים הוא ע\"ש שמגביהים את הידים עי\"ז וכמ\"ש שאו ידיכם קדש<sup data-n=\"4919\">8</sup>, נשיאות כפיים<sup data-n=\"4920\">9</sup> וינטלם וינשאם<sup data-n=\"4921\">10</sup>.\n<b>וביאור</b> ענין דהנה כתי' שאו ידיכם קדש ופי' בזהר אתר עילאה דמתמן נחלא עמיקא נפק<sup data-n=\"4922\">11</sup>, ופי' המפר'<sup data-n=\"4923\">12</sup> אתר עילאה חכ'<sup data-n=\"4924\">13</sup> אבא, נחלא עמיקא בינה (ובפ\"א<sup data-n=\"4925\">14</sup> והוא כמ\"ש ונהר יוצא מעדן<sup data-n=\"4926\">15</sup>, ושמו דההוא נהר יובל שמו<sup data-n=\"4927\">16</sup> והוא בחי' יובל שנק' קדש וכמ\"ש<sup data-n=\"4928\">17</sup> כו'), דהנה מדות דאצי' הגם דכתי' לא יגרך רע<sup data-n=\"4929\">18</sup> מ\"מ כשיורדים בבי\"ע נשתלשל מזה רע וכמו ידים שגדילים צפרנים וכמ\"ש וירא כי לא יכול לו<sup data-n=\"4930\">19</sup> דטעה ביעקב דסבור ששרשו ממדות ושם יש יניקת החיצונים אבל באמת יעקב הוא י' עקב<sup data-n=\"4931\">20</sup> שהוא בחי' חכ'<sup data-n=\"4932\">21</sup>, אך במדות יש יניקת החיצונים וזהו\"ע נט\"י שממשיכים מבחי' חכ' וכתי' ימותו ולא בחכ'<sup data-n=\"4933\">22</sup> דשם לא יש יניקת החיצונים וכמו\"כ מהנהר ג\"כ לא יש יניקת החיצונים דבעצם הבינה לא הי' שבה\"כ<sup data-n=\"4934\">23</sup> כ\"א בז\"ת דבינה אבל לא בג\"ר לכן משם נמשך לדחות החיצונים, ויובן זה ע\"ד דוגמא מז' קני מנורה והי' הדלקת הנרות והטבת הנרות והכל מכוון א', ז' נרות הם (ז' או ו')<sup data-n=\"4935\">24</sup> מדות וכמ\"ש לך",[["4917","6","<b>נטיל\"ת ידים. . רחיצת ידים</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1347."],["4918","7","<b>שהכלי נק' נטלא</b>: ראה שו\"ע אדה\"ז מהדו\"ק הלכות נט\"י ס\"ד, ס\"א. הלכות נט\"י סקנ\"ט, סכ\"ד."],["4919","8","<b>שאו ידיכם קדש</b>: תהלים קלד, ב."],["4920","9","<b>נשיאות כפיים</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1349."],["4921","10","<b>וינטלם וינשאם</b>: ישע' סג, ט. ראה גם (לעיל בחלק המאמרים) שם הערה 1348."],["4922","11","<b>אתר עילאה. . נפק</b>: ראה זהר ויקרא יג, א."],["4923","12","<b>ופי' המפר'</b>: מק\"מ שם."],["4924","13","<b>חכ'</b>: תיבה זו אינה ברורה כ\"כ."],["4925","14","<b>ובפ\"א</b>: ראה גם לעיל הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 80."],["4926","15","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["4927","16","<b>ושמו. . יובל שמו</b>: ראה זהר יתרו פג, א. אחרי נח, א. וראה גם בכורות נה, ב. ויק\"ר ספכ\"ב. ראה גם אוה\"ת שה\"ש כאן ע' תלח."],["4928","17","<b>יובל שנק' קדש וכמ\"ש</b>: בהר כה, יב — יובל היא קדש תהי' לכם."],["4929","18","<b>לא יגרך רע</b>: ראה תהלים ה, ה. לקו\"ת במדבר ג, ג."],["4930","19","<b>וירא כי לא יכול לו</b>: וישלח לב, כו. ראה גם לעיל הנחה ד\"ה אל יתהלל החכם על יד הערה 17 ואילך. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אשריכם זורעי על כל מים על יד הערה 41 ואילך."],["4931","20","<b>יעקב הוא י' עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה תו\"א ר\"פ ויצא. מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["4932","21","<b>י'. . בחי' חכ'</b>: ראה זהר בראשית לא, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשסד ובהנסמן לשם."],["4933","22","<b>ימותו ולא בחכ'</b>: איוב ד, כא. ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ג ובהערה 261."],["4934","23","<b>דבעצם הבינה לא הי' שבה\"כ</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן פמ\"ג ובהנסמן שם."],["4935","24","<b>ז' נרות. . או ו') מדות</b>: להעיר מלקו\"ש הוספות חגה\"ש כרך יג ע' 154 הערה ד\"ה נרות. ספר השיחות תשמ\"ח ח\"ב ס\"ע 482 ואילך ובהערה 56. וראה גם הערה שלאח\"ז."]]],[2000470513,"ה' הגדולה הגבורה<sup data-n=\"4936\">25</sup> והת\"ת והנצח וההוד, אך במדות את זלעו\"ז עשה אלקים<sup data-n=\"4937\">26</sup> וכמו שיש ז' מדות בקדושה כמו\"כ יש ז\"מ בלעו\"ז דמאהבה דקדושה נמשך בריבוי השתל' תאווה זרה ומיראה נמשך יראה רעה וכעס שכ\"ז מגבו' ומת\"ת נמשך ענין ההתפארות וכמו\"כ מכולם, ואהרן כהנא רבא הי' מדליק את הנרות היינו שהמשיך בהם בחי' חכ' ואינו שייך אז יניקת החיצונים, ובלילה שהוא זמן החשך צריכים ז' נרות דאור הוא חכ'<sup data-n=\"4938\">28</sup> ולכן אז שהוא זמן יניקת החיצונים צריכים ריבוי אור וביום שיניקת החיצונים אינו כ\"כ לא הי' רק ב' נרות<sup data-n=\"4939\">27</sup>, וזהו בעולם שהוא בהמ\"ק ובזמן שהי' בלילה וכמו\"כ הוא בנפש<sup data-n=\"4940\">29</sup> וכמ\"ש בהעלותך את הנרות<sup data-n=\"4941\">30</sup> נר הוא נשמה וכמ\"ש נר ה' נשמת אדם<sup data-n=\"4942\">31</sup> ואהרן מעלה את הנרות הגם דנשמה שנתת בי טהורה היא מ\"מ ירדה דרך בחי' בראת<sup data-n=\"4943\">32</sup> יצרת נפחת צריכים להעלים<sup data-n=\"4944\">33</sup> אותם וכמו בבהמ\"ק כתי' בהעלותך את הנרות הגם שנתן בהם שמן ואור ה\"ז המשכה ומ\"מ נק' העלאה והיינו מפני שעי\"ז מעלים אותם, וכמו\"כ כאן שממשיך בחי' חכ' ועי\"ז מעלה אותם, וזהו נט\"י שמעלה את הידים וכמו נשיאות כפים וכמ\"ש שאו ידיכם קדש וכמו וינטלם וינשאם.\n<b>אך</b> צ\"ל מה שייך נט\"י ללחם חולין<sup data-n=\"4945\">34</sup>, דללחם תרומה קודש שייך נט\"י<sup data-n=\"4946\">35</sup> אבל מה שייך נט\"י ללחם חולין. והענין דהנה לחם שרשה מחסד דאצי' לכן אומרים הזן את העולם כולו בטובו בחן ובחסד<sup data-n=\"4947\">36</sup>, הגם דמשה תקן ברכת הזן<sup data-n=\"4948\">37</sup> וא\"כ קאי על בחי' לחם מן השמים, ומ\"מ אומרים עתה ג\"כ ברכת הזן, ומתרצים מפני דלחם מן הארץ",[["4936","25","<b>לך ה' הגדולה הגבורה</b>: דבהי\"א כט, יא [ושם: והגבורה]. ומונה כאן רק ה'. וראה הערה שלפנ\"ז."],["4937","26","<b>אזלע\"ז עשה אלקים</b>: קהלת ז, יד. ראה גם סה\"מ תרל\"ח ע' קלד."],["4938","28","<b>דאור הוא חכ'</b>: ראה זהר בראשית ל, ב. לקו\"ת מטות פב, ג. וש\"נ. שעה\"י קכז, ב הערה 38. ש\"א ד, א הערה 10."],["4939","27","<b>ובלילה. . ז' נרות. . וביום. . ב' נרות</b>: ראה לקו\"ש בהעלותך כרך כג ע' 354. כרך יג ע' 193 ואילך. ובאג\"ק שלו חי\"ט ר\"ע קיד. רשימות חוב' מז. עא. פ."],["4940","29","<b>בעולם. . ובזמן. . בנפש</b>: ראה ס\"י פ\"ג, מ\"ג ואילך. מאמרי אדה\"א בראשית ע' נו ואילך. וש\"נ. תו\"ח וארא ח\"א נג, ב ובהערה 13. סה\"מ תרל\"ח ע' מג. וש\"נ."],["4941","30","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב."],["4942","31","<b>נר ה' נשמת אדם</b>: משלי כ, כז. ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ד ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא'."],["4943","32","<b>דנשמה. . טהורה. . בראת</b>: ברכת אלקי נשמה (מברכות ס, ב). ראה גם (לעיל בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ו."],["4944","33","<b>להעלים</b>: אוצ\"ל: להעלות."],["4945","34","<b>נט\"י ללחם חולין</b>: ראה חולין קו, א. שו\"ע אדה\"ז הל' נט\"י רסקנ\"ח. סה\"מ תרל\"ב ח\"א ע' קמו."],["4946","35","<b>דללחם תרומה. . נט\"י</b>: שבת יד, ב ואילך."],["4947","36","<b>הזן. . ובחסד</b>: נוסח ברכת המזון [כ\"ה בסידור תפלה למשה להרמ\"ק<sup data-n=\"e267\">א</sup>. ר\"ש ראשקוב. קול יעקב. ועוד<sup data-n=\"e268\">ב</sup>. בסידור אדה\"ז: בחסד]."],["4948","37","<b>דמשה תקן ברכת הזן</b>: ברכות מח, ב. ראה לקו\"ת עקב יד, ב ואילך.\n\n<b>א</b>  אבל אולי נוסח ברהמ\"ז היא הוספת המו\"ל.\n\n<b>ב</b>  וכ\"ה גם במאמרי אדה\"ז תקס\"ה ח\"ב ע' תתנג. שע\"ת ה, סע\"ד. ש\"א כו, ב. תו\"ח בשלח ח\"א קע, ב. אוה\"ת שה\"ש כאן ע' תלח. (לעיל בחלק המאמרים) המשך מצה זו כאן פמ\"ד."]]],[2000470514,"שרשו מן לחם מהשמים (בפ\"א טל מן) ושרשו מחסד דז\"א (ר\"ל שרש לחם מן הארץ הוא מחסד ועוד יש לו שרש מטל ומן כנ\"ל), וכדי שיתגשם ויהי' לחם הוא ע\"י שיורד בבי\"ע וזהו\"ע מעשה בראשית, דמעשה הוא כמ\"ש על כל שבח מעשה ידיך<sup data-n=\"4949\">38</sup> וצ\"ל מה שייך מעשה למעלה, והלא לא בעמל לא ביגיעה<sup data-n=\"4950\">39</sup> ברא הקב\"ה את עולמו כ\"א במאמר וברוח פיו, אלא כמו שמעשה למטה הוא כח האחרון שבאדם והוא נפרד דדיבור נראה כמו שהוא נפרד אבל באמת אינו נפרד אבל מעשה הוא נפרד וכמו\"כ למעלה מעשה הוא בחי' אחרונה (אבל באמת אין לך דבר שחוץ ממנו), וזהו שיש הפרש בין ששת ימי המעשה לשבת, דכשם שיש הפרש בגשמית דבשיה\"מ יש מלאכת הזורע והחורש<sup data-n=\"4951\">40</sup> והקוצר והמעמר כו', והו\"ע הבירורים ובשבת בורר אסור<sup data-n=\"4952\">41</sup> מפני שנברר ממילא, וכמו\"כ בעבודה יש הפרש בין אתכפי' לאתהפכא דשיה\"מ העבודה בדרך אתכפי' ובשבת העבודה בדרך אתהפכא, הרי שרש הלחם מחסד דרועא ימינא<sup data-n=\"4953\">42</sup> שהוא בחי' ידים, והנה בידים יש אצבעות, דהנה חסד כמו שהוא למעלה הוא בחי' יד (ויש בזה כמה מדרי'), אך כדי שיבוא למטה צריך להתחלק לחלקים וכמו חסד שבחסד גבו' שבחסד כו', ולפ\"ז ה' אצבעות דיד ימין ויד שמאל הם ה\"ח וה\"ג<sup data-n=\"4954\">43</sup> ויש חסד שבגבו' גבו' שבגבו' וחסד שבחסד וגבו' שבחסד, ועל האצבעות יש צפרנים, והנה הצפרנים הם דין ויש שהם דבוקים בבשר ויש מה שחוץ לבשר.\n<b>והענין</b> דהנה ארז\"ל לא כאברהם שיצא ממנו ישמעאל<sup data-n=\"4955\">44</sup>, דאברהם הי' מרכבה למדת החסד<sup data-n=\"4956\">45</sup> וכמ\"ש<sup data-n=\"4957\">46</sup> בפרד\"ס<sup data-n=\"4958\">47</sup> בשם ס' הבהיר<sup data-n=\"4959\">48</sup> אמרה מדת החסד לפני הקב\"ה<sup data-n=\"4960\">49</sup> כל ימי היות אברם בארץ<sup data-n=\"4961\">50</sup> לא הוצרכתי אני לעשות מלאכתי שהרי אברם עומד ומשמש במקומי, ומפרשים עומד ומשמש שהי' מחלי\"ף מקו\"ם מדות החסד<sup data-n=\"4962\">51</sup> וז\"ש דלא הוצרכתי אני לעשות מלאכתי כלל ולכן הי' מאכיל ומשקה לכל",[["4949","38","<b>על כל שבח מעשה ידיך</b>: ברכת יוצר. ראה תו\"א יתרו סז, א."],["4950","39","<b>לא בעמל לא ביגיעה</b>: ראה ב\"ר פ\"ג, ב. ספ\"י."],["4951","40","<b>הזורע והחורש</b>: שבת עג, א."],["4952","41","<b>ובשבת בורר אסור</b>: ראה שו\"ע אדה\"ז הל' שבת סשי\"ט. תו\"א ח\"ש טו, ג. בשלח סה, סע\"ב ואילך. תשא קיג, א. מאמר ד\"ה ברוך שעשה נסים (ט\"ו תמוז) תש\"כ."],["4953","42","<b>מחסד דרועא ימינא</b>: ת\"ז בהקדמה יז, א."],["4954","43","<b>ה' אצבעות. . ה\"ח וה\"ג</b>: מאו\"א מערכת אצבעות סקמ\"ט."],["4955","44","<b>לא כאברהם שיצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. וש\"נ. שע\"ת פה, ג ובהערה 14. תו\"ח בא ח\"א קכז, ד."],["4956","45","<b>דאברהם. . החסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["4957","46","<b>כמ\"ש בפרד\"ס</b>: ראה שער טעם האצילות ש\"ב, פ\"ב. שער הכנויים שכ\"ב, פ\"ד (בשינוי קל). ראה גם סה\"מ תרס\"ג ח\"ב ע' צא."],["4958","47","<b>בפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["4959","48","<b>ס' הבהיר</b>: סקצ\"א (בשינוי קל). זח\"א בהשמטות רסד, ריש ע\"ב."],["4960","49","<b>לפני הקב\"ה</b>: תיבות אלו לא הובאו שם."],["4961","50","<b>בארץ</b>: וכ\"ה לעיל (בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 10."],["4962","51","<b>אברם. . מחלי\"ף מקו\"ם מדות החסד</b>: נסמן לעיל (בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה הערה 52."]]],[2000470515,"אפי' לערביים<sup data-n=\"4963\">52</sup>, וכמו אברהם למטה כמו מדות החסד למעלה. והנה מי שהוא וותרן משפיע לכל<sup data-n=\"4964\">53</sup> אפי' למי שאינו ראוי כלל וכלל וכמו אברהם שאמר לו ישמעאל יחי' לפניך<sup data-n=\"4965\">54</sup>, הגם שהי' בנו מ\"מ ידע איכותו ומהותו<sup data-n=\"4966\">55</sup>, ומכ\"ש אחר שא\"ל שרה גרש את האמה הזאת<sup data-n=\"4967\">56</sup> ואת בנה, למה כתי' וירע הדבר בעיניו<sup data-n=\"4968\">57</sup>, ומהו אומרו לו ישמעאל יחי' לפניך, אך זה מצד מדות החסד צריכים להשפיע אפי' למי שאינו ראוי דמאחר שיש הבחנה בין זה לזה ה\"ז קצת דין ומצד החסד צריכים להשפיע לכל, וזהו הצפרנים שגדילים על האצבעות כדי שיומשך למקום הראוי דוקא. ויובן זה מענין ג' מיני חשמלים שהי' לאדה\"ר<sup data-n=\"4969\">58</sup> דלבושו הי' מצפרנים<sup data-n=\"4970\">59</sup> ובזה הי' מדרי' חלוקות כמו שהי' קודם<sup data-n=\"4971\">60</sup> כשהי' בג\"ע שעז\"נ כתנות אור באלף<sup data-n=\"4972\">61</sup>, ואח\"כ נשארו הצפרנים רק על ראשי האצבעות, והנה אי' בכהאריז\"ל<sup data-n=\"4973\">62</sup> שלא נטעה לאמר דהצפרנים הם קליפה דהם דין דקדושה<sup data-n=\"4974\">63</sup> והצפורן שדבוק לבשר הוא קדושה ומה שיוצא לחוץ לבשר הוא קליפה, ויש בזה חילוקי' מה שכנגד הבשר ושלא כנגד הבשר, וזהו שארז\"ל מצוה לקוץ הצפרנים בע\"ש<sup data-n=\"4975\">64</sup> כדי שלא ינקו הקליפות ע\"י אמצעות ק\"נ דהצפורן הדבוק לבשר",[["4963","52","<b>מאכיל ומשקה. . לערביים</b>: ראה ב\"מ פו, ב. תו\"ח לך פג, ד הערה 57."],["4964","53","<b>וותרן משפיע לכל</b>: ראה הנסמן בסמוך הערה 55."],["4965","54","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח."],["4966","55","<b>ידע איכותו ומהותו</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה גור ארי' יהודה פ\"ב על יד הערה 45 ואילך ובהנסמן שם."],["4967","56","<b>גרש את האמה הזאת</b>: וירא כא, י [בהוספת תיבת: ”את\" — ראה תו\"ח ח\"ש קכו, א ובהערה 8. אוה\"ת ויקרא ח\"א ע' צד]."],["4968","57","<b>וירע הדבר בעיניו</b>: וירא שם, יא [ושם: מאד בעיני]."],["4969","58","<b>ג' מיני חשמלים שהי' לאדה\"ר</b>: ראה מק\"מ לזהר ויקהל רח, ב בשם ספר א\"י<sup data-n=\"e269\">ג</sup>. הדרת מלך סכ\"ג<sup data-n=\"e270\">ד</sup>. ע\"ח שער החשמל שמ\"א, פ\"א (הובא בתניא פ\"ב)."],["4970","59","<b>לאדה\"ר דלבושו הי' מצפרנים</b>: ראה<sup data-n=\"e271\">ה</sup> ב\"ר פ\"כ, יב<sup data-n=\"e272\">ו</sup>. פדר\"א פי\"ד זהר ויקהל שם ת\"ז בהקדמה י, סע\"ב ואילך תנ\"ח<sup data-n=\"e273\">ז</sup> (צב, ב). רש\"י בראשית ג, כא<sup data-n=\"e274\">ח</sup>. ע\"ח ונגיד ומצוה דלקמן הערה 66."],["4971","60","<b>קודם</b>: בגוכתי\"ק ניתוסף: וכמו שהי' אחר. ומחק תיבת אחר. ולפי\"ז לכאורה משמע שגם התיבות שלפנ\"ז ”וכמו שהי'\" מיותרות."],["4972","61","<b>כתנות אור באלף</b>: בראשית ג, כא. ראה ב\"ר שם. ע\"ח שער החשמל שם. לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה כנשר יעיר קנו על יד הערה 143 ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תצג. וש\"נ. שעה\"י קמ, א ואילך ובהערה 10. לקו\"ש ט\"ו באב כרך כד ע' 58 בשולי היריעה."],["4973","62","<b>אי' בכהאריז\"ל</b>: ראה בהמצויין בהערות שלפנ\"ז."],["4974","63","<b>דהצפרנים. . דין דקדושה</b>: ראה מק\"מ שם."],["4975","64","<b>מצוה לקוץ הצפרנים בע\"ש</b>: ראה שו\"ע או\"ח הל' שבת סר\"ס, ס\"א ושם: מצוה. שו\"ע אדה\"ז שם ס\"ב<sup data-n=\"e275\">ט</sup>. פע\"ח שער השבת שי\"ח, פ\"ג. שער הכוונות ענין רחיצת פניו ידיו ורגליו. של\"ה מס' שבת קלח, א. נגיד ומצוה ח\"ב כוונות המקוה ד\"ה קציצת הצפרנים (ע' קטז ואילך). אור צדיקים הל' שבת סכ\"ח, ס\"ב. משנת חסידים מסכת יום הששי פ\"ה, מ\"ו. סידור ר\"ש ראשקוב כוונת הלכות שבת. קול יעקב כוונת שבתי. מק\"מ שם. סה\"מ תרל\"ב ח\"א ס\"ע קנא.\n\n<b>ג</b>  ראה גם אדם ישר דרוש מרכבת יחזקאל פ\"ד (מ, א ואילך). נעתק לשונו בע\"ח שער ק\"נ שמ\"ט, פ\"ד.\n\n<b>ד</b>  והוא העתק ע\"ח שער החשמל שבפנים ההערה.\n\n<b>ה</b>  בנוסף להערה שלפנ\"ז.\n\n<b>ו</b>  ברש\"י שם בשם התנחומא שהן דבוקין על בשרו של אדם. ראה במפרשים שם.\n\n<b>ז</b>  קודם חטא עה\"ד.\n\n<b>ח</b>  <b>ושם</b>: מדובקין על עורן. ראה מפרשי רש\"י בראשית ג, א.\n\n<b>ט</b>  <b>ושם</b>: או בעיו\"ט (ממג\"א שם בשם מגיד משרים משלי כג, ו)."]]],[2000470516,"הוא נוגה<sup data-n=\"4976\">65</sup> לכן הוא מבריק והצפרנים שחוץ לבשר הם קליפות ויונקים מקדושה ע\"י אמצעות ק\"נ, לכן האסור גדול כ\"כ לגדל הצפרנים<sup data-n=\"4977\">66</sup> מפני שממשיך מקדושה לסט\"א, והזמן הוא בע\"ש מפני דאז כל דינין מתעברין מיני'<sup data-n=\"4978\">67</sup> וכ\"א מישראל הוא קומה שלמה<sup data-n=\"4979\">68</sup> לכן צריך לקוץ את הצפרנים.\n<b>ולהבין</b> זה ע\"ד העבודה הנה ארז\"ל ת\"ח צ\"ל<sup data-n=\"4980\">70</sup> שמינית שבשמינית<sup data-n=\"4981\">69</sup> מגה\"ר דכתי' כלו ס\"ג יחדיו נאלחו<sup data-n=\"4982\">71</sup>, סג הוא גס<sup data-n=\"4983\">72</sup> וצ\"ל חלק א' מס\"ד, והו\"ע ויגבה לבו בדרכי ה'<sup data-n=\"4984\">73</sup>, דאפי' מי שהוא עובד ה' באמת לאמתו ובטל לאלקות מ\"מ מה שחושב דכשעובד ה' הוא עושה נח\"ר ליוצרו ולהיפך כשאינו עובד כו' (בפ\"א וכאלו פורע חובו), ה\"ז גסות, אך לא סגי בלא\"ה דצריך להיות קצת גסות זה אינו לפי כבודו ועי\"ז לא יפול ברע ח\"ו, אך דוקא ס\"ד ולא ס\"ג דהוא ג\"ס אף דס\"ד הוא רק חלק א' פחות מס\"ג אך העיקר דלא גס דהיינו ס\"ג, ומעטרא לי' כסאסאה לשבולתא, סאסאה פי' בערוך<sup data-n=\"4985\">74</sup> שהוא חוט דקין שלמעלה מהשבולת ויש בהם שינים דקים מאד, והיינו שבתחלת עבודה צ\"ל חלק שמינית כו' (ובפ\"א אך אח\"כ כשהוא בטל באמת א\"צ לזה כלל), וכמו\"כ ענין הציפורן הוא שלא יומשך למקום שאינו ראוי, ועוי\"ל ענין הצפורן דהנה יש ב' בחי' חשמל א' המבדיל בין קדש לחול וכמ\"ש והבדילה הפרוכת לכם בין קדש לקדה\"ק<sup data-n=\"4986\">75</sup> והוא כמו משל לשכל עמוק שהוא מסתיר על השכל והוא סיבת הגילוי דמבלעדו לא יובן השכל<sup data-n=\"4987\">76</sup> מפני עומקו, הב' ההבדלה",[["4976","65","<b>נוגה</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן פמ\"ד בהקיצור על יד הערה 1386."],["4977","66","<b>האסור. . לגדל הצפרנים</b>: ראה זהר שם. פרע\"ח שער הברכות ש\"ב, פ\"ה. אור צדיקים שם. משנת חסידים שם. סידור ר\"ש ראשקוב וקול יעקב שם. מק\"מ שם. ע\"ח שער פרצופי זו\"ן של\"א, פ\"ב. נגיד ומצוה שם."],["4978","67","<b>דכל דינין מתעברין מיני'</b>: זהר תרומה קלה, ב."],["4979","68","<b>וכ\"א מישראל הוא קומה שלימה</b>: ראה זהר בראשית לד, ב ובלקוטי לוי יצחק שם. לקו\"ת נשא כו, ב. מאמרי אדה\"ז תקס\"ו ע' רכח ואילך. תקס\"ה ח\"ב ע' תתתקלה ואילך. סה\"מ תרל\"ח ע' שב ואילך ובהנסמן שם. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה על יד הערה 28."],["4980","70","<b>צ\"ל</b>: אוצ\"ל: צ\"ל בו."],["4981","69","<b>ת\"ח. . שמינית שבשמינית</b>: ראה סוטה ה, א. (לעיל בחלק המאמרים) המשך מצה זו כאן פמ\"ד הערה 1376."],["4982","71","<b>כלו ס\"ג יחדיו נאלחו</b>: תהלים נג, ד."],["4983","72","<b>סג הוא גס</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקסו. וש\"נ. תו\"ח בשלח ח\"א קסא, ג. וש\"נ. סה\"מ תרל\"ח ע' קלה. לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם עברו ברית על יד הערה 68. (לעיל בחלק המאמרים) המשך מצה זו כאן פמ\"ד על יד הערה 1381. לקמן ח\"ב (בחלק המאמרים) המשך יונתי ס\"כ שוה\"ג ד."],["4984","73","<b>ויגבה לבו בדרכי ה'</b>: דהי\"ב יז, ו. ראה גם כש\"ט קה\"ת סשצ\"ג (נז, א ואילך)."],["4985","74","<b>סאסאה פי' בערוך</b>: בערך ססא — נעתק בשינויים קלים (לעיל בחלק המאמרים) המשך מצה זו כאן פמ\"ד על יד הערה 1377."],["4986","75","<b>והבדילה. . לקדה\"ק</b>: תרומה כו, לג [ושם: הקדש ובין קדש הקדשים]."],["4987","76","<b>משל. . דמבלעדו לא יובן השכל</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו רפי\"א."]]],[2000470517,"בין קדש לחול<sup data-n=\"4988\">77</sup>, קדש הוא חכ' שהוא קדש מילי' בגרמי'<sup data-n=\"4989\">78</sup> וכן עצם הבינה הוא קדש דהשבירה הי' רק בז\"ת דבינה אבל בג\"ר לא הי' שום שבירה, וחול הוא בי\"ע (וההבדלה הוא שלא יומשך) וזהו בד\"כ מל\"ת, וזהו הצפרנים כדי שלא יומשך אלא למקום הראוי. ועוד יש בדין הצפרנים דמה שנמשך להם וכמ\"ש ואתה מחי' את כולם<sup data-n=\"4990\">79</sup> יומשך להם בצמצום, דמצד החסד אינו שייך כו' רק מצד בחי' השוה ומשוה קטן וגדול<sup data-n=\"4991\">80</sup>, וזהו הצפרנים שיקבלו ע\"י גבורות וצמצומים. וזהו\"ע נט\"י שלא יהי' יניקת החיצונים, הצפרנים שחוץ לבשר צריכים לגזוז ומכ\"ש הצואה שתחת הצפורן שהוא חוצץ<sup data-n=\"4992\">81</sup> לגמרי. וזהו ערבים עלי דברי דודיך יותר מיינה ש\"ת דחכמים כשראו סוכת דוד הנופלת<sup data-n=\"4993\">82</sup> תקנו נט\"י כדי שלא יהי' יניקת החיצונים וזהו ערבים עלי ד\"ס כו' דמל\"ת הם לא דהיינו שב ואל תעשה לבד אבל מצות דרבנן כמו נט\"י הם קום ועשה ופועלים לדחות הרע לכן ערבים עלי דברי דודיך יותר מיינה של תורה.",[["4988","77","<b>ההבדלה בין קדש לחול</b>: ראה תו\"א לך יג, א."],["4989","78","<b>קדש. . חכ'. . קדש מילי' בגרמי'</b>: ראה זהר אמור צד, ב. לקו\"ת מסעי צג, א. מאמרי אדה\"א דברים ח\"ג ע' תתקב."],["4990","79","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["4991","80","<b>השוה ומשוה קטן וגדול</b>: חרוז בפיוט לימים נוראים ”האוחז ביד מדת משפט\" (וכל מאמינים)."],["4992","81","<b>הצואה שתחת הצפורן שהוא חוצץ</b>: ראה שו\"ע אדה\"ז חאו\"ח דיני חציצה וטבילה סקס\"א, ס\"א. ס\"ג."],["4993","82","<b>סוכת דוד הנופלת</b>: עמוס ט, יא. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א (כאן) ע' נו ובהנסמן במ\"מ לשם."]]],[2000470518,"<h3>ואלא עלמא אמאי קאים</h3>\n<b>ש\"פ מטו\"מ תר\"ם לפ\"ק </b>\n(סוטה דמט\"א)\nואלא עלמא אמאי קאים<sup data-n=\"4994\">1</sup> אקדושה דבי סידרא ואיהא שמיא רבא דאגדתא<sup data-n=\"4995\">2</sup>. ולכאו' צ\"ל החקירה אמאי קאים עלמא והלא כתי' לעולם דברך ה' נצב בשמים<sup data-n=\"4996\">3</sup> ואי' במדרשים<sup data-n=\"4997\">4</sup> ורבינו ז\"ל בשם הבעש\"ט ז\"ל<sup data-n=\"4998\">5</sup> דדבר ה' עומד תמיד בשמים לחי' ולהווה אותו ואם הי' נסתלק כרגע הי' נעשה אין ואפס ממש וכמ\"ש ובטובו מחדש בכ\"י תמיד מע\"ב<sup data-n=\"4999\">6</sup>, ול\"ד בכ\"י דבכ\"ע ובכ\"ר נמשך חיות חדש לחדש",[["4994","1","<b>ואלא עלמא אמאי קאים</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב (רק חלק) ממאמר הי\"ט מהמשך מצה זו (פנ\"ט — פס\"א) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: ועד\"ז יובן ג\"כ בנ\"ח]."],["4995","2","<b>ואלא עלמא. . דאגדתא</b>: סוטה מט, א (כמצויין בריש ההנחה — בשינוי לשון קצת)."],["4996","3","<b>לעולם דברך ה' נצב בשמים</b>: תהלים קיט, פט [ושם: ה' דברך]."],["4997","4","<b>ואי' במדרשים</b>: ראה שמו\"ר רפל\"ח. מדרש תהלים קיט, לו. סה\"מ תרל\"ח ע' כב. וש\"נ."],["4998","5","<b>ורבינו ז\"ל בשם הבעש\"ט ז\"ל</b>: שער היחוד והאמונה פ\"א. ראה גם לעיל (בחלק המאמרים) המשך מצה זו פנ\"ב ובהערה 1546."],["4999","6","<b>וכמ\"ש ובטובו מחדש בכ\"י תמיד מע\"ב</b>: ברכת יוצר. ראה גם לעיל (בחלק המאמרים) מאמר ד\"ה להבין ענין ר\"ח ובהערה 43."]]],[2000470519,"הישנות ומ\"ש<sup data-n=\"5000\">7</sup> ואתה מחי' את כולם<sup data-n=\"5001\">8</sup> א\"ת מחי' אלא מהווה<sup data-n=\"5002\">9</sup>, וא\"כ מהו החקירה אמאי קאים כו' דמציאות הוא קאים על האין המהווה אותו, וגם מ\"ש איהא שמיא רבא דאגדתא צ\"ל מפני מה מכל הדברים לא בחרו רק יהא כו'.\n<b>והענין</b> דהנה כתי' אם לא בריתי<sup data-n=\"5003\">10</sup> יומם ולילה חוקת שמו\"א לא שמתי, בריתי יומם ולילה הוא תורה, דעיקר מצותה כמ\"ש והגית בה יומם ולילה<sup data-n=\"5004\">11</sup>, רק בעלי עסקים מקילין<sup data-n=\"5005\">12</sup> פ\"א שחרית ופ\"א ערבית אבל עיקר מצותה יום ולילה לכן נק' בריתי יומם ולילה, ואם לא כו' חוקת שו\"א לא שמתי וכמארז\"ל תנאי התנה הקב\"ה<sup data-n=\"5006\">13</sup> במע\"ב אם יקיימו ישראל את תורתי מוטב וא\"ל יחזיר את העולם לתוהו ובוהו, הרי עיקר הבריאה הי' על תנאי אם יקיימו את התורה וכן אמרז\"ל עשרה עשרה הכף<sup data-n=\"5007\">14</sup> כו', עה\"ד מכוון כנגד ע\"מ<sup data-n=\"5008\">15</sup> ר\"ל דקיום ע\"מ וכל הנבראים שנבראו הוא ע\"י התורה, וארז\"ל אלה תולדות השמים והארץ בהבראם<sup data-n=\"5009\">16</sup> אלה בזכות מי נבראו ובזכות מי עומדים בזכות אלה שמות בנ\"י<sup data-n=\"5010\">17</sup> כו' בזכות אלה העדות והחוקים והמשפטים<sup data-n=\"5011\">18</sup>, ומקרא מלא דבר הכתוב אנכי עשיתי ארץ<sup data-n=\"5012\">19</sup> ואדם עלי' בראתי וצ\"ל אומרו אנכ\"י עשיתי כו' והלא במע\"ב נא' רק אלקים, אך אומרו אנכי כו' ר\"ל מה שנשפל מאנכי מי שאנכי<sup data-n=\"5013\">20</sup> בשם אלקים שיהי' הארץ הוא בשביל האדם וע\"ד שארז\"ל כל העולם כולו לא נברא אלא לצוות לזה<sup data-n=\"5014\">21</sup> דע\"פ פשוט מבלעדם א\"א להיות מציאות האדם,",[["5000","7","<b>ומ\"ש</b>: אוצ\"ל: וכמ\"ש."],["5001","8","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["5002","9","<b>א\"ת מחי' אלא מהווה</b>: ראה שער היחוה\"א פ\"ב ובמ\"מ, הגהות והע\"ק שם. הערה בסה\"מ תש\"ד ע' 20."],["5003","10","<b>אם לא בריתי</b>: ירמי' לג, כה. ראה שבת לג, א."],["5004","11","<b>והגית בה יומם ולילה</b>: יהושע א, ח<sup data-n=\"e276\">א</sup>. ראה הל' ת\"ת לאדה\"ז פ\"ג, ה\"ה."],["5005","12","<b>בעלי עסקים מקילין</b>: ראה הל' ת\"ת שם ה\"ד."],["5006","13","<b>תנאי התנה הקב\"ה</b>: כ\"ה בכ\"מ ומהם: מאמרי אדה\"א בראשית ע' קמ. וש\"נ. תו\"ח בראשית ב, ד הערה 37. סה\"מ מלוקט ד' ע' שכו — ראה שבת פח, א."],["5007","14","<b>עשרה עשרה הכף</b>: נשא ז, פו."],["5008","15","<b>עה\"ד מכוון כנגד ע\"מ</b>: ראה זהר יתרו צג, ב. ויקרא יא, ב. לקו\"ת חוקת נז, סע\"ג ואילך בשם המגיד. מאמרי אדה\"א דברים ח\"א ע' רפ. וש\"נ. תו\"ח וארא ח\"א פא, ג ובהערה 636. סה\"מ תרל\"ח ע' ע. וש\"נ. סה\"מ מלוקט ד' ע' פ ואילך."],["5009","16","<b>אלה תולדות השמים והארץ בהבראם</b>: בראשית ב, ד. ראה שמו\"ר פמ\"ח, [ב]. לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 1683."],["5010","17","<b>אלה שמות בנ\"י</b>: שמות א, א [ושם: ואלה — אבל כ\"ה גם בשמו\"ר שם. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ח. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' על יד הערה 27]."],["5011","18","<b>אלה העדות והחוקים והמשפטים</b>: ואתחנן ד, מה."],["5012","19","<b>אנכי עשיתי ארץ</b>: ישעי' מה, יב."],["5013","20","<b>מאנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."],["5014","21","<b>כל העולם. . לצוות לזה</b>: ראה ברכות ו, ב.\n\n<b>א</b>  <b>ושם</b>: בו — ראה גם מאמרי אדה\"ז תקס\"ז ע' שמח. תו\"ח מקץ רכז, א ובהערה 18. סה\"מ תרל\"ח ע' שלה. וש\"נ."]]],[2000470520,"ואדם בראתי בגימ' תרי\"ג<sup data-n=\"5015\">22</sup> שמקיים תרי\"ג מצותי' של תורה<sup data-n=\"5016\">23</sup> וגם מצות לימוד התורה עצמה שהיא ג\"כ מצוה<sup data-n=\"5017\">24</sup> בתרי\"ג מצות.\n<b>והנה</b> עפ\"ז יובן משארז\"ל ערבים עלי דברי דודיך יותר מיינה ש\"ת<sup data-n=\"5018\">25</sup> ונת\"ל דמצות דרבנן<sup data-n=\"5019\">26</sup> הם למעלה ממצות דאורייתא וזהו בינה יתירה ניתנה באשה<sup data-n=\"5020\">27</sup> יותר מבאיש דהנה כשרצו להשכיחם תורתך<sup data-n=\"5021\">28</sup> כו' תקנו שידליקו נרות דחנוכה וצ\"ל מה שייך זה לזה, והנה נר חנוכה הוא להאיר מקום החשך כפול ומכופל ג\"כ, ולא לדחות את החשך לבד וכמו כשמכניסים נר בבית אפל שנדחה החשך, דהנה נ\"ח היא מ\"ע בקום ועשה ואינו שייך לדחות רק להאיר את החשך שיהי' אתהפכא חשוכא לנהורא<sup data-n=\"5022\">30</sup>, לכן בפרטי דינים דנ\"ח שהם היסודות ארז\"ל מצותה משתשקע החמה<sup data-n=\"5023\">29</sup> וצ\"ל למה משתשקע החמה דוקא, והענין דהנה כתי' שמש ומגן הוי' אלקים<sup data-n=\"5024\">31</sup> דשם הוי' נמשל לשמש וכשישראל הי' על עמדם והאיר בהם בחי' שמש הוי' לא הי' צריכים לנ\"ח, אך משתשקע החמה שאינו מאיר בחי' שמש ה' אז תקנו נ\"ח ומצוה מן המובחר הוא בשמן זית<sup data-n=\"5025\">32</sup> דשמן הוא חכ'<sup data-n=\"5026\">33</sup> ור\"ל שפועל שיאיר אור התו' למטה דעיקר האור הוא מהשמש<sup data-n=\"5027\">34</sup> דהפתילה הוא רק כמו צבת שדרך בו עובר השמן ושיהי' להאור דבר הנאחז אבל העיקר האור הוא מהשמן וזהו שהוא מאיר אור החכ' למטה (וענין שמן זי\"ת דוקא אפ\"ל ע\"ד משנ\"ת במ\"א בענין נרות דמנורה שצ\"ל שמן זית<sup data-n=\"5028\">35</sup>, דהנה ארז\"ל מה הזית<sup data-n=\"5029\">36</sup> משכח תלמודו של ע' שנה כך שמן זית מחזיר תלמודו של ע' שנה, שכחה הוא מצד הק\"נ<sup data-n=\"5030\">37</sup>, והנה בכ\"ד יש הבלא דגרמי<sup data-n=\"5031\">38</sup>",[["5015","22","<b>בראתי בגימ' תרי\"ג</b>: ראה רמ\"ז לזהר ויגש רה, ב (קז, ב בדפי הספר). לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 1688."],["5016","23","<b>תרי\"ג מצותי' של תורה</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["5017","24","<b>מצות לימוד התורה. . מצוה</b>: ראה סהמ\"צ להרמב\"ם מ\"ע יא."],["5018","25","<b>ערבים עלי. . מיינה ש\"ת</b>: ע\"ז לה, א וברש\"י שם."],["5019","26","<b>ונת\"ל דמצות דרבנן</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו פל\"ז ואילך."],["5020","27","<b>בינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["5021","28","<b>להשכיחם תורתיך</b>: נוסח (ועל הנסים) בימי מתתיהו."],["5022","30","<b>אתהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרכ\"ט ע' פח ואילך. וש\"נ. מאמר ד\"ה זאת חוקת התורה ש\"פ פרה תשכ\"ו."],["5023","29","<b>תקנו שידליקו נרות דחנוכה. . מצותה משתשקע החמה</b>: ראה שבת כא, ב. לקמן הנחה ד\"ה ר' אבהו פתח והמה כאדם על יד הערה 151 ואילך."],["5024","31","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["5025","32","<b>ומצוה מן המובחר הוא בשמן זית</b>: ראה שבת כג, א ובתוד\"ה מריש. רמ\"א הל' חנוכה רסתרע\"ג. שו\"ע אדה\"ז הל' שבת סרס\"ד, סי\"ב."],["5026","33","<b>דשמן הוא חכ'</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט ובהערה 159."],["5027","34","<b>מהשמש</b>: אוצ\"ל: מהשמן."],["5028","35","<b>נרות דמנורה שצ\"ל שמן זית</b>: ר\"פ תצוה. אמור כד, ב. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פי\"ג. תו\"א תצוה פא, ג."],["5029","36","<b>מה הזית</b>: ראה הוריות יג, ב."],["5030","37","<b>שכחה הוא מצד הק\"נ</b>: ראה אוה\"ת וישלח ח\"ב ע' רמז."],["5031","38","<b>הבלא דגרמי</b>: ראה זהר שלח קסט, א. קע, א. הנסמן לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 249."]]],[2000470521,"וזהו השמן שיש בכ\"ד<sup data-n=\"5032\">39</sup> והוא החכ', לכן כשטמאו כל השמנים<sup data-n=\"5033\">40</sup> והוא מצד הקליפה בלימוד חכ' חיצוניות<sup data-n=\"5034\">41</sup> וכשית\"ל לכן תקנו נ\"ח משמן זית שיאיר בחי' החכ' כנ\"ל, וע' בת\"א בד\"ה ת\"ר מצות נ\"ח<sup data-n=\"5035\">42</sup>, ובלקו\"ת בד\"ה בהעלותך הא'<sup data-n=\"5036\">43</sup> ), והנה היוונים טמאו כל השמנים שהי' בהיכל והיינו ע\"י לימוד חכמות חיצוניות שהוא גרוע מדברים בטלים שהוא מטמא הדבור ומח' והמדה המלובש בה אבל ע\"י חכ' חיצוניות מטמאה חב\"ד שבנפשו<sup data-n=\"5037\">44</sup> אם לא שעושה אותם קרדום לחתוך בו או שמתוכם עובד ה' וכמו הרמב\"ם והרמב\"ן אבל אם אינו יכול כמוהם ה\"ה מטמא חב\"ד שבנפשו עי\"ז, וזהו ע\"ד שארז\"ל חמרא אפי' בתקופת תמוז קרירא לי'<sup data-n=\"5038\">45</sup>, פי' אפי' בתקופות תמוז שאז תוקף החום<sup data-n=\"5039\">46</sup> והיינו אפי' כשיתבונן איך דאני ה' לא שניתי<sup data-n=\"5040\">47</sup> בין קודם הבריאה לאחר הבריאה, אתה הוא קודם שנברה\"ע<sup data-n=\"5041\">48</sup> ואתה הוא לאחר שנברה\"ע, ומ\"מ אינו מתפעל כלל וזהו טמאו כל השמנים (הו\"ע טמטום המוח והלב<sup data-n=\"5042\">49</sup> ) וזהו משתשקע השמש הוא שמש הוי' (דאפי' התבוננות דאני הוי' לא שניתי אינו מועיל כלל) לכן כשגברה מלכות בית חשמונאי ונצחום<sup data-n=\"5043\">50</sup> תקנו להדליק נ\"ח שיאיר גם במקום החשך, וזהו שארז\"ל מצותה להניחה על פתח הבית מבחוץ<sup data-n=\"5044\">51</sup> פי' אפי' רה\"ר טורא דפרודא<sup data-n=\"5045\">52</sup>",[["5032","39","<b>השמן שיש בכ\"ד</b>: ראה גם תו\"א מקץ מ, ד. הנסמן לעיל (בחלק המאמרים) שם הערות 264 ואילך."],["5033","40","<b>כשטמאו כל השמנים</b>: שבת כא, ב."],["5034","41","<b>כשטמאו כל השמנים. . הקליפה בלימוד חכ' חיצוניות</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ט ובהערה 158."],["5035","42","<b>בת\"א בד\"ה ת\"ר מצות נ\"ח</b>: מקץ לד, א."],["5036","43","<b>ובלקו\"ת בד\"ה בהעלותך הא'</b>: ל, סע\"ב ואילך."],["5037","44","<b>חכמות חיצוניות. . מטמאה חב\"ד שבנפשו</b>: ראה תניא ספ\"ח. וראה מ\"מ הגהות והע\"ק שם."],["5038","45","<b>חמרא אפי' בתקופת תמוז קרירא לי'</b>: שבת נג, א. ראה אוה\"ת שמע\"צ ע' א'תתטז. מאמר ד\"ה ביום השמע\"צ תרל\"ב<sup data-n=\"e277\">ב</sup> ע' 21. סה\"מ תרל\"ב ס\"ע לו. ע' קכד. ע' קצז ואילך. ע' רסב. המשך מים רבים תרל\"ו פקי\"ט ע' קכו. ח\"ב ע' שע. וככה תרל\"ז פס\"ג ע' צט. המשך תער\"ב ח\"א ע' שסח ואילך. סה\"מ תרפ\"ט ע' 158. לקו\"ש תמוז כרך יח ע' 462 ואילך<sup data-n=\"e278\">ג</sup>. וראה גם לקו\"ת שמ\"ע פז, ג. אוה\"ת וישלח כרך ה ס\"ע 1762 ואילך. ויחי כרך ו ע' תתשכב."],["5039","46","<b>בתקופות תמוז שאז תוקף החום</b>: ראה גם לקו\"ש יב-יג תמוז כרך יח ע' 310 ואילך."],["5040","47","<b>דאני ה' לא שניתי</b>: מלאכי ג, ו. ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ג על יד הערה 44."],["5041","48","<b>אתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["5042","49","<b>טמטום המוח והלב</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פט\"ו הערה 343."],["5043","50","<b>כשגברה מלכות בית חשמונאי ונצחום</b>: שבת כא, ב."],["5044","51","<b>מצותה להניחה על פתח הבית מבחוץ</b>: שבת שם."],["5045","52","<b>רה\"ר טורא דפרודא</b>: ראה תניא ספל\"ג ובמ\"מ הגהות והערות קצרות לשם. מאמרי אדה\"א שמות ח\"א ע' רצו דברים ח\"ב ע' תעט ובהנסמן בהנ\"ל.\n\n<b>ב</b>  נדפס בקונ' בפ\"ע קה\"ת תש\"נ. סה\"מ תרל\"א (נמצא בדפוס).\n\n<b>ג</b>  נדפס גם בשיחות קודש שנת השי\"ת (תשנ\"ח) ע' 88 ואילך."]]],[2000470522,"דרה\"י עולה עד לרקיע<sup data-n=\"5046\">53</sup>, אפי' ברה\"ר שהכל בוקעין בו יאיר ג\"כ אור החכ', ועוד ארז\"ל מזוזה מימין ונ\"ח משמאל<sup data-n=\"5047\">54</sup> דבקו השמאל שם יש יניקת החיצונים<sup data-n=\"5048\">55</sup> דממותרי הגבורות יונקים יותר מבמותרי החסדים וזהו\"ע נ\"ח שיהי' מאיר בקו השמאל.\n<b>והנה</b> להבין שרש ענין דנ\"ח צ\"ל תחלה ענין התורה ויובן איך שערבים עלי דברי דודיך כו'<sup data-n=\"5049\">56</sup>.",[["5046","53","<b>דרה\"י עולה עד לרקיע</b>: שבת ז, סע\"א. שו\"ע אדה\"ז הל' שבת סשמ\"ה, סי\"ח."],["5047","54","<b>מזוזה מימין ונ\"ח משמאל</b>: שבת כב, א. ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 1676."],["5048","55","<b>דבקו השמאל שם יש יניקת החיצונים</b>: ראה סה\"מ תר\"ן ע' שצ."],["5049","56","<b>כו'</b>: ע\"כ נרשם בגוכתי\"ק. ראה המשך הענין לעיל (בחלק המאמרים) בההמשך כאן."]]],[2000470523,"<h3>ר' אבהו פתח והמה כאדם</h3>\n<b>ש\"פ דברים תר\"ם לפ\"ק </b>\n(פתיחתא דאיכה ובמד\"ר בראשית פי\"ט בשינוי קצת)\nר' אבהו<sup data-n=\"5050\">1</sup> פתח<sup data-n=\"5051\">2</sup> והמה כאדם עברו ברית<sup data-n=\"5052\">3</sup> זה אדה\"ר א' הקב\"ה אדה\"ר הכנסתיו לג\"ע כמ\"ש ויניחהו בג\"ע לעבדו ולשמרו<sup data-n=\"5053\">4</sup>, וצויתיו ויצו כו' מכל עץ הגן<sup data-n=\"5054\">5</sup> אכל תאכל ומעה\"ד טו\"ר לא תאכל<sup data-n=\"5055\">6</sup>, ועבר על ציוויי כמ\"ש המן עץ אשר צויתיך<sup data-n=\"5056\">7</sup> לבלתי אכל ממנו אכלת, ודנתיו בגירושין ויגרש את האדם<sup data-n=\"5057\">8</sup> ובשילוחין וישלחהו משם<sup data-n=\"5058\">9</sup> וקוננתי עליו איכה, אי כה<sup data-n=\"5059\">10</sup> איכה כתי' (דהי' יכול לכתוב בך' קמוצה (ר\"ל בקמ\"ץ<sup data-n=\"5060\">11</sup> ) ונא' בך' ה' ה\"ז איכה) כך בני הכנסתים לארץ כמ\"ש ואביא אותם אל ארץ הכרמל<sup data-n=\"5061\">12</sup>, וצויתים צו את בנ\"י<sup data-n=\"5062\">13</sup>, ועברו על ציווי וכל ישראל עברו בריתי (במ\"א אי' עזבו בריתי<sup data-n=\"5063\">14</sup> ) ודנתי בגירושין מביתי אגרשם<sup data-n=\"5064\">15</sup>, ובשילוחין שלח",[["5050","1","<b>ר' אבהו פתח והמה כאדם</b>: הנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר הכ' מהמשך מצה זו (פס\"ב — פס\"ד) שנדפס לעיל בחלק המאמרים [ושם הפתיחה: וביאור ענין משתשקע החמה]."],["5051","2","<b>ר' אבהו פתח</b>: פתיחתא דאיכ\"ר ס\"ד — בשינויים. ב\"ר פי\"ט, ט — כמצויין בריש המאמר."],["5052","3","<b>והמה כאדם עברו ברית</b>: הושע ו, ז."],["5053","4","<b>ויניחהו בג\"ע לעבדו ולשמרו</b>: בראשית ב, טו [ושם: לעבדה ולשמרה]."],["5054","5","<b>ויצו כו' מכל עץ הגן</b>: בראשית ב, טז."],["5055","6","<b>ומעץ הדעת טו\"ר לא תאכל</b>: שם ב, יז."],["5056","7","<b>המן עץ אשר צויתיך</b>: בראשית ג, יא [ושם: העץ]."],["5057","8","<b>ויגרש את האדם</b>: שם ג, כד."],["5058","9","<b>וישלחהו משם</b>: בראשית שם, כג [ושם: וישלחהו ה\"א מג\"ע לעבוד את האדמה אשר לוקח משם]."],["5059","10","<b>איכה</b>: שם ג, ח."],["5060","11","<b>בך'. . בקמ\"ץ</b>: מתנות כהונה לאיכ\"ר שם."],["5061","12","<b>ואביא אותם אל ארץ הכרמל</b>: ירמי' ב, ז [ושם: אתכם]."],["5062","13","<b>צו את בנ\"י</b>: באיכ\"ר כאן צויין ויקרא כד, ב. בב\"ר שם (פי\"ט, ט) מביא הכתוב: ואתה תצוה את בנ\"י — תצוה כו, כ."],["5063","14","<b>וכל ישראל עברו בריתי. . עזבו בריתי</b>: באיכ\"ר כאן: וכל ישראל עברו את תורתיך — דניאל ט, יא."],["5064","15","<b>מביתי אגרשם</b>: הושע ט, טו."]]],[2000470524,"מעל פני ויצאו<sup data-n=\"5065\">16</sup>, וקוננתי עליהם איכה ישבה בדד<sup data-n=\"5066\">17</sup>, (ה' ע' זח\"א ךטא ואפשר לכוונו עם המדר' הנ\"ל ע')<sup data-n=\"5067\">18</sup>, וצ\"ל מה שייך חורבן בהמק\"ד לחטא עה\"ד (ה' ע' בזח\"א דךוא וגלי לון קוב\"ה דביום אכלו ממנו גרמו דאבדו ב' אבדין דאינון בית ראשון בית שני כו'<sup data-n=\"5068\">19</sup> מות תמות ב\"פ כו' יחרב ויבש בב\"ר ובב\"ש ע\"ש וע' במד\"ר בר' פך\"א<sup data-n=\"5069\">20</sup> ע\"פ ויגרש הראה לו חורבן בהמק\"ד, וע' בזח\"א רלז\"א, ע'), ואם נאמר שזהו בירור על חטא עה\"ד צ\"ל והלא אדה\"ר הי' מקור כלליות הנשמות ואח\"כ כשנוסדה הארץ מג' בני נח הי' גם לבני חם ויפת ליטול חלק כו' ולמה דוקא בני שם ומבני שם ישראל דוקא מחויבים בהשיעבוד.\n<b>והענין</b> דהנה כתי' אל תראוני שאני שחרחורת שזפתני השמש<sup data-n=\"5070\">21</sup> ופי' בזהר (ה' ח\"ג דמה\"א<sup data-n=\"5071\">22</sup> ע') דאסתלק שימשא מלאנהרא בי' ומלאסתכלא בי'<sup data-n=\"5072\">23</sup> ופי' במק\"מ שמש הוא שמש הוי'<sup data-n=\"5073\">24</sup> ז\"א והיינו דז\"א אינו מאיר במל' ועל ל' החסידות הוא קול ודיבור, וא\"כ א\"ז כפי' הפשוט שמפרשים שהשחרות אינו מצד עצמה כ\"א מצד השמש אבל כאן מפרש שהשחרות הוא מפני דאסתלק שימשא כו' וא\"כ צ\"ל אומרו אל תראוני כו', ואפ\"ל ע\"ד שארז\"ל אל תשתדל לראותו בשעת קלקלתו<sup data-n=\"5074\">25</sup>, ועוי\"ל דהשחרות אינו מצ\"ע כ\"א כמ\"ש כי בפשעיכם שולחה אמכם<sup data-n=\"5075\">26</sup> וזהו אל תראוני שאני שחרחורת דזה שזפתני השמש הוא מצד עונות בנ\"י, ועוי\"ל כמארז\"ל גלו לבבל שכינה עמהם<sup data-n=\"5076\">27</sup> וכמ\"ש למענכם שולחתי בבלה<sup data-n=\"5077\">28</sup> והיינו ג\"כ שאינו מצ\"ע, רק לפי תירוץ זה הוא מה שנמשך לאגנאה עלייהו.\n<b>ושרש</b> הענין הוא דהנה ארז\"ל נתאווה הקב\"ה להיות לו דירה בתחתונים<sup data-n=\"5078\">29</sup>, מפני מה נתאווה אין אנו יודעין<sup data-n=\"5079\">30</sup> דמה תופס מקום לגבי' וכן מצינו שארז\"ל מה איכפת לו להקב\"ה<sup data-n=\"5080\">31</sup> אם שוחט מן העורף ואם שוחט מן הצואר, אך מ\"מ זה אנו",[["5065","16","<b>שלח מעל מעל פני ויצאו</b>: ירמי' טו, א."],["5066","17","<b>איכה ישבה בדד</b>: איכה א, א."],["5067","18","<b>(ה'. . ע')</b>: (הגה. . עד כאן)."],["5068","19","<b>כו'</b>: אולי כ\"ה בגוכתי\"ק."],["5069","20","<b>במד\"ר בר' פך\"א</b>: ס\"ח."],["5070","21","<b>אל תראוני. . השמש</b>: שה\"ש א, ו [ושם: ששזפתני — ראה גם לקמן פיסקא וזהו\"ע נר חנוכה. מאמרי אדה\"א נ\"ך ע' רמד]."],["5071","22","<b>דמה\"א</b>: וכ\"ה לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 1765. וכנצ\"ל: ע\"ב."],["5072","23","<b>דאסתלק. . בי'</b>: בזהר: דאסתלק מני שמשא לאנהרא לי ולאסתכלא בי."],["5073","24","<b>שמש הוי'</b>: לא הובא במק\"מ כאן. ראה זהר בראשית כ, א. (לעיל בחלק המאמרים) המשך מצה זו הערה 1166. סה\"מ תרל\"ח ע' צו."],["5074","25","<b>אל תשתדל לראותו בשעת קלקלתו</b>: אבות פ\"ד, מי\"ח."],["5075","26","<b>בפשעיכם שולחה אמכם</b>: ישעי' נ, א."],["5076","27","<b>גלו לבבל שכינה עמהם</b>: מכילתא בא יב, מב. ספרי בהעלותך י, לה. מסעי לה, לד. מגילה כט, א. ראה גם לקו\"ש ב' ניסן כרך ז ע' 210 הערה 29."],["5077","28","<b>למענכם שולחתי בבלה</b>: ישעי' מג, יד."],["5078","29","<b>נתאוה הקב\"ה. . דירה בתחתונים</b>: ראה תניא רפל\"ו. לעיל (בחלק המאמרים) המשך מצה זו הערה 1693."],["5079","30","<b>מפני מה נתאוה אין אנו יודעין</b>: ראה גם (לעיל בחלק המאמרים) המשך מצה זו כאן ובהערה 1776."],["5080","31","<b>מה איכפת לו להקב\"ה</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. לקו\"ש אבות כרך יז ע' 415 הערה 53. שופטים כרך יט ע' 182 הערה 42."]]],[2000470525,"יודעין שנתאווה כו', וכן ארז\"ל ע\"פ שוקיו עמודי שש<sup data-n=\"5081\">32</sup> שוקיו זה עולם שנשתוקק הקב\"ה<sup data-n=\"5082\">33</sup> כו' עמודי שש שנברא בששה ימים, מפני מה אין אנו יודעין אבל זה אנו יודעים שנשתוקק ואמרז\"ל (ה' מד\"ר בראשית פי\"ט) עיקר שכינה בתחתונים היתה<sup data-n=\"5083\">34</sup> וע\"י חטא ז' דורות סלקו השכינה עד למעלה מרקיע הז', והנה אדה\"ר שהי' בחיר שבנבראים וכל העולם לא נברא אלא לצוות לזה<sup data-n=\"5084\">35</sup> וכמארז\"ל דמלאכי' היו צולין לו בשר<sup data-n=\"5085\">36</sup> הרי שגם מלאכים היו (טפלים) לו, הוא התחילה<sup data-n=\"5086\">37</sup> בעבודה תחילה ונא' בו ויניחהו בג\"ע לעבדה ולשמרה וכמו עבודת הגן שצריכין לזמר הקוצים ושארי עובדות כמו\"כ הי' עבודה שלו בג\"ע וזהו לעבדה ולשמרה לעבדה רמ\"ח ולשמרה שס\"ה מל\"ת<sup data-n=\"5087\">38</sup>, רמ\"ח מ\"ע הם המשכות אלקות למטה ושס\"ה מל\"ת הוא שלא יהי' יניקת החיצונים וכמו שמזמרי' את הקוצים, והנה זה מובן דהעבודה בגן הי' באופן יותר מכמו אח\"כ כשגירש אותו, והריחוק הערך הוא כמו שכר לגבי עונש, דעכשיו הג\"ע הוא תשלום שכר דכשמקיימים תומ\"צ התשלום שכר הוא הג\"ע, רק שאינו עצם השכר<sup data-n=\"5088\">39</sup> כ\"א פירותיהן כו' (הגה דשכר מצוה הוא עצם המצוה<sup data-n=\"5089\">40</sup> וזה יתגלה לע\"ל דוקא, ואפ\"ל זהו\"ע זיו תורתן ועבודתן<sup data-n=\"5090\">41</sup> שהוא רק זיו והארה לבד ובחי' זו הוא בג\"ע, ואפ\"ל זהו\"ע מארז\"ל יושבין ונהנים מזיו השכינה<sup data-n=\"5091\">42</sup> שהוא רק זיו לבד וזהו שכ' נהנים הנאה שייך מדבר שמשיג וזהו ג\"ע בינה<sup data-n=\"5092\">43</sup> שהוא השגה והבנה וכידוע ומבואר במ\"א באריכות ומאחר שהוא מושג מוכרח לומר שהוא רק הארה לבד אך על לע\"ל ארז\"ל צדיקים יושבין ועטרותיהן בראשיהם<sup data-n=\"5093\">44</sup>, ומ\"ש במ\"א דעיקר ענ\"ג העליון יהי' לע\"ל<sup data-n=\"5094\">45</sup> דוקא אפ\"ל שהוא עונג שאינו מצד השגה וכמבואר במ\"א דג\"ע הוא ממכ\"ע ולע\"ל יהי' בחי' סוכ\"ע<sup data-n=\"5095\">46</sup> וזהו שארז\"ל יפה שעה אחת<sup data-n=\"5096\">47</sup> בתשובה ומע\"ט",[["5081","32","<b>שוקיו עמודי שש</b>: שה\"ש ה, טו."],["5082","33","<b>שוקיו. . שנשתוקק הקב\"ה</b>: ראה במד\"ר רפ\"י."],["5083","34","<b>מד\"ר. . עיקר שכינה בתחתוני' היתה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 1780."],["5084","35","<b>וכל העולם. . לצוות לזה</b>: ראה ברכות ו, ב."],["5085","36","<b>דמלאכי' היו צולין לו בשר</b>: סנהדרין נט, ב. ראה גם תו\"ח ויקהל ח\"ב תכב, ג הערה 1256."],["5086","37","<b>התחילה</b>: אוצ\"ל: התחיל."],["5087","38","<b>לעבדה רמ\"ח ולשמרה שס\"ה מל\"ת</b>: בראשית ב, טו. ראה זהר בראשית כז, א. תרומה קסה, ב. הנסמן במאמרי אדה\"א דברים ח\"ב ע' שצט בראשית ע' עג קונטרסים ע' שי."],["5088","39","<b>הג\"ע רק שאינו עצם השכר</b>: ראה לקו\"ת בהר מב, א. תו\"א יתרו עג, ב. תניא פל\"ו ובמ\"מ הגהות והערות קצרות לשם."],["5089","40","<b>דשכר מצוה הוא עצם המצוה</b>: אבות פ\"ד, מ\"ב. ראה לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח הערה 230."],["5090","41","<b>זיו תורתן ועבודתן</b>: ראה תניא פל\"ט. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וכל שיח השדה על יד הערה 41."],["5091","42","<b>יושבין ונהנים מזיו השכינה</b>: ראה ברכות יז, א."],["5092","43","<b>ג\"ע בינה</b>: ראה תו\"א יתרו עג, ב. לקו\"ת צו יא, ד. מאמרי אדה\"ז תק\"ע ע' צח."],["5093","44","<b>צדיקים יושבין ועטרותיהן בראשיהם</b>: ברכות יז, א. ראה גם לקו\"ת שלח מז, סע\"ג. מאמרי אדה\"א ויקרא ח\"א ע' קעא."],["5094","45","<b>ענ\"ג העליון יהי' לע\"ל</b>: ראה תו\"א ויצא כא, ג."],["5095","46","<b>דג\"ע הוא ממכ\"ע ולע\"ל. . סוכ\"ע</b>: ראה אגה\"ק סי\"ז. תו\"א יתרו שם."],["5096","47","<b>יפה שעה אחת</b>: אבות פ\"ד, מי\"ז."]]],[2000470526,"בעוה\"ז כו' עכ\"ה), אבל מ\"מ הוא שכר הנשמות רק נשמות בגופים יהי' גילוי גבוה יותר (ה' מצד הסוכ\"ע שמשם שורש הגופים<sup data-n=\"5097\">48</sup> וכמ\"ש במ\"א ע') ומ\"ש ויגרש הוא עונש א\"כ בערך כשכר לגבי עונש.\n<b>והנה</b> אח\"כ בהעונש כתי' וישלחהו לעבוד את האדמה אשר לוקח משם, וצ\"ל מהו אומרו אשר לוקח משם והול\"ל לעבוד את האדמה ותו לא. והענין דלכאור' צ\"ל איך יש בכח נברא לשנות הדיעה העליונה והלא כשבראו ברא אותו בכל הפרטים ואיך שייך שרצונו יעשה היפך הרצה\"ע (ה' אפ\"ל הכוונה דכתי' נעשה אדם בצלמינו כדמותינו<sup data-n=\"5098\">49</sup> וכמו שיש רצון למעלה כמו\"כ נעשה רצון באדם ואיך יעשה ההיפך מרצה\"ע ע'), אך זהו מפני שהאדם הוא בעל בחירה<sup data-n=\"5099\">50</sup> ובזה הוא מחולק מכל הנבראים (אפ\"ל ר\"ל<sup data-n=\"5100\">51</sup> גם בזה כו'), אך אף שהוא בע\"ב מ\"מ אפשר לבחור בטוב וכמ\"ש ראה נתתי לפניך<sup data-n=\"5101\">52</sup> כו' ובחרת בחיים<sup data-n=\"5102\">53</sup> אף שהוא בדרך עצה מ\"מ מי ששכלו ישר צריך לבחור כן ע\"פ השכל, עז\"א אשר לוקח משם, דזה מובן דעיקר העבודה אינו בהאדמה אשר לוקח משם דאל\"כ הול\"ל<sup data-n=\"5103\">54</sup> ליישב אותו בארץ ולמה השיבו בגן הארץ אלא מוכרח לומר דעיקר העבודה הוא בג\"ע, ומה ששלחו לעבוד כו' הוא עונש על החטא, וקאמר אשר לוקח משם מזה יובן סיבת החטא, דהנה הארץ שינתה ציווי' שנצטווה עץ פרי שיהי' טעם העץ והפרי שוים<sup data-n=\"5104\">55</sup> ואח\"כ נא' עץ עושה פרי<sup data-n=\"5105\">56</sup> שאין עץ ופרי' שוים וכמו\"כ האדם עץ הוא הגוף וכמ\"ש כי האדם עץ השדה<sup data-n=\"5106\">57</sup> והנפש נמשל לפרי ואין עץ ופרי שוי' דאף שהנפש היא חלק אלוקה ממעל<sup data-n=\"5107\">58</sup> ויש לו אהבה לאלקות מ\"מ הגוף עושה את שלו, וזהו שא' אשר לוקח משם, וזהו נתינת טעם איך שינה רצה\"ע, הטעם הוא מפני שלוקח מן האדמה והיא שינתה ציווי' לכן האדם שינה ג\"כ, ולמה שינתה הארץ יש ע\"ז טעם אחר והוא שייך לתוהו ותיקון, ובמדה שאדם מודד<sup data-n=\"5108\">59</sup> בה מודדין לו, דמפני שהגבירו<sup data-n=\"5109\">60</sup> העץ על הפרי (ה' אפ\"ל והוא מסיבת שינוי הארץ כנ\"ל ואפ\"ל שזהו הטעם שפגם בעולם כמשית\"ל, ע') בה מודדין לו שיעבוד את האדמה.",[["5097","48","<b>הסוכ\"ע שמשם שורש הגופים</b>: ראה תו\"א מג\"א צ, ב. סע\"ג. צא, ג. צב, ג ואילך. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה סוכה שחמתה מרובה מצלתה ובהערה 25."],["5098","49","<b>נעשה אדם בצלמינו כדמותינו</b>: בראשית א, כו."],["5099","50","<b>שהאדם הוא בעל בחירה</b>: ראה לקו\"ת אמור לח, ב. עט\"ר ע' 84. תו\"ח תולדות קנה, א ואילך. אוה\"ת ר\"ה ע' א'שלה ואילך. סה\"מ תר\"ס ע' י ואילך."],["5100","51","<b>אפ\"ל ר\"ל</b>: תיבת אפ\"ל נכתבה ממעל לתיבת ר\"ל."],["5101","52","<b>ראה נתתי לפניך</b>: נצבים ל, טו."],["5102","53","<b>ובחרת בחיים</b>: שם ל, יט."],["5103","54","<b>הול\"ל</b>: אוצ\"ל: הו\"ל."],["5104","55","<b>עץ פרי. . העץ והפרי שוים</b>: בראשית א, יא וברש\"י."],["5105","56","<b>עץ עושה פרי</b>: שם א, יב [ושם: ועץ]."],["5106","57","<b>כי האדם עץ השדה</b>: פ' שופטים כ, יט."],["5107","58","<b>שהנפש היא חלק אלוקה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. לעיל הנחה ד\"ה ואתה תצוה ובהערה 54."],["5108","59","<b>ובמדה שאדם מודד</b>: סוטה ח, ב במשנה."],["5109","60","<b>שהגבירו</b>: תיבה זו אינה ברורה."]]],[2000470527,"<b>והנה</b> ירידות האור הוא לפ\"ע הבירורים ולכן מצינו ג' דברים (פגמים) א' ששינתה הארץ, ב' ביום רביעי כתי' מארת חסר<sup data-n=\"5110\">61</sup> והוא מ\"ש לכי ומעטי א\"ע מפני שטענה א\"א לב' מלכים<sup data-n=\"5111\">62</sup> להשתמש בכתר א' והוא הרגשות היש, והענין דהנה ארז\"ל הכל הי' מן העפר<sup data-n=\"5112\">63</sup> אפי' גלגל חמה וא\"כ כ\"ש הלבנה ומפני שהארץ שינתה מכמו שנצטווה לכן גם הלבנה טענה א\"א כו' (ה' ע' במא\"א מע' א' סעי' קךו ארץ נק' הנוק' כשיש לה זווג כו' וכפה\"נ אפ\"ל שהוא מל' דאצי' וע' מע' למד סעי' טית לבנה נק' מל' דיצי', ע') דהנה אי' בכהאריז\"ל דהשבירה הי' בז\"ת<sup data-n=\"5113\">64</sup> ובמל' לא הי' שבירה רק ארעא אתבטלית (ספד\"צ פ\"ג)<sup data-n=\"5114\">65</sup> ונשאר בה אורות דתהו והוא משם<sup data-n=\"5115\">67</sup> ס\"ג<sup data-n=\"5116\">66</sup> גס<sup data-n=\"5117\">68</sup> לכן הלבנה שהיא מהארץ הי' בה הרגשות היש וטענה א\"א כו' וא\"ל לכי ומעטי כו' ואח\"כ א' הביאו עלי כפרה<sup data-n=\"5118\">69</sup> על שמעטתי את הירח, עלי הוא על הוי'<sup data-n=\"5119\">70</sup> וכדי שיומשך על הוי' הוא ע\"י לכי ומעטי א\"ע והו\"ע הבירורים, ואח\"כ ביום ו' יום ברוא אדה\"ר חטא<sup data-n=\"5120\">71</sup> בחטא עה\"ד והעונש הי' וישלחהו לעבוד את האדמה כו' והוא הבירור, ומכל הנ\"ל מובן שהעבודה שהי' בג\"ע לגבי עבודה דעכשיו אין ערוך כלל, דאז הי' העבודה להמשיך עונג העליון למטה, ועכשיו צריכים לזכך העולם דע\"י חטאו פגם בהעולם (ה' ואפ\"ל זהו מ\"ש ארורה האדמה בעבורך<sup data-n=\"5121\">72</sup> מפני חטא שלך כו' ע') לכן צריכים לזכך את העולם שיהי' העולם ראוי לקבל גילוי אלקות.\n<b>וזהו</b> שאנו אומרים בנוסח תפלות מוסף ושם נעשה לפניך כמצות רצוניך<sup data-n=\"5122\">73</sup>, משמע דעכשיו אינו כמצות רצוניך, דכל עבודה דעכשיו הוא לזכך את העולם וכמ\"ש את העולם נתן בלבו<sup data-n=\"5123\">74</sup> שהעולם נתון בלבו של אדם דלפ\"ע שמזכך נפשו לפ\"ע זה מברר חלקו בעולם, וא\"ז כמו העבודה שהי' בג\"ע שהמקום הי' מקום",[["5110","61","<b>מארת חסר</b>: בראשית א, יד. רש\"י שם. ירושלמי תענית פ\"ד, ה\"ג. מ\"ס פי\"ז, ה\"ה."],["5111","62","<b>לכי ומעטי. . א\"א לב' מלכים</b>: ראה חולין ס, ב. לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערה 1810."],["5112","63","<b>הכל הי' מן העפר</b>: קהלת ג, כ. ראה ב\"ר פי\"ב, יא. קה\"ר שם. ראה גם תו\"ח בשלח ח\"א קסג, ב. אוה\"ת בלק ע' תתקכא. סה\"מ תרכ\"ז ע' שנז. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הא' על יד הערה 58."],["5113","64","<b>בכהאריז\"ל דהשבירה הי' בז\"ת</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ח. וש\"נ."],["5114","65","<b>ובמל'. . ארעא אתבטלית (ספד\"צ פ\"ג)</b>: אוצ\"ל: רפ\"א. זהר תרומה קעו, ב. ראה לקו\"ת בהר מ, א<sup data-n=\"e279\">א</sup>. מאמרי אדה\"א במדבר ח\"ב ע' תשפו. המשך תער\"ב ח\"א ע' תרב. ע' תרד ואילך. ח\"ב ע' תתפח."],["5115","67","<b>משם ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["5116","66","<b>דתהו. . ס\"ג</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. תו\"ח בראשית ט, א ובהערה 2."],["5117","68","<b>ס\"ג גס</b>: ראה גם לעיל הנחה ד\"ה ערבים עלי דברי דודיך הערה 72."],["5118","69","<b>הביאו עלי כפרה</b>: חולין שם."],["5119","70","<b>הביאו עלי. . על הוי'</b>: ראה גם סה\"מ תרכ\"ט ס\"ע קיט. תרל\"ב ח\"א ע' סה."],["5120","71","<b>ביום ו' יום ברוא אדה\"ר חטא</b>: בראשית א, כו ואילך. ראה סנהדרין לח, ב."],["5121","72","<b>ארורה האדמה בעבורך</b>: בראשית ג, יז."],["5122","73","<b>בנוסח תפלות מוסף ושם נעשה לפניך כמצות רצוניך</b>: ליו\"ט [בדילוג]. ראה לעיל הנחה ד\"ה בן פורת יוסף הב' ובהערה 9."],["5123","74","<b>את העולם נתן בלבו</b>: קהלת ג, יא [ושם: בלבם]. ראה לעיל הנחה ד\"ה מזבח אדמה תעשה לי תעשה לי ובהערה 142.\n\n<b>א</b>  ראה אוה\"ת בהר כרך ב ע' תתצח. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצח."]]],[2000470528,"מוכשר רק שצריכים להמשיך גילוי אלקות (הגה ואדה\"ר ע\"י עבודתו בג\"ע המשיך הרצה\"ע בג\"ע שהי' מקום מוכשר (וצ\"ע כמשנת\"ל דע\"י חטאו פגם בהעולם למה לא הניחו בארץ אשר לוקח משם, ואפשר י\"ל ממשארז\"ל עה\"ד טעם עץ ופריו שוים<sup data-n=\"5124\">75</sup> וצ\"ע ע' בכ\"ה<sup data-n=\"5125\">76</sup> הבי' ממד' דבלא החטא לא הי' תמיד בג\"ע כ\"א בארץ ג\"כ<sup data-n=\"5126\">77</sup> ) (ומה שנת\"ל שהמשיך עונג העליון בג\"ע אפ\"ל שהכל כוונה א' דעונג ורצון א' הם<sup data-n=\"5127\">78</sup> שהרצון הוא מצד העונג שיש לו בדבר ההוא, והעונג הוא מצד הרצון וכמ\"ש במ\"א באריכות דא\"א להיות עונג בלא רצון ורצון בלא עונג לכן כא' נחשבו), אך עתה מפני שנפגם הארץ א\"א להמשיך עונג העליון למטה כ\"א להוסיף אורות באצי' לכן אינו כמצות רצוניך דנתאווה הקב\"ה להיות לו דירה למטה, וכל שממשיכים עתה ע\"י העבודה באצי' כנ\"ל יומשך לע\"ל למטה בעוה\"ז, אז יהי' כמצות רצוניך, עכ\"ה), אך בעוה\"ז המקום אינו ראוי כלל, וכ\"ש משארז\"ל נח\"ר לפני שאמרתי ונעשה רצוני<sup data-n=\"5128\">79</sup> ונת\"ל<sup data-n=\"5129\">80</sup> דלפני הוא בחי' בעל הרצון שאין הארץ כלי מוכשר לגילוי זה, לכן אינו כמצות רצוניך והעיקר יהי' לע\"ל דוקא.\n<b>והנה</b> מעת חטא עה\"ד עד זמן שאנו בו עתה היו כמה שינוים בעבודה דתחילה הי' שני אלפי' תוהו<sup data-n=\"5130\">81</sup>, הגם שאדה\"ר התחיל בבירורים<sup data-n=\"5131\">82</sup> מ\"מ הי' ע\"ד התהו<sup data-n=\"5132\">83</sup>, ואח\"כ ב\"א תורה<sup data-n=\"5133\">84</sup> והעיקר הוא מזמן מ\"ת, אף שהתחלת החשבון הוא ממ\"ח לאברהם<sup data-n=\"5134\">85</sup> מ\"מ הרי ארז\"ל כל המצות שעשו האבות ריחות היו<sup data-n=\"5135\">86</sup> אבל אנו שמן תורק שמך<sup data-n=\"5136\">87</sup> דבר שמוריקין מכלי לכלי<sup data-n=\"5137\">88</sup>, ריח הוא רק הארה בעלמא, ולכן כמה שמריחים אינו כלה כלל, אבל אנו שמן תורק שמך שהוא עצמיות<sup data-n=\"5138\">89</sup> וגם כדבר שמוריקין מכלי",[["5124","75","<b>עה\"ד טעם עץ ופריו שוים</b>: של\"ה תורה שבכתב רסט, ריש ע\"ב."],["5125","76","<b>בכ\"ה</b>: אולי כתוב: בנ\"ה."],["5126","77","<b>הבי' ממד' דבלא החטא לא הי' תמיד בג\"ע כ\"א בארץ</b>: ראה גם ב\"ר פי\"ט, ג. פדר\"א פי\"א. חסד לאברהם מעיין רביעי נהר ז."],["5127","78","<b>דעונג ורצון א' הם</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' מז. מאמרי אדה\"א נ\"ך ע' תפ ואילך. וש\"נ. פיה\"מ סב, ג. פלח הרמון אמור ע' שדמ."],["5128","79","<b>נח\"ר. . ונעשה רצוני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["5129","80","<b>ונת\"ל</b>: ראה לעיל (בחלק המאמרים) המשך מצה זו פ\"ס."],["5130","81","<b>שני אלפי' תוהו</b>: ע\"ז ט, א."],["5131","82","<b>שאדה\"ר התחיל בבירורים</b>: ראה גם<sup data-n=\"e280\">ב</sup> סה\"מ עת\"ר ע' רטז. מאמר ד\"ה צו את בנ\"י תשי\"א. ד\"ה ויקח ה\"א את האדם תשי\"ב. ולהעיר משיחת ליל ב' דחה\"פ תרס\"ט ד\"ה מתחלה — סה\"מ ליקוט ח\"ג ע' קסט."],["5132","83","<b>ע\"ד התהו</b>: ראה גם לקו\"ש ח\"ש כרך ג' ע' 776."],["5133","84","<b>ב\"א תורה</b>: ע\"ז ט, א."],["5134","85","<b>שהתחלת החשבון הוא ממ\"ח לאברהם</b>: בע\"ז שם: נ\"ב. ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אריב\"ל הנהו ך\"ו הודו על יד הערה 20."],["5135","86","<b>כל המצות. . ריחות היו</b>: ראה שהש\"ר שבהערה הבאה."],["5136","87","<b>אנו שמן תורק שמך</b>: שה\"ש א, ג. ראה שהש\"ר פ\"א, ג (א). מאמרי אדה\"א שמות ח\"א ע' רנז ואילך. וש\"נ. סה\"מ תרכ\"ט ע' רכא ואילך. וש\"נ."],["5137","88","<b>דבר שמוריקין מכלי לכלי</b>: ראה גם לקו\"ש בהעלותך כרך ח ע' 76 הערה 11."],["5138","89","<b>ריח. . הארה. . שמן. . שהוא עצמיות</b>: ראה גם לקו\"ת שה\"ש ג, א-ב.\n\n<b>ב</b>  ראה (קודם החטא) ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש ג. שער ק\"נ שמ\"ט, פ\"ג. וראה גם שער דרושי הנקודות ש\"ח, פ\"ו. ועוד."]]],[2000470529,"לכלי שהמהות נמשך ע\"י, ואף לאחר שקיבלו התורה לכאו' אז הי' שלימות וכמ\"ש ותרב חכמת שלמה<sup data-n=\"5139\">90</sup>, בימי שלמה קיימא סיהרא באשלמותא<sup data-n=\"5140\">91</sup> ובבהמק\"ד הי' גילוי אלקות וכמארז\"ל במקדש קורין את השם ככתבו<sup data-n=\"5141\">92</sup>, ושאבתם מים בששון<sup data-n=\"5142\">93</sup> שמשם הי' שואבין רוה\"ק<sup data-n=\"5143\">94</sup>, מ\"מ אינו שלימות עדיין וכמ\"ש על אפי ועל חמתי הי' העיר הזאת מיום הוסדה<sup data-n=\"5144\">95</sup>, ולכאורה צ\"ל והלא ארז\"ל ביום שמחת לבו זו בנין בהמק\"ד<sup data-n=\"5145\">96</sup> ואיך אמר על אפי כו', אך זהו מצד מוחין דגדלות דההנהגה למטה צ\"ל בשמחה, ושיהי' גילוי אלקות, אך הנה גלוי וידוע בד\"ע שהידיעה אינה מכרחת הבחירה<sup data-n=\"5146\">97</sup> שעתידים לחטוא וישפוך חמתו על עצים ואבנים<sup data-n=\"5147\">98</sup> לכן על אפי ועל חמתי כו'. דהנה א\"א לומר ח\"ו דבנין בהמק\"ד וחורבנו הי' במקרה<sup data-n=\"5148\">99</sup>, כ\"א ע\"ד תהו ותיקון* דדין לא אהניא לי' ודין אהניא לי'<sup data-n=\"5149\">100</sup> אינו שייך שמתחלה קסבר שאהני' לי' ואח\"כ ראה שלא אהני' לי', האומר כן הוא מצד הקליפות עמלק<sup data-n=\"5150\">*100</sup> שהוא אשר קרך ומצד הקרירות<sup data-n=\"5151\">101</sup> אפ\"ל שהי' מקרה אבל מי שיעיין בעינא פקיחא א\"א לומר שהוא במקרה ח\"ו כ\"א בונה ע\"מ לסתור וסותר ע\"מ לבנות<sup data-n=\"5152\">102</sup>, וכמו\"כ בבהמק\"ד בונה ע\"מ לסתור ועיקר המכוון הוא שיהי' מ\"ש ושם נעשה לפניך כמצות רצוניך, והנה אף לאחר מ\"ת (ה' קודם שנכנסו לארץ, ולפי המשך הענין הול\"ל קודם ענין בהמק\"ד) לא הי' שלימות עדיין, וכמ\"ש וזאת המצוה אשר צוה ה' לעשות בארץ שמע ישראל<sup data-n=\"5153\">103</sup> כו' וצ\"ל הלא ק\"ש",[["5139","90","<b>ותרב חכמת שלמה</b>: מלכים-א ה, י."],["5140","91","<b>בימי שלמה קיימא סיהרא באשלמותא</b>: ראה זהר ויצא קנ, א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקפט."],["5141","92","<b>במקדש קוראין את השם ככתבו</b>: ראה תמיד פ\"ז, מ\"ב."],["5142","93","<b>ושאבתם מים בששון</b>: ישעי' יב, ג."],["5143","94","<b>שמשם הי' שואבין רוה\"ק</b>: ראה ירושלמי סוכה פ\"ה, ה\"א. לקו\"א להה\"מ סרנ\"ט<sup data-n=\"e281\">ד</sup><sup data-n=\"e282\">ג</sup>. אוה\"ת הושע כרך א ע' תלז. לקו\"ש האזינו וחה\"ס כרך ב ע' 424."],["5144","95","<b>על אפי. . הי'. . מיום הוסדה</b>: ירמי' לב, לא [בשינויים]. ראה לעיל (בחלק המאמרים) המשך מצה זו כאן ובהערות 1803-1804."],["5145","96","<b>ביום שמחת לבו זו בנין בהמ\"ק</b>: שה\"ש ג, יא [ושם: וביום]. ראה תענית כו, ב (במשנה)."],["5146","97","<b>שהידיעה אינה מכרחת הבחירה</b>: ראה תו\"א וירא טו, א. תו\"ח בראשית ל, ד ובהערה 15. תולדות קנד, ב ואילך ובהערה 43."],["5147","98","<b>וישפוך חמתו על עצים ואבנים</b>: איכ\"ר פ\"ד, יד."],["5148","99","<b>א\"א לומר. . הי' במקרה</b>: ראה גם לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 1808 ואילך. תו\"ח תולדות קנד, א ואילך ובהערה 20. סה\"מ מלוקט ה' ע' קנד ואילך ובהנסמן שם."],["5149","100","<b>דדין. . אהניא לי'</b>: ראה ב\"ר פ\"ג, ז. פ\"ט, ב. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 21. לקמן (בחלק ההנחות) הנחה ד\"ה ביום השמיני עצרת על יד הערה 21. סה\"מ ת\"ש ע' 55 בהערה. תרל\"ח ע' תמב. וש\"נ."],["5150","*100","<b>תהו ותיקון. . מצד הקליפת עמלק</b>: ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 90."],["5151","101","<b>אשר קרך. . הקרירות</b>: תצא כה, יח. ראה גם לעיל (בחלק המאמרים) המשך מצה זו ובהערה 560."],["5152","102","<b>בונה ע\"מ לסתור וסותר ע\"מ לבנות</b>: בסה\"מ מלוקט ה' ע' קנו מציין מאמרי אדה\"ז תקס\"ג ח\"ב ע' תשכח. מאמרי אדה\"א דברים ח\"ב ס\"עד תקפב ואילך."],["5153","103","<b>וזאת המצוה. . בארץ שמע ישראל</b>: ואתחנן ו, א [בדילוגים]. ד. ראה לקו\"ת ואתחנן ד, א. ט, א. מאמרי אדה\"א הנחות תקע\"ז ע' רנה. וש\"נ.\n\n<b>ד</b>  אולי כצ\"ל בסה\"מ מלוקט שם.\n\n<b>ג</b>  נמצא גם באו\"ת צג, ג."]]],[2000470530,"הוא חובות הגוף<sup data-n=\"5154\">104</sup> ומה שייך לארץ<sup data-n=\"5155\">105</sup> דוקא, והתירוץ דאפי' מצות שאינו תלויות בארץ מ\"מ בארץ הם באו\"א, וזהו שרצה משה ליכנס לארץ<sup data-n=\"5156\">106</sup> וכי לאכול מפרי' הוא צריך אלא לקיים מצות התלויות בה, וצ\"ל דאפי' מצות שאינם תלויות בארץ נק' ג\"כ תלויות בארץ דעיקר עשייתן הוא בארץ (ה' ואפי' בארץ אינו שלימות עדיין וכמ\"ש על אפי ועל חמתי כו' כנ\"ל וזהו מפני שעברו על ציווי'<sup data-n=\"5157\">107</sup> (אפ\"ל חטא עה\"ד) וכמשנת\"ל ע').\n<b>וזהו</b> אדה\"ר הכנסתיו לג\"ע כו' כך בני הכנסתי לארץ כו', דלא יאמרו דבארץ הוא שלימות העבודה אלא כמו אדה\"ר הכנסתיו לג\"ע כדי שיהי' שלימות ודנתיו בגירושין ובשילוחין מפני שעבר על ציווי' כך בנ\"י הכנסתים לארץ ודנתים בגרושין ובשילוחין וכ\"ז מפני שעברו על ציווי' וקננתי עליהם איכה כמו באדה\"ר שא\"ל איכה וצ\"ל והלא<sup data-n=\"5158\">108</sup> לא ידע אי' מקומו, והמפרשים<sup data-n=\"5159\">109</sup> פי' לכנוס עמו בדברים, ואפ\"ל שא\"ל איך אתה ירדת כ\"כ למדרי' שפלה, וכמו\"כ בנ\"י קוננתי עליהם איכה ישבה בדד, דעליהם נא' הן עם לבדד ישכון<sup data-n=\"5160\">110</sup> והוא מ\"ש ה' בדד ינחנו<sup data-n=\"5161\">111</sup> וזה יהי' לע\"ל ובלעם ראה את זאת ואמר הן עם לבדד ישכון, ועתה איכה ישבה בדד, (ושרש) הענין דהנה כתי' הזורעים בדמעה<sup data-n=\"5162\">112</sup> כו' הלוך ילך ובכה<sup data-n=\"5163\">113</sup> נושא משך הזרע, הנה זריעה הוא מצות<sup data-n=\"5164\">114</sup> וכמ\"ש זרע הקב\"ה התומ\"צ להנחילן לישראל לעוה\"ב<sup data-n=\"5165\">115</sup> ולא הניח דבר שאין בו מצוה, בא לחרוש שדהו לא תחרוש בשור וחמור יחדיו<sup data-n=\"5166\">116</sup> (ה' כמבואר במ\"א ע\"פ בארץ לא זרוע<sup data-n=\"5167\">117</sup> שהלא הוא זרוע, ואפ\"ל דמה שנמשלו מצות לזריעה, כמו שזורעין גרעין בארץ ונרקב שם ואח\"כ צומח מהגרעין, והצמיחה הוא לפ\"ע הרקבון<sup data-n=\"5168\">118</sup> דכל",[["5154","104","<b>ק\"ש הוא חובות<sup data-n=\"e283\">ה</sup> הגוף</b>: ראה קדושין לז, א וברש\"י שם. וראה גם לקו\"ש עקב כרך ט ע' 80 ואילך ובהערות שם. אחרי כרך יז ע' 190."],["5155","105","<b>ומה שייך לארץ</b>: ראה גם לקו\"ת תצא מ, סע\"ד. אוה\"ת חוקת כרך ה ע' א'תרכו<sup data-n=\"e284\">ו</sup>. דברים כרך ד (בהוספות) ע' אתתלג. סה\"מ תרל\"ח ע' רכט. לעיל (בחלק המאמרים) המשך מצה זו כאן על יד הערה 1817."],["5156","106","<b>שרצה משה ליכנס לארץ</b>: ראה סוטה יד, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלז. וש\"נ. תו\"ח וישלח קצד, ג ובהערה 48."],["5157","107","<b>ציווי'</b>: וכ\"ה בסמוך."],["5158","108","<b>והלא</b>: אוצ\"ל: וכי."],["5159","109","<b>והמפרשים</b>: רש\"י שם."],["5160","110","<b>הן עם לבדד ישכון</b>: בלק כג, ט."],["5161","111","<b>ה' בדד ינחנו</b>: האזינו לב, יב."],["5162","112","<b>הזורעים בדמעה</b>: תהלים קכו, ה."],["5163","113","<b>הלוך ילך ובכה</b>: תהלים שם, ו."],["5164","114","<b>זריעה הוא מצות</b>: ראה גם תו\"א שמות נג, ג. לעיל (בחלק המאמרים) המשך מצה זו כאן הערה 1821."],["5165","115","<b>זרע הקב\"ה. . לעוה\"ב</b>: לעיל (בחלק המאמרים) המשך מצה זו כאן מציין: במד\"ר ס\"פ שלח — ראה במדב\"ר פי\"ז, ה<sup data-n=\"e285\">ו</sup>. תנחומא שלח טו."],["5166","116","<b>לא תחרוש בשור וחמור יחדיו</b>: תצא כב, י [ושם: ובחמור]."],["5167","117","<b>בארץ לא זרוע</b>: ירמי' ב, ב [ושם: זרועה]. ראה לקו\"ת פקודי ג, ב. שה\"ש ז, א. תו\"ח פקודי ח\"ב תמג, סע\"ג. תנד, ד. לעיל המשך מצה זו רפ\"מ."],["5168","118","<b>גרעין. . לפ\"ע הרקבון</b>: ראה אגה\"ק ס\"ח (קיג, א). מאמרי אדה\"א ויקרא ח\"ב ע' תקצח. וש\"נ. תו\"ח שמות ח\"א ב, ב. וש\"נ. לעיל הנחה ד\"ה כי טובים דודיך מיין על יד הערה 14. (בחלק המאמרים) המשך מצה זו על יד הערה 1159.\n\n<b>ה</b>  אוצ\"ל: חובת.\n\n<b>ו</b>  במהדורת תשנ\"ח חוקת בהוספות ע' 18 ואילך.\n\n<b>ו</b>  מובא גם בהמשך מים רבים תרל\"ו פצ\"ח ע' קד."]]],[2000470531,"שנרקב יותר צומח ממנו אח\"כ בריבוי יותר (וכמו אחר גלות מצרים הי' מ\"ת ולהגילוי דלע\"ל צריכים גלות כו' שהוא גדול מגלות מצרים<sup data-n=\"5169\">119</sup> ) וכמו\"כ במצות כתי' זורע צדקות<sup data-n=\"5170\">120</sup> מצמיח ישועות (שע\"ה נהורין<sup data-n=\"5171\">121</sup> ) שזרען בארץ והם ישראל שנק' ארץ חפץ<sup data-n=\"5172\">122</sup> כדי שיהי' הצמיחה, ועיקר הצמיחה הוא לפ\"ע הרקבון והוא הביטל לכן ע\"י שעושה המצוה ומבטל א\"ע לאלקות נעשה העלאת מ\"ן, ועי\"ז נעשה הצמיחה הוא המשכות מ\"ד<sup data-n=\"5173\">123</sup>, והנה עיקר הרקבון הוא במל\"ת דוקא שהוא הכפי' וההכרח שלא יעשה ד\"ז כלל א\"כ הביטל גדול יותר ממילא הצמיחה היא ג\"כ בריבוי יותר, וזהו שמי עם י\"ה שס\"ה וזכרי עם ו\"ה רמ\"ח<sup data-n=\"5174\">124</sup> שמ\"ע תלויות בו\"ה שהם זו\"נ ומל\"ת בי\"ה שהם חו\"ב<sup data-n=\"5175\">125</sup> עכ\"ה) בא לבנות בית ועשית מעקה לגגך<sup data-n=\"5176\">126</sup> ומזוזה.\n<b>והנה</b> הניצוצות שנפלו בשבה\"כ נתפזרו וזה שכ' כד' רוחות השמים<sup data-n=\"5177\">127</sup> פרשתי אתכם (וארז\"ל ע\"פ צדקות פרזונו בישראל<sup data-n=\"5178\">128</sup> ) צדקה עשה הקב\"ה עם ישראל שפזרן בין האומות<sup data-n=\"5179\">129</sup>, והוא ללקט הניצוצות, וזהו וילקט יוסף את כל הכסף אשר במצרים<sup data-n=\"5180\">130</sup> הרי שלקט כל הנצוצות דאי' בספרי' דר\"ב נצוצות נפלו במצרים<sup data-n=\"5181\">131</sup>",[["5169","119","<b>ולהגילוי דלע\"ל. . גדול מגלות מצרים</b>: ראה תו\"א וארא נו, ד. תו\"ח שם ח\"א סג, ד. מאמרי אדה\"א הנחות תקע\"ז ע' צו. וש\"נ."],["5170","120","<b>זורע צדקות</b>: ברכת יוצר. ראה גם לעיל בהנחה והמשך שבהערה 118."],["5171","121","<b>שע\"ה נהורין</b>: ראה גם לעיל (בחלק המאמרים) המשך זאת חנוכת המזבח פ\"ז ובהערה 121."],["5172","122","<b>ישראל שנק' ארץ חפץ</b>: מלאכי ג, יב. ראה גם מאמרי אדה\"א דברים ח\"ב ע' שע. וש\"נ תו\"ח ויצא קסח, ב הערה 33."],["5173","123","<b>מ\"ן. . מ\"ד</b>: זהר בראשית יז, סע\"ב. יח, רע\"א. ראה גם בענין מ\"ן ומ\"ד מאמרי אדה\"ז תקס\"ג ח\"א ע' קפג ואילך."],["5174","124","<b>שמי עם י\"ה שס\"ה. . רמ\"ח</b>: ראה שמות ג, טו. ת\"ז בהקדמה ד, סע\"ב. ה, א. לקו\"ת פקודי ג, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ג ע תתקי. וש\"נ. תו\"ח בא ח\"א קיד, א. וש\"נ. סה\"מ תרכ\"ז ע' קכט. וש\"נ. תרל\"ח ע' שיב."],["5175","125","<b>בו\"ה שהם זו\"נ. . בי\"ה שהם חו\"ב</b>: ראה זהר רעיא מהימנא פינחס רמג, רע\"א. אגה\"ת פ\"ד."],["5176","126","<b>ועשית מעקה לגגך</b>: תצא כב, ח."],["5177","127","<b>כד' רוחות השמים</b>: זכרי' ב, י. ראה גם סידור שחרית סז, ד. מאמרי אדה\"א דברים ח\"ד ע' תס ואילך."],["5178","128","<b>צדקות פרזונו בישראל</b>: ס' שופטים ה, יא."],["5179","129","<b>צדקה עשה הקב\"ה. . האומות</b>: ראה פסחים פז, ב. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה וזהו שרש יונתי על יד הערה 19. תו\"ח שמות ח\"א מ, ג ואילך ובהנסמן שם."],["5180","130","<b>וילקט יוסף. . אשר במצרים</b>: ויגש מז, יד<sup data-n=\"e286\">ז</sup>. ראה מג\"ע מקץ<sup data-n=\"e287\">ח</sup> אופן י\"ז. מאמרי אדה\"א בראשית ע' תפט ואילך. אה\"ת מקץ כרך ו ע' תתשה ואילך. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' ז ואילך. סה\"מ מלוקט ה' ע' רנט ואילך<sup data-n=\"e288\">ט</sup>. וש\"נ."],["5181","131","<b>דאי' בספרי' דר\"ב נצוצות נפלו במצרים</b>: ראה תו\"ח שמות ח\"א לט, סע\"ג: נהר נילוס (שנפלו שם כל ניצוצות דתהו שנפלו בדור הפלגה ועוד נשמות. בהערה הבאה.\n\n<b>ז</b>  <b>ושם</b>: הנמצא בארץ מצרים.\n\n<b>ח</b>  מהדו\"ת ברוקלין תשל\"ז ע' קפו ד\"ה גם.\n\n<b>ט</b>  <b>ושם וכן במפתח הפסוקים (לשם ובכרך ו) צ\"ל</b>: ויגש מז, יד."]]],[2000470532,"ובררו אותם במצרים וזהו וגם ערב ר\"ב עלו אתם<sup data-n=\"5182\">132</sup> הם ר\"ב ניצוצות, והבירור הוא ע\"י המצות הגם דכתי' ראשו פ\"ז<sup data-n=\"5183\">133</sup> דממ\"ע לא נשאר לנו רק פ\"ז מצות<sup data-n=\"5184\">134</sup> צ\"ל דשאר המצות נבררו כבר ואותן שנשארו צריכים לבררם, והנה עיקר ירידות המל' הוא עתה<sup data-n=\"5185\">135</sup>, דבזמן שהי' בהמק\"ד קיים הי' הבירורים ע\"י הקרבנות וזהו העשן שעולה מן הקרבנות<sup data-n=\"5186\">136</sup> דכל דבר מורכב מד' יסודות<sup data-n=\"5187\">137</sup> והעפר נשאר באפר ואר\"מ יוצאים בהעשן<sup data-n=\"5188\">138</sup> וזהו\"ע הבירורים, אך משחרב בהמק\"ד צ\"ל ירידות עצם המל' לברר בירורים וזהו מ\"ש בכה תבכה בלילה<sup data-n=\"5189\">139</sup> על בית ראשון וב\"ש וכמ\"ש ונהר יחרב ויבש<sup data-n=\"5190\">140</sup>, יחרב בב\"ר ויבש בב\"ש והוא כמ\"ש חרבה המים<sup data-n=\"5191\">141</sup> יבשה הארץ<sup data-n=\"5192\">142</sup>, והי' שהיות זמן ביניהם, דחרב היינו שיש קצת לחלוחית עדיין ויבשה הוא שנתיבש לגמרי, דבב\"ש חסרו ה' דברים<sup data-n=\"5193\">143</sup> שהם עקרים.\n<b>וזהו</b> היתה לי דמעתי לחם<sup data-n=\"5194\">144</sup> יומם ולילה באמר אלי כל היום אי' אלקיך, פי' כאדם שאומר הלחם שלי הוא הדמעה, באמר אלי כל היום אי' אלקיך דבישראל העיקר הוא הבטחון, וזהו אי' אלקיך דאותותינו לא ראינו<sup data-n=\"5195\">145</sup>, אלביש שמים קדרות<sup data-n=\"5196\">146</sup> ושק אשים כסותם, אך באמת אינו כן וכמ\"ש אכן אתה אל מסתתר<sup data-n=\"5197\">147</sup>, אדרבה הכח ההסתר הוא למעלה מכח הגילוי. וזהו הזורעים בדמעה ברנה יקצרו כו' בא יבוא ברנה נושא אלומותיו<sup data-n=\"5198\">148</sup>, כמו עד\"מ כשאדם זורע אינו יודע אם יצמח, הגם שבשנה העברה צמחה הרבה אך אפשר שעתה לא יצמח, דיש שנה שצומח הרבה ויש שצומח מעט ויש שאינו צומח כלל, אבל בשעה שקוצר ונושא אלומותיו דהדרך שקוצרין תחילה ואח\"כ עושין אלומות ומאספים אותם למ\"א ומכניסים לגורן, וזהו בא יבא שבא למעלה מעלה, ומ\"ש ברנה הוא שמחה שאחר העצב<sup data-n=\"5199\">149</sup> וע\"ד הקבלה",[["5182","132","<b>וגם ערב ר\"ב עלו אתם</b>: ראה בא יב, לח. לעיל (בחלק המאמרים) המשך מצה זו הערה 388."],["5183","133","<b>ראשו פ\"ז</b>: שה\"ש ה, יא [בדילוג]."],["5184","134","<b>נשאר לנו רק פ\"ז מצות</b>: ראה מאמרי אדה\"א קונטרסים ע' רסו. וש\"נ. סה\"מ תרכ\"ז ע' שעט. וש\"נ."],["5185","135","<b>עיקר ירידות המל' הוא עתה</b>: ראה תו\"א מקץ לח, א. לקו\"ת במדבר ג, ד ואילך."],["5186","136","<b>הבירורים. . העשן שעולה מן הקרבנות</b>: ראה (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1835."],["5187","137","<b>דכל דבר מורכב מד' יסודות</b>: ראה רמב\"ם רפ\"ד מהל' יסוה\"ת."],["5188","138","<b>והעפר. . ואר\"מ יוצאים בהעשן</b>: ראה גם אגה\"ק סט\"ו. סה\"מ תרל\"ח ע' רצו. וש\"נ."],["5189","139","<b>בכה תבכה בלילה</b>: איכה א, ב. סנהדרין קד, ב. ראה גם אוה\"ת איכה כרך ב ע' א'ג."],["5190","140","<b>ונהר יחרב ויבש</b>: איוב יד, יא. ראה זהר בהקדמה ו, ב. בראשית כו, א. שמות ט, ב. (לעיל בחלק המאמרים) המשך מצה זו כאן הערה 1746."],["5191","141","<b>חרבה המים</b>: נח ח, יג [שם: חרבו]. ראה מאמרי אדה\"א במדבר ח\"ב ע' תרלו. תו\"ח בשלח ח\"א קנג, ב ובהערה לשם. סה\"מ תרכ\"ט ע' רצה."],["5192","142","<b>יבשה הארץ</b>: שם ח, יד."],["5193","143","<b>דבב\"ש חסרו ה' דברים</b>: יומא כא, ב. ראה לקו\"ת ר\"ה נז, ג."],["5194","144","<b>היתה לי דמעתי לחם</b>: תהלים מב, ד."],["5195","145","<b>דאותותינו לא ראינו</b>: תהלים עד, ט. ראה גם לעיל הנחה ד\"ה מזבח אדמה תעשה לי על יד הערה 68."],["5196","146","<b>אלביש שמים קדרות</b>: ישעי' נ, ג."],["5197","147","<b>אכן אתה אל מסתתר</b>: ישעי' מה, טו. ראה גם לעיל הנחה ד\"ה אי' וכו' נביאים וכתובים ובהערה 33."],["5198","148","<b>בא יבוא. . אלומותיו</b>: תהלים קכו, ו."],["5199","149","<b>ברנה הוא שמחה שאחר העצב</b>: ראה אוה\"ת (יהל אור) תהלים ע' שעד."]]],[2000470533,"הוא גבורות דאימ'. וזהו העם ההולכים בחשך<sup data-n=\"5200\">150</sup> ראו אור גדול, מפני שהלכו בחשך לכן ראו אור גדול.\n<b>וזהו\"ע</b> נר חנוכה מצותה משתשקע<sup data-n=\"5201\">151</sup>, שנשקע שמש הוי', וכמ\"ש אל תראוני שאני שחרחורת שזפתני השמש דאסתלק שימשא מני', והיינו אף כשיתבונן איך דאני ה' לא שניתי<sup data-n=\"5202\">152</sup> ואתה הוא קודם שנברה\"ע<sup data-n=\"5203\">153</sup> כו' מ\"מ ואתם בנ\"י לא כליתם<sup data-n=\"5204\">154</sup> שלא באו לכלות הנפש, וזהו משתשקע, שנשקע לגמרי כמו טבעו<sup data-n=\"5205\">155</sup> כו', אז צריכים להדליק נ\"ח שיש בהם שמן ופתילה ותרי גוונא אור הם פנימים ומקיפים ושמן ופתילה הוא להמשיך האור למטה ומצותה להניח על פתח הבית מבחוץ<sup data-n=\"5206\">156</sup> דוקא במקום החשך יאיר האור שהחשך יהי' אור, והזמן הוא עד שתכלה רגל מן השוק, עד דכלי' רגלי דתרמודאי<sup data-n=\"5207\">157</sup>, דכ\"ז שיש בנ\"א בשוק אין המזיקין שולטים כ\"כ אבל אח\"כ אינו שייך בירורים, וזהו\"ע ז' מצות דרבנן<sup data-n=\"5208\">158</sup> דערבים עלי דברי דודיך יותר מיינה ש\"ת<sup data-n=\"5209\">159</sup>, בינה יתירה ניתנה באשה<sup data-n=\"5210\">160</sup>, והוא סופר וספר<sup data-n=\"5211\">161</sup>, דס\"ת הוא בינה<sup data-n=\"5212\">162</sup> ומי שכותב את הספר הוא בינה יתירה, וכמו\"כ כאן ע\"י הזורעים בדמעה כו' בא יבא ברנה. ומה שישראל דוקא הם המבררים דהנה כתי' כי יעקב בחר לו יה ישראל לסגולתו<sup data-n=\"5213\">163</sup>, דדוקא ישראל שעושה מצוה<sup data-n=\"5214\">164</sup> אז הוא מצוה אבל לא או\"ה<sup data-n=\"5215\">165</sup> (ה' וכמ\"ש כי תהיו אתם ארץ חפץ<sup data-n=\"5216\">166</sup> דוקא ע') אדרבה גוי ששבת<sup data-n=\"5217\">167</sup> חייב מיתה דלא ישבותו, לבד ז' מצות ב\"נ<sup data-n=\"5218\">168</sup> יכולים הם ג\"כ",[["5200","150","<b>העם ההולכים בחשך</b>: ישעי' ט, א. ראה גם לעיל (בחלק המאמרים) המשך מצה זו על יד הערה 1177."],["5201","151","<b>נר חנוכה מצותה משתשקע</b>: ראה שבת כא, ב. לעיל הנחה ד\"ה ואלא עלמא אמאי קאים על יד הערה 29 ואילך."],["5202","152","<b>דאני ה' לא שניתי</b>: מלאכי ג, ו."],["5203","153","<b>ואתה הוא קודם שנברה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["5204","154","<b>ואתם בנ\"י לא כליתם</b>: המשך הכתוב אני ה' לא שניתי. ראה תו\"א יתרו סז, א. תו\"ח שמות ח\"א ז, ג. וש\"נ. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 663."],["5205","155","<b>טבעו</b>: בשלח טו, ד. תהלים ט, טו. איכה ב, ט."],["5206","156","<b>ומצותה להניח על פתח הבית מבחוץ</b>: שבת כא, ב."],["5207","157","<b>עד שתכלה. . דכלי' רגלי דתרמודאי</b>: שבת שם."],["5208","158","<b>ז' מצות דרבנן</b>: נסמן לעיל בהנחה ד\"ה סמכוני באשישות הערות 82-83."],["5209","159","<b>דערבים עלי. . מיינה ש\"ת</b>: ע\"ז לה, א וברש\"י שם."],["5210","160","<b>בינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. ב\"ר רפי\"ח."],["5211","161","<b>סופר וספר</b>: ראה ס\"י בתחילתו."],["5212","162","<b>דס\"ת הוא בינה</b>: ראה זהר ויקהל דף ר, א. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"ד. וש\"נ."],["5213","163","<b>כי יעקב. . לסגולתו</b>: תהלים קלה, ד."],["5214","164","<b>דדוקא ישראל שעושה מצוה</b>: ראה תו\"א שמות נג, ד (ובהנסמן בריש המאמר שם). יתרו סח, ב. ע, ד. עב, ב. בהערה הבאה."],["5215","165","<b>אבל לא או\"ה</b>: ראה לעיל הנחה ד\"ה בן פורת יוסף הא' ובהערה 57."],["5216","166","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב. מובא גם לעיל שם על יד הערה 53."],["5217","167","<b>גוי ששבת</b>: סנהדרין נח, סע\"ב. ראה גם לקמן (בחלק הנחות) הנחה ד\"ה הנה אנכי כורת על יד הערה 57."],["5218","168","<b>ז' מצות ב\"נ</b>: ראה סנהדרין נו, סע\"א. רמב\"ם הל' מלכים רפ\"ט."]]],[2000470534,"לברר<sup data-n=\"5219\">169</sup>, וזהו כמו סגולה שא\"י טעמה רק שהוא סגולה כמו\"כ כאן דוקא ישראל הם המבררים, וזהו הזורעים בדמעה ע\"י הזריעה בדמעות וכמ\"ש בכה תבכה בב\"ר וב\"ש עי\"ז דוקא אח\"כ בא יבא ברנה.\n[בגוכתי\"ק הניח 2 שורות פנוי ואח\"כ נרשם]\nאברהם המשיכו ברקיע הא'<sup data-n=\"5220\">170</sup> כו' עד משה המשיכו למטה.\n<b>(דבהמ\"ק</b> הי' דירת עראי וכמ\"ש ואהי' מתהלך במשכן ובאהל<sup data-n=\"5221\">171</sup> אבל לע\"ל יהי' דירת קבע)",[["5219","169","<b>ז' מצות. . יכולים. . לברר</b>: ראה גם ש\"א צב, א. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע על יד הערה 177 ואילך."],["5220","170","<b>אברהם המשיכו ברקיע הא'</b>: אולי הכוונה מלמעלה למטה. ראה מאמרי אדה\"א בראשית ע' רלד. סה\"מ תרע\"ח ע' רעא."],["5221","171","<b>ואהי' מתהלך במשכן ובאהל</b>: שמואל-ב ז, ו [ושם: באהל ובמשכן]."]]],[2000470535,"<h3>מי כהוי' אלקינו המגביהי לשבת</h3>\n<b></b><b>הנחה בס\"ד פ' נח שנת תר\"מ</b>\nנח\n<b>מי</b> כהוי' אלקינו<sup data-n=\"5222\">1</sup> המגביהי לשבת<sup data-n=\"5223\">2</sup> והמשפילי לראות בשמים וארץ<sup data-n=\"5224\">3</sup> וצ\"ל פי' המגביהי ומשפילי, וגם צ\"ל הקישור וחיבור דהמגביהי עם המשפילי. והענין דהנה פסוק זה הוא תשובה על הפסוק הקודם כי בתחילה כתי' רם על כל גוים<sup data-n=\"5225\">4</sup> כו' והוא הדיעה האומרת עזב ד' את הארץ<sup data-n=\"5226\">5</sup> כו', ולזה אומר הפ' תשובה ע\"ז שאדרבה שלפי שהוא מגביהי הוא משפילי בשמים וארץ בשוה<sup data-n=\"5227\">6</sup> להוציא מאותו הדיעה. ולהבין זה צ\"ל תחילה ענין ר\"ח בכלל דהנה עיקר ענין קריאת שם ראש חודש הוא ע\"ש שהוא ראש לכל החדש<sup data-n=\"5228\">7</sup> כמו שהראש הוא הראש לכל הגוף וכמו שבגוף האדם הראש הוא כלל והאברים הם פרטים, כמו\"כ השלשים יום הם פרטים ור\"ח הוא כלל, ע\"ד שראש השנה הוא כלל אלא שר\"ה הוא כלל לשנה תמימה ור\"ח הוא כלל לחדש. וצ\"ל למה נתנו היו\"ט דר\"ח לנשים<sup data-n=\"5229\">8</sup> דוקא שהם אסורים במלאכה והלא מ\"ע שהזמן גרמא נשים פטורות<sup data-n=\"5230\">9</sup>. ויש ע\"ז הרבה טעמים, וטעם א' הוא לפי שתחת הזמן אשה משועבדת לבעלה<sup data-n=\"5231\">10</sup>, אך עכ\"פ אנו רואים שהמצות שהם רמים ונפלאים כמו שופר סוכה לולב נשים פטורות<sup data-n=\"5232\">11</sup> ור\"ח הוא ג\"כ בזמן דוקא כי יום א' לפני ר\"ח ויום לאחר ר\"ח אינו שייך ליו\"ט דר\"ח כ\"א בזמן ר\"ח דוקא, ואף שאיסור המלאכה בר\"ח הוא רק מנהג אבל מ\"מ הרי הוא מנהג גמור כמ\"ש בפרד\"א ובירושלמי<sup data-n=\"5233\">12</sup> וא\"כ למה ניתן לנשים דוקא. והנה בפרד\"א אי' טעם ע\"ז כי בשעה שהטעו הערב רב לישראל לעשות העגל ואח\"כ אמרו להם פרקו נזמי הזהב<sup data-n=\"5234\">13</sup>, לא נתנו הנשים ולכן ניתן להם השכר בעד זה יו\"ט של ר\"ח. וצ\"ל למה ר\"ח דוקא הוא השכר על מניעות עשיית העגל. וצ\"ל ענין העגל דהנה בעגל כתיב שאמרו אלה אלקיך ישראל<sup data-n=\"5235\">14</sup> אשר העלוך מארץ מצרים, וצ\"ל הלא העגל נעשה ממה שהתיכו זהב, והלא מי שיש לו איזה שמץ וקצת דעת יבין זאת שאין שייך על מתכות או זהב מהותך לאמר אלה אלקיך, ובפרט דור המדבר שהי' דור דיעה<sup data-n=\"5236\">15</sup>",[["5222","1","<b>מי כהוי' אלקינו</b>: הנחה ממאמר ד\"ה לה\"ע ר\"ח שנדפס לעיל בחלק המאמרים. וש\"נ."],["5223","2","<b>מי. . המגביהי לשבת</b>: תהלים קיג, ה."],["5224","3","<b>והמשפילי. . וארץ</b>: תהלים שם, ו [ושם: המשפילי. . ובארץ]."],["5225","4","<b>רם על כל גוים</b>: שם שם, ד."],["5226","5","<b>עזב ד' את הארץ</b>: יחזקאל ח, יב. ט, ט."],["5227","6","<b>שלפי שהוא מגביהי. . בשוה</b>: ראה גם לקמן פיסקא וזהו מה. (לעיל בחלק המאמרים) מאמר לה\"ע ר\"ח כאן ובהערה 26."],["5228","7","<b>ר\"ח. . ראש לכל החדש</b>: ראה לקו\"ת ר\"ה נח, א. (לעיל בחלק המאמרים) בהמאמר כאן הערה 2."],["5229","8","<b>למה נתנו. . לנשים</b>: ראה ירושלמי פסחים רפ\"ד. פדר\"א פמ\"ה וברד\"ל שם. רש\"י מגילה כב, ב ד\"ה ראשי חדשים. אוה\"ת חנוכה כרך ה' ע' 1864 הובא לקמן במאמר ד\"ה רני ושמחי על יד הערה 52 ואילך. לקו\"ש ר\"ח תמוז כרך ח ע' 315 הערה 8."],["5230","9","<b>מ\"ע שהזמן גרמא נשים פטורות</b>: קדושין כט, א במשנה. ראה גם סה\"מ תרל\"ח ע' קנח ואילך. וש\"נ."],["5231","10","<b>שתחת הזמן אשה משועבדת לבעלה</b>: ראה אבודרהם סדר תפלות של חול (ירושלים תשכ\"ג ע' כה ד\"ה כל. ובהערת המו\"ל שם תה, א)."],["5232","11","<b>שופר סוכה לולב נשים פטורות</b>: ראה שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ט, ס\"ב. הל' סוכה רסתר\"מ. הל' ציצית סי\"ז, ס\"ג."],["5233","12","<b>בפרד\"א ובירושלמי</b>: נסמן לעיל הערה 8."],["5234","13","<b>פרקו נזמי הזהב</b>: ל' הכתוב תשא לב, ב."],["5235","14","<b>אלה אלקיך ישראל</b>: תשא שם, ד. ח."],["5236","15","<b>דור דיעה</b>: ראה זהר בשלח סב, ב. פע\"ח שחה\"מ שכ\"א, פ\"א. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה והנה כובע על יד הערה *109: הצד\"ג."]]],[2000470536,"האיך אפ\"ל שטעו כ\"כ בעגל הגשמי הנעשה מזהב לומר שזה אלקה, ובפרט לומר שהוא הוציא את בנ\"י ממצרים, והלא הם ראו בראי' חושיות האותות והמופתים שעשה הקב\"ה בהוציאם ממצרים ואיך יחליפו אותו בעגל מזהב לומר שהוא המוציא אתכם מארץ מצרים.\n<b>אך</b> הענין דהנה פרעה אמר לא ידעתי את הוי' כו' מי הוי'<sup data-n=\"5237\">17</sup> כו'. והענין דהנה כל האומות הכופרים בהקב\"ה אינם כופרים לגמרי<sup data-n=\"5238\">16</sup> כ\"א שהם כופרים בהשגחה פרטיות, כי זה הם מודים שמאמיתית המצאו<sup data-n=\"5239\">18</sup> נמצאו כל הנמצאים והוא ברא את הכל מאין ליש והוא יחיד ונצחי, אך שהם כופרים בהשגחה פרטי' שאומרים רם על כל גוים, עזב את הארץ, שטענתם הוא שהשפלה וירידה לפניו להשפיל א\"ע להחיות כל עולמות השפלים ולהשגיח על כל פרטיהם, וזהו שאומרים על השמים כבודו כי אין הפי' שמים גשמי' כ\"א שמים רוחניות וארץ הוא גשמי' ואומרים לפי טעותם שברוחני' הוא משגיח על כל פרט אבל בגשמי' השפלה לפניו להשגיח עליהם, וזהו פי' רם הוי' על כל גוים על השמים כו' דכמו שגבוה שמים מארץ כמ\"ש כי כגבוה שמים מארץ<sup data-n=\"5240\">19</sup> וכתיב שמים לרום<sup data-n=\"5241\">20</sup>, כמו\"כ הוא ריחוק הערך גשמי' מרוחני' ולכן אומרים כי רם כו' על השמים כו' אבל הארץ עזב ביד צבא המזלות וכמארז\"ל אין לך עשב<sup data-n=\"5242\">21</sup> מלמטה שאין לו מזל המכה בו ואומר לו גדל שכל עשב וכל אילן פרטי יש לו מזל פרטי אבל הם אומרים שעזב הקב\"ה ביד צבא המזלות לעשות כאות נפשם ורצונם ואין לו חלק בהם, וזהו טעות גמור כי המזלות אינם אלא שלוחי השפע, והגם דכתיב ממגד תבואות שמש<sup data-n=\"5243\">22</sup> וממגד גרש ירחים אין זה כ\"א שע\"י עובר השפע וכל צבא מעלה אינם אלא כגרזן ביד החוצב<sup data-n=\"5244\">23</sup> בו היתכן לומר שהגרזן הוא הפועל והעושה הלא העושה והפועל אינו אלא האדם או למשל כלי המחרישה שבו חורשים היתכן לומר שהם פועלים כלום אלא שבהם וע\"י עושה האדם כחפצו וכרצונו.\n<b>וזהו</b> מה שנ\"י אומרים מי כהוי' אלקינו המגביהי לשבת שלפי שהוא מגביהי שהוא מרומם ומנושא מכללות כולם ושוה לפניו שמים וארץ רוחני' וגשמי' דכמו שגשמי' השפלה לפניו ית' כמו\"כ רוחני' השפלה לפניו בשוה ממש. והנה גם לפי טעותם הרי הם מודים שהוא משגיח ברוחני' כמו\"כ הוא משגיח על פרט ופרט",[["5237","17","<b>לא ידעתי. . מי הוי'</b>: שמות ה, ב [בהיפך הסדר]."],["5238","16","<b>פרעה. . אינם כופרים לגמרי</b>: ראה ספר הערכים חב\"ד כרך ב מערכת אוה\"ע ע' רעז ואילך."],["5239","18","<b>שמאמיתית המצאו</b>: ראה רמב\"ם ריש הל' יסוה\"ת."],["5240","19","<b>כי כגבוה שמים מארץ</b>: תהלים קג, יא."],["5241","20","<b>שמים לרום</b>: משלי כה, ג."],["5242","21","<b>אין לך עשב</b>: ראה אוה\"ת וארא כרך ח ע' ב'תתפג שמציין: הובא בר\"ח פ\"ה משער האהבה והוא במ\"ר בראשי' פ\"י[, ו]. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג."],["5243","22","<b>ממגד תבואות שמש</b>: ברכה לג, טו [ושם: וממגד]."],["5244","23","<b>כגרזן ביד החוצב</b>: מו\"נ ח\"ג פכ\"ט. זהר בראשית לו, א. ישעי' י, טו."]]],[2000470537,"בגשמי' כי הרי רוחני' וגשמי' שוין לפניו, וזהו משארז\"ל ע\"פ כי ממזרח שמש עד מבואו גדול שמי ומהולל בגוים ובכל מקום מוקטר ומוגש לשמי<sup data-n=\"5245\">24</sup> דקרו לי' אלקא דאלקי'<sup data-n=\"5246\">25</sup>, פי' אלקייא הוא הכח כי אלקים הוא מלשון כ\"ח וכמ\"ש ואת אילי הארץ<sup data-n=\"5247\">26</sup> כו' והוא לפי דבריהם ולפי טעותם שניתן הכח לצבא המזלות לעשות כאות נפשם והקב\"ה הוא אלקי אלקים וכמ\"ש הודו לאלקי האלקים<sup data-n=\"5248\">27</sup> ועזב להם את ההנהגה כי הרי הם מקבלים רק מצבא המזלות, ולכן יש מדינה אחת במדינת יוון אשר מושליהם ע\"פ רוב הם נשים כי שם הוא מזל בתולה והם מקבלים מהמזלות<sup data-n=\"5249\">28</sup>. ובזה יובן מ\"ש במצרים למען תדע כי אין כמוני בכל הארץ<sup data-n=\"5250\">29</sup>, ולכאורה תיבת בכל הארץ הרי הוא מיותר כי עיקר הסיפור הוא לידע שאין כמוהו. אך הענין דהנה בשמים הרי גם הם מודים שהוא המנהיג והוא המשגיח, אלא שהם כופרים ואומרים שעזב את הארץ, ולכן עשה הקב\"ה אותות ומופתים בארץ שעשה שינוי הטבע בארץ כחפצו וכרצונו ועי\"ז ידעו כי גם בארץ הוא משגיח וזהו כי אין כמוני בכל הארץ וכמ\"ש ולמען ספר שמי כי אין כמוני בכל הארץ<sup data-n=\"5251\">30</sup>. וזהו מ\"ש וידעת היום<sup data-n=\"5252\">31</sup> והשבות אל לבבך כי הוי' הוא האלקים בשמים ממעל ועל הארץ מתחת אין עוד והענין דהנה אלקים הוא מלשון כח<sup data-n=\"5253\">32</sup> והוא מקור כל הכוחות הנשפעים ומחמת שם אלקים נעשה ריבוי התחלקות הנבראים כי אלקים הוא לשון רבים<sup data-n=\"5254\">33</sup>, ובא הציווי ע\"ז לידע כי לא שם אלקים בלבד הוא העושה כ\"א ש' הוי' ובאמת ש' הוי' ואלקים כולא חד<sup data-n=\"5255\">34</sup>. וזהו מ\"ש רבות עשית<sup data-n=\"5256\">35</sup> אתה ה' אלקי דהנה ריבוי התהוות הנבראים שנעשה מש' אלקים והוא ע\"י ש' הוי' שהוא העושה והמהוה ע\"י ש' אלקים, וזהו ה' אלקי.\n<b>וזהו</b> וידעת כי הוי' הוא האלקים בשמים ממעל וכו' ועל הארץ מתחת שעיקר מצות הידיעה הוא לידע דכמו שהוי' הוא האלקים בשמים ממעל כמו\"כ הוא בארץ מתחת שגם בארץ הגשמי' עיקר המהוה והמחי' הוא ש' הוי' והוא המשגיח בכל מעשה התחתונים, ואמרו אין עוד הוא עוד ענין אחד דהיינו שאין דבר נוסף על עצמותו ח\"ו והוא להוציא ג\"כ ענין השיתוף<sup data-n=\"5257\">36</sup> דענין השיתוף הוא כמארז\"ל שלש",[["5245","24","<b>כי. . עד. . ומהולל. . ומוגש לשמי</b>: מלאכי א, יא [ושם: ועד. תיבת ומהולל ליתא. מוגש]."],["5246","25","<b>דקרו לי' אלקא דאלקייא</b>: מנחות בסופה. ראה סה\"מ תרל\"ב ח\"א ע' נג בהערה."],["5247","26","<b>ואת אילי הארץ</b>: יחזקאל יז, יג."],["5248","27","<b>הודו לאלקי האלקים</b>: תהלים קלו, ב."],["5249","28","<b>במדינת. . יוון. . מהמזלות</b>: ראה גם (לעיל בחלק המאמרים) מאמר לה\"ע ר\"ח כאן ובהערה 22."],["5250","29","<b>למען תדע. . הארץ</b>: וארא ט, יד."],["5251","30","<b>ולמען ספר. . הארץ</b>: וארא שם, טז [בהוספת תיבות: כי אין כמוני]."],["5252","31","<b>וידעת היום</b>: ואתחנן ד, לט. ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה סמוכים לעד פ\"ב."],["5253","32","<b>אלקים. . כח</b>: ראה שו\"ע אדה\"ז דין כוונת הברכות ס\"ה, ס\"ג. תו\"ח וארא ח\"א עה, ב. וש\"נ."],["5254","33","<b>אלקים. . רבים</b>: רש\"י וירא כ, יג. וישלח לה, ז. ראה תו\"א וארא נו, ב. תו\"ח שם ס, א ואילך. לקו\"ת אמור לא, ג."],["5255","34","<b>הוי' ואלקים כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, א ואילך. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. תו\"ח וארא ח\"א ס, א. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תה ואילך. וש\"נ."],["5256","35","<b>רבות עשית</b>: תהלים מ, ו."],["5257","36","<b>אין עוד. . ענין השיתוף</b>: ראה סה\"מ תרכ\"ט ע' קנה ואילך ובהנסמן שם. סה\"מ מלוקט א' ע' נה."]]],[2000470538,"שותפים באדם<sup data-n=\"5258\">37</sup> אב ואם והקב\"ה, והגם שחלק אב ואם אין ערוך לגבי חלק הקב\"ה מ\"מ נק' בשם שותפים מפני שהם בעלי בחירה<sup data-n=\"5259\">38</sup> והרי יכול לבחור שלא לישא אשה ולא להוליד בנים וכאשר בחר לישא אשה והוליד בנים נק' עש\"ז בשם שותף, אבל צבא מעלה אינו כן כי אינם בעלי בחירה כלל והם רק כגרזן ביד החוצב בו, וכמו שלא שייך לומר שכלי המחרישה הוא שותף עם האדם העושה בו וע\"י, שהרי האדם יוכל בידים ג\"כ לחרוש אלא שהוא ברוב טורח וריבוי זמן ולא יהי' כ\"כ בעומק וע\"י כלי המחרישה יהי' במהירות ובנקל ובעומק יותר, וכמו הגרזן שחוצבים בו וע\"י אבנים מהר הרי יוכל ג\"כ באצבעות ידיו לעקור את האבן מההר אלא שיהי' ברוב טרחה, וא\"כ אין נופל כלל עליהם לומר שהם שותפים להאדם, וכמו\"כ כל צבא מעלה אינם אלא כגרזן ביד החוצב בו שאינם בעלי בחירה כלל וכלל כמו הגרזן שאנו רואים שהאדם כאשר ירצה וחוצב בהגרזן ואם לא ירצה לא יחצוב בו, אבל הגרזן גם אם ירצה לחצוב לא יפעול כלום, כמו\"כ הם צבא מעלה שאין בהם ממש מצד עצמם אלא כגרזן ביד החוצב בו, ומה שארז\"ל אין אומן בלא כלים<sup data-n=\"5260\">39</sup> אין הפי' שבלא כלים אינו אומן כלל, כי אם אין לו כלים ה\"ה ג\"כ אומן, אלא שהכלים הם המביאים את אומנות האומן מהעלם אל הגילוי, כי בלא כלים הלא לא ניכר פלאות<sup data-n=\"5261\">*40</sup> האומן והרי הוא כמו שאינו אומן כלל כי מאי נפ\"מ אם הוא אומן או לאו אם אינו מוציא אומנותו מהעלם אל הגילוי שיהי' ניכר הפעולה שלו אבל באמת הכלים הם רק כמו צבת שבהם וע\"י יאחוז האומנות של האומן.\n<b>וזהו</b> מ\"ש אין עוד כי מלבד שלא להם לבד ניתן הכח להשגיח על מעשה התחתונים עוד זאת שגם בש' שותפים ג\"כ לא יקראו שאינם דבר נוסף על עצמותו כי אין בהם ממש כלל וכלל, אלא הקב\"ה בלבדו הוא המשגיח על כל פרט ופרט, ובדרך כלל יש דומם צומח חי מדבר ובדומם יש הרבה מינים לאין שיעור<sup data-n=\"5262\">40</sup> וכמו\"כ בכל מין ומין יש ריבוי פרטים, וכמו\"כ הוא בצומח וחי, והקב\"ה בעצמו הוא המשגיח על כל פרטי פרטיות המין, וכמ\"ש המחדש בטובו<sup data-n=\"5263\">41</sup> בכל יום תמיד מעשה בראשית שבטובו שלו העצמי' ממש מחדש מע\"ב דכמו שבתחילת הבריאה הי' ע\"י טבע הטוב להטיב<sup data-n=\"5264\">42</sup> כמ\"כ הוא עכשיו ממש שהוא מהוה ומחי' ומשגיח בכל רגע ורגע, אלא דמ\"ש בכל יום הוא דבכדי שיבין האדם זאת הוא בנקל להבין יותר מכל יום, דכמו שבתחילת הבריאה הי' כברייתו של עולם",[["5258","37","<b>שלש שותפים באדם</b>: ראה נדה לא, א. מאמרי אדה\"א דברים ח\"ב ע' תקנ. ח\"ד ע' א'רז. קונטרסים ע' קו. הנחות תקע\"ז ע' רעח."],["5259","38","<b>שותפים. . בעלי בחירה</b>: ראה גם לקו\"ש יתרו כרך לו ע' 90 ואילך."],["5260","39","<b>אין אומן בלא כלים</b>: פמ\"ג לאו\"ח (בהקדמה) באגרת הראשונה."],["5261","*40","<b>פלאות</b>: אולי צ\"ל: פעולת."],["5262","40","<b>ובדומם. . לאין שיעור</b>: ראה גם (לעיל בחלק המאמרים) מאמר ד\"ה ואעשך לגוי גדול ובהערה 37."],["5263","41","<b>המחדש בטובו</b>: ברכת יוצר. ראה גם לעיל ע' ה. וש\"נ. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויאמר כו' לך לך על יד הערה 84."],["5264","42","<b>טבע הטוב להטיב</b>: ראה עמק המלך שער שעשועי המלך בתחילתו. שומר אמונים ויכוח שני סי\"ד. שער היחוה\"א פ\"ד ובמ\"מ הגהות והע\"ק לשם. ולהעיר משו\"ת חכם צבי סי\"ח."]]]]});
